-- إزالة الإحالات إلى «الكتاب/المذكرة/الشكل» من نص 385 سؤالًا في كيمياء 3 و2-1. مولّد آليًا بـ scripts/apply-question-edits.mjs.
-- محروس: يعدّل السؤال فقط إن كان نصه الحالي هو النص القديم، فلا يمس سؤالًا عدّلته يدويًا. لا يغيّر الاعتماد ولا المفاتيح. آمن للتكرار.
begin;
update public.question_answers set explanation = 'المحاليل مخاليط متجانسة تحتوي على مادتين أو أكثر تسمى المذاب والمذيب؛ فالمخاليط المتجانسة هي المحاليل.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O02' and q.type = 'mcq' and q.number = 2) and explanation = 'يذكر الكتاب أن المحاليل مخاليط متجانسة تحتوي على مادتين أو أكثر تسمى المذاب والمذيب؛ فالمخاليط المتجانسة هي المحاليل.';
update public.question_answers set explanation = 'هناك نوعان من المخاليط غير المتجانسة، هما المعلق والغروي.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O02' and q.type = 'mcq' and q.number = 3) and explanation = 'يذكر الكتاب أن هناك نوعين من المخاليط غير المتجانسة، هما المعلق والغروي.';
update public.question_answers set explanation = 'النيتينول محلول صلب يتكون من التيتانيوم المذاب في النيكل، والمحاليل مخاليط متجانسة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O02' and q.type = 'mcq' and q.number = 6) and explanation = 'يذكر الكتاب أن النيتينول محلول صلب يتكون من التيتانيوم المذاب في النيكل، والمحاليل مخاليط متجانسة.';
update public.question_answers set explanation = 'المخاليط غير المتجانسة هي مخاليط لا تمتزج مكوناتها تمامًا معًا؛ أي يمكن تمييز كل منها.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O03' and q.type = 'mcq' and q.number = 1) and explanation = 'يعرّف الكتاب المخاليط غير المتجانسة بأنها مخاليط لا تمتزج مكوناتها تمامًا معًا؛ أي يمكن تمييز كل منها.';
update public.question_answers set explanation = 'هناك نوعان من المخاليط غير المتجانسة هما المعلق والغروي.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O03' and q.type = 'mcq' and q.number = 3) and explanation = 'يذكر الكتاب أن هناك نوعين من المخاليط غير المتجانسة هما المعلق والغروي.';
update public.question_answers set explanation = 'هذا هو تعريف المخلوط غير المتجانس.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O03' and q.type = 'mcq' and q.number = 4) and explanation = 'هذا هو تعريف المخلوط غير المتجانس كما ورد في الكتاب.';
update public.question_answers set explanation = 'الوحل مثال على المخلوط المعلق؛ إذ تترسب جسيمات الطين فيه إذا تُرك دون تحريك.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O04' and q.type = 'mcq' and q.number = 1) and explanation = 'يمثل الكتاب للمخلوط المعلق بالوحل؛ إذ تترسب جسيمات الطين فيه إذا تُرك دون تحريك (الشكل 1-1).';
update public.question_answers set explanation = 'المايونيز مثال على المستحلب، وهو نوع من المخاليط الغروية.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O04' and q.type = 'mcq' and q.number = 2) and explanation = 'يذكر الجدول 1-1 المايونيز مثالًا على المستحلب، وهو نوع من المخاليط الغروية.';
update public.question_answers set explanation = 'الدم والجيلاتين (صلب في سائل) والضباب (هباء جوي سائل) كلها مخاليط غروية.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O04' and q.type = 'mcq' and q.number = 3) and explanation = 'وفق الجدول 1-1: الدم والجيلاتين (صلب في سائل) والضباب (هباء جوي سائل) كلها مخاليط غروية.';
update public.question_answers set explanation = 'الدخان هباء جوي صلب: جسيمات صلبة منتشرة في وسط انتشار غازي.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O04' and q.type = 'mcq' and q.number = 4) and explanation = 'الدخان هباء جوي صلب: جسيمات صلبة منتشرة في وسط انتشار غازي (الجدول 1-1).';
update public.question_answers set explanation = 'الحليب مخلوط غروي لا يمكن فصل مكوناته بالترويق أو الترشيح.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O04' and q.type = 'mcq' and q.number = 6) and explanation = 'يذكر الكتاب أن الحليب مخلوط غروي لا يمكن فصل مكوناته بالترويق أو الترشيح.';
update public.question_answers set explanation = 'مانع التجمد محلول سائل (الإيثيلين جلايكول في الماء)، أي مخلوط متجانس؛ أما البقية فمخاليط غير متجانسة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O04' and q.type = 'mcq' and q.number = 7) and explanation = 'مانع التجمد محلول سائل (الإيثيلين جلايكول في الماء) وفق الجدول 1-2، أي مخلوط متجانس؛ أما البقية فمخاليط غير متجانسة.';
update public.question_answers set model_answer = 'مثال المعلق: الوحل؛ لأنه يحتوي على جسيمات طين كبيرة تترسب إذا تُرك دون تحريك، وتُفصل بالترشيح. مثالا الغروي: الحليب؛ لأنه مستحلب تنتشر فيه جسيمات سائلة في وسط سائل ولا تترسب، والضباب؛ لأنه هباء جوي سائل تنتشر فيه قطيرات سائلة في الهواء ولا تترسب ويشتت الضوء. (تُقبل أمثلة أخرى مثل الدم والجيلاتين والزبد والدخان).' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O04' and q.type = 'essay' and q.number = 1) and model_answer = 'مثال المعلق: الوحل؛ لأنه يحتوي على جسيمات طين كبيرة تترسب إذا تُرك دون تحريك، وتُفصل بالترشيح. مثالا الغروي: الحليب؛ لأنه مستحلب تنتشر فيه جسيمات سائلة في وسط سائل ولا تترسب، والضباب؛ لأنه هباء جوي سائل تنتشر فيه قطيرات سائلة في الهواء ولا تترسب ويشتت الضوء. (تُقبل أمثلة أخرى من الجدول 1-1 مثل الدم والجيلاتين والزبد والدخان).';
update public.question_answers set explanation = 'المحلول قد يكون غازيًّا أو سائلًا أو صلبًا اعتمادًا على الحالة الفيزيائية للمذيب.', distractor_notes = '["المذاب قد يكون غازًا أو سائلًا أو صلبًا في محلول واحد النوع؛ فالماء الغازي محلول سائل مذابه غاز.","كمية المذاب تحدد تركيز المحلول لا حالته الفيزيائية.","","درجة الحرارة ليست أساس تصنيف المحاليل."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O05' and q.type = 'mcq' and q.number = 1) and explanation = 'يذكر الكتاب أن المحلول قد يكون غازيًّا أو سائلًا أو صلبًا اعتمادًا على الحالة الفيزيائية للمذيب.';
update public.question_answers set explanation = 'المذيب في لغم الأسنان هو الفضة، وهي صلبة؛ وبما أن حالة المحلول تعتمد على حالة المذيب فهو محلول صلب.', distractor_notes = '["","صُنّف المحلول وفق حالة المذاب، والصحيح أن التصنيف يعتمد على حالة المذيب.","لا يوجد في لغم الأسنان مذيب غازي؛ فالمذيب الفضة الصلبة.","لغم الأسنان محلول صلب لا مخلوطًا غرويًّا."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O05' and q.type = 'mcq' and q.number = 3) and explanation = 'المذيب في لغم الأسنان هو الفضة، وهي صلبة؛ وبما أن حالة المحلول تعتمد على حالة المذيب فهو محلول صلب (الجدول 1-2).';
update public.question_answers set distractor_notes = '["الماء الغازي مثلًا مذيبه سائل ومذابه غاز؛ فلا يشترط تساوي الحالتين.","الفولاذ ولغم الأسنان والنيتينول محاليل صلبة.","","معظم المحاليل تكون في الحالة السائلة."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O05' and q.type = 'mcq' and q.number = 5) and distractor_notes is not distinct from '["الماء الغازي مثلًا مذيبه سائل ومذابه غاز؛ فلا يشترط تساوي الحالتين.","الفولاذ ولغم الأسنان والنيتينول محاليل صلبة.","","يذكر الكتاب أن معظم المحاليل تكون في الحالة السائلة."]'::jsonb;
update public.question_answers set explanation = 'الهواء محلول غازي مذيبه النيتروجين (غاز) ومن مذاباته الأكسجين (غاز).' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O05' and q.type = 'mcq' and q.number = 6) and explanation = 'الهواء محلول غازي مذيبه النيتروجين (غاز) ومن مذاباته الأكسجين (غاز) وفق الجدول 1-2.';
update public.question_answers set explanation = 'أقطار الجسيمات في المخلوط الغروي تتراوح بين 1 nm و1000 nm.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O06' and q.type = 'mcq' and q.number = 1) and explanation = 'يذكر الكتاب أن أقطار الجسيمات في المخلوط الغروي تتراوح بين 1 nm و1000 nm.';
update public.question_answers set explanation = 'المخاليط الغروية والمعلقة تُظهر تأثير تندال، أما المحاليل فلا يمكن أن تُظهره.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O06' and q.type = 'mcq' and q.number = 4) and explanation = 'يذكر الكتاب أن المخاليط الغروية والمعلقة تُظهر تأثير تندال، أما المحاليل فلا يمكن أن تُظهره.';
update public.question_answers set explanation = 'تأثير تندال هو تشتيت جسيمات المخلوط الغروي المنتشرة للضوء.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O08' and q.type = 'mcq' and q.number = 1) and explanation = 'يعرّف الكتاب تأثير تندال بأنه تشتيت جسيمات المخلوط الغروي المنتشرة للضوء.';
update public.question_answers set explanation = 'جسيمات الغروي المنتشرة تشتت الضوء فيظهر مسار الحزمة في الكأس (2)، أما المحلول فلا يشتت الضوء.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O08' and q.type = 'mcq' and q.number = 3) and explanation = 'جسيمات الغروي المنتشرة تشتت الضوء فيظهر مسار الحزمة في الكأس (2)، أما المحلول فلا يشتت الضوء (الشكل 1-3).';
update public.question_answers set explanation = 'يمكن ملاحظة تأثير تندال عند مرور أشعة الشمس خلال الهواء المشبع بالدخان؛ إذ تشتت جسيمات الدخان الضوء.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O08' and q.type = 'mcq' and q.number = 5) and explanation = 'يذكر الكتاب أنه يمكن ملاحظة تأثير تندال عند مرور أشعة الشمس خلال الهواء المشبع بالدخان؛ إذ تشتت جسيمات الدخان الضوء.';
update public.question_answers set explanation = 'على سطح الجسيمات المنتشرة مجموعات ذرية أو قطبية مشحونة تجذب جسيمات وسط الانتشار، فتتكون حولها طبقات كهروستاتيكية تتنافر عند تصادم الجسيمات، فتبقى الجسيمات منتشرة ولا تترسب. إذن الإجابة: تكوّن طبقات كهروستاتيكية حولها تجعلها تتنافر عند تصادمها.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O09' and q.type = 'mcq' and q.number = 1) and explanation = 'يذكر الكتاب أن على سطح الجسيمات المنتشرة مجموعات ذرية أو قطبية مشحونة تجذب جسيمات وسط الانتشار، فتتكون حولها طبقات كهروستاتيكية تتنافر عند تصادم الجسيمات، فتبقى الجسيمات منتشرة ولا تترسب. إذن الإجابة: تكوّن طبقات كهروستاتيكية حولها تجعلها تتنافر عند تصادمها.';
update public.question_answers set explanation = 'تجذب المجموعات الذرية أو القطبية المشحونة على سطح الجسيمات المنتشرة المناطقَ الموجبة أو السالبة لجسيمات وسط الانتشار، فتتكون حول الجسيمات طبقات كهروستاتيكية. فالإجابة: طبقات كهروستاتيكية مشحونة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O09' and q.type = 'mcq' and q.number = 2) and explanation = 'تجذب المجموعات الذرية أو القطبية المشحونة على سطح الجسيمات المنتشرة المناطقَ الموجبة أو السالبة لجسيمات وسط الانتشار، فتتكون حول الجسيمات طبقات كهروستاتيكية (الشكل 1-2). فالإجابة: طبقات كهروستاتيكية مشحونة.';
update public.question_answers set explanation = 'الطبقات الكهروستاتيكية يتنافر بعضها مع بعض عندما تتصادم الجسيمات المنتشرة، فتبقى الجسيمات منفصلة في المخلوط الغروي ولا تترسب. إذن: تتنافران فيبقى الجسيمان منفصلين.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O09' and q.type = 'mcq' and q.number = 3) and explanation = 'يوضح الكتاب أن الطبقات الكهروستاتيكية يتنافر بعضها مع بعض عندما تتصادم الجسيمات المنتشرة، فتبقى الجسيمات منفصلة في المخلوط الغروي ولا تترسب. إذن: تتنافران فيبقى الجسيمان منفصلين.';
update public.question_answers set explanation = 'الحركة البراونية تنتج عن تصادم جسيمات الوسط مع الجسيمات المنتشرة، وأن هذه التصادمات تمنع الجسيمات المنتشرة من الترسب في المخلوط. فالإجابة: تصادمات جسيمات الوسط بالجسيمات المنتشرة تُبقيها متحركة فلا تترسب.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O09' and q.type = 'mcq' and q.number = 4) and explanation = 'يذكر الكتاب أن الحركة البراونية تنتج عن تصادم جسيمات الوسط مع الجسيمات المنتشرة، وأن هذه التصادمات تمنع الجسيمات المنتشرة من الترسب في المخلوط. فالإجابة: تصادمات جسيمات الوسط بالجسيمات المنتشرة تُبقيها متحركة فلا تترسب.';
update public.question_answers set explanation = 'الجسيمات المنتشرة تُمنع من الترسب لوجود مجموعات ذرية أو قطبية مشحونة على سطحها، تجذب المناطق الموجبة أو السالبة لجسيمات وسط الانتشار فتتكون الطبقات الكهروستاتيكية. فالإجابة: وجود مجموعات ذرية أو قطبية مشحونة على سطحها.', distractor_notes = '["لو خلا السطح من الشحنات لما جذبت الجسيماتُ جسيماتِ الوسط ولما تكونت الطبقات الكهروستاتيكية.","لا توجد طبقة دهنية؛ فالطبقات المذكورة كهروستاتيكية تنشأ عن مجموعات مشحونة على السطح.","الكثافة الأعلى تُسرّع الترسب لا تمنعه، فعدم الترسب مرتبط بالمجموعات المشحونة على السطح.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O09' and q.type = 'mcq' and q.number = 6) and explanation = 'يذكر الكتاب أن الجسيمات المنتشرة تُمنع من الترسب لوجود مجموعات ذرية أو قطبية مشحونة على سطحها، تجذب المناطق الموجبة أو السالبة لجسيمات وسط الانتشار فتتكون الطبقات الكهروستاتيكية. فالإجابة: وجود مجموعات ذرية أو قطبية مشحونة على سطحها.';
update public.question_answers set explanation = 'الطبقات الكهروستاتيكية هي ما يجعل الجسيمات تتنافر فلا تتجمع. وإذا تدخلنا في هذه الطبقات فسوف تترسب الجسيمات المنتشرة، إذ تتجمع معًا ويتلف المخلوط الغروي. فالمتوقع: تتجمع الجسيمات عند تصادمها فتترسب.', distractor_notes = '["إزالة الطبقات لا تُذيب الجسيمات؛ فلا ينتج محلول، بل تتجمع الجسيمات وتترسب.","التنافر مصدره الطبقات نفسها؛ فإذا زالت زال التنافر ولم يزدد.","","الطبقات الكهروستاتيكية سبب رئيس لعدم الترسب؛ والتدخل فيها يؤدي إلى ترسب الجسيمات."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O09' and q.type = 'mcq' and q.number = 7) and explanation = 'الطبقات الكهروستاتيكية هي ما يجعل الجسيمات تتنافر فلا تتجمع. ويذكر الكتاب أنه إذا تدخلنا في هذه الطبقات فسوف تترسب الجسيمات المنتشرة، إذ تتجمع معًا ويتلف المخلوط الغروي. فالمتوقع: تتجمع الجسيمات عند تصادمها فتترسب.';
update public.question_answers set explanation = 'ظهور مسار حزمة الضوء نتيجة تشتيت الجسيمات المنتشرة له يُسمى تأثير تندال، ويُلاحظ عند مرور ضوء خلال الضباب. فالإجابة: تأثير تندال.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O10' and q.type = 'mcq' and q.number = 5) and explanation = 'ظهور مسار حزمة الضوء نتيجة تشتيت الجسيمات المنتشرة له يُسمى تأثير تندال، ويذكر الكتاب أنه يُلاحظ عند مرور ضوء خلال الضباب. فالإجابة: تأثير تندال.';
update public.question_answers set explanation = 'الرطوبة محلول غازي (الماء مذاب في الهواء)، والمحاليل لا تُظهر تأثير تندال لأنه لا يمكن تمييز المذاب فيها. أما الضباب فهباء جوي سائل تشتت قطيراته الضوء. إذن: الرطوبة محلول غازي لا يُظهر تأثير تندال، أما الضباب فهباء جوي سائل تشتت قطيراته الضوء.', distractor_notes = '["الرطوبة محلول غازي (ماء مذاب في الهواء)، والضباب هباء جوي سائل لا محلول؛ فالتصنيفان معكوسان وخاطئان.","","الماء في الضباب قطيرات سائلة منتشرة لا بخار ذائب، وهذا الفرق في الحالة هو سبب ظهور تأثير تندال.","المحاليل ومنها الرطوبة لا تُظهر تأثير تندال؛ فالفرق في نوع المخلوط لا في الكثافة."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O10' and q.type = 'mcq' and q.number = 6) and explanation = 'يصنف الجدول 1-2 الرطوبة محلولًا غازيًّا (الماء مذاب في الهواء)، والمحاليل لا تُظهر تأثير تندال لأنه لا يمكن تمييز المذاب فيها. أما الضباب فهباء جوي سائل (الجدول 1-1) تشتت قطيراته الضوء. إذن: الرطوبة محلول غازي لا يُظهر تأثير تندال، أما الضباب فهباء جوي سائل تشتت قطيراته الضوء.';
update public.question_answers set explanation = 'الدخان في الهواء هباء جوي صلب، وجسيماته المنتشرة تشتت الضوء كما تشتته قطيرات الضباب؛ وتأثير تندال يُشاهد عند مرور أشعة الشمس خلال الهواء المشبع بالدخان. فالسبب: جسيمات الدخان الصلبة المنتشرة في الهواء تشتت ضوء المصابيح.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O10' and q.type = 'mcq' and q.number = 7) and explanation = 'الدخان في الهواء هباء جوي صلب (الجدول 1-1)، وجسيماته المنتشرة تشتت الضوء كما تشتته قطيرات الضباب؛ ويذكر الكتاب أن تأثير تندال يُشاهد عند مرور أشعة الشمس خلال الهواء المشبع بالدخان. فالسبب: جسيمات الدخان الصلبة المنتشرة في الهواء تشتت ضوء المصابيح.';
update public.question_answers set explanation = 'الحركة البراونية هي حركة عشوائية غير منتظمة ومستمرة تتحركها الجسيمات المنتشرة في المخاليط الغروية السائلة. فالإجابة: حركة عشوائية غير منتظمة ومستمرة لجسيمات المخلوط الغروي السائل.', distractor_notes = '["","الحركة البراونية عشوائية غير منتظمة، وهي حركة لجسيمات المخاليط الغروية السائلة لا المحاليل.","هذا وصف لترسب جسيمات المعلق (الترويق)، والحركة البراونية بالعكس تمنع الترسب.","تشتيت الجسيمات للضوء هو تأثير تندال، وليس الحركة البراونية."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O11' and q.type = 'mcq' and q.number = 1) and explanation = 'يعرّف الكتاب الحركة البراونية بأنها حركة عشوائية غير منتظمة ومستمرة تتحركها الجسيمات المنتشرة في المخاليط الغروية السائلة. فالإجابة: حركة عشوائية غير منتظمة ومستمرة لجسيمات المخلوط الغروي السائل.';
update public.question_answers set explanation = 'لاحظ عالم النبات الإسكتلندي روبرت براون (1773–1858) هذه الحركة أول مرة، فسُمّيت باسمه. فالإجابة: روبرت براون.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O11' and q.type = 'mcq' and q.number = 2) and explanation = 'يذكر الكتاب أن عالم النبات الإسكتلندي روبرت براون (1773–1858) لاحظ هذه الحركة أول مرة، فسُمّيت باسمه. فالإجابة: روبرت براون.';
update public.question_answers set explanation = 'لاحظ روبرت براون الحركة العشوائية لحبوب اللقاح المتناثرة في الماء أول مرة. فالإجابة: حبوب اللقاح المتناثرة في الماء.', distractor_notes = '["لاحظ براون الحركة في حبوب اللقاح في الماء، لا في الدخان.","","الزيت والخل مثال على السوائل غير الممتزجة، لا على مشاهدة براون.","السكر يذوب في الماء مكونًا محلولًا، وبراون لاحظ حبوب لقاح غير ذائبة متناثرة في الماء."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O11' and q.type = 'mcq' and q.number = 3) and explanation = 'يذكر الكتاب أن روبرت براون لاحظ الحركة العشوائية لحبوب اللقاح المتناثرة في الماء أول مرة. فالإجابة: حبوب اللقاح المتناثرة في الماء.';
update public.question_answers set explanation = 'الحركة البراونية تنتج عن تصادم جسيمات الوسط مع الجسيمات المنتشرة. فالإجابة: تصادم جسيمات وسط الانتشار مع الجسيمات المنتشرة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O11' and q.type = 'mcq' and q.number = 4) and explanation = 'يذكر الكتاب أن الحركة البراونية تنتج عن تصادم جسيمات الوسط مع الجسيمات المنتشرة. فالإجابة: تصادم جسيمات وسط الانتشار مع الجسيمات المنتشرة.';
update public.question_answers set explanation = 'الحركة البراونية عشوائية غير منتظمة ومستمرة؛ فالطالب يرى الجسيمات تتحرك دون توقف وفي اتجاهات تتغير باستمرار. فالإجابة: تتحرك باستمرار في اتجاهات عشوائية متغيرة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O11' and q.type = 'mcq' and q.number = 5) and explanation = 'الحركة البراونية كما يصفها الكتاب عشوائية غير منتظمة ومستمرة؛ فالطالب يرى الجسيمات تتحرك دون توقف وفي اتجاهات تتغير باستمرار. فالإجابة: تتحرك باستمرار في اتجاهات عشوائية متغيرة.';
update public.question_answers set explanation = 'الجسيمات المنتشرة في المخاليط الغروية السائلة تتحرك حركة عشوائية تُسمى الحركة البراونية، وأنها تنتج عن تصادم جسيمات الوسط مع الجسيمات المنتشرة. فالعبارة الصحيحة: تُلاحظ في المخاليط الغروية السائلة، وتنتج عن تصادم جسيمات الوسط بالجسيمات المنتشرة.', distractor_notes = '["الحركة البراونية تخص جسيمات المخاليط الغروية السائلة، وتشتيت الضوء هو تأثير تندال لا سبب الحركة.","جذب الأرض يسبب ترسب جسيمات المعلق، أما الحركة البراونية فسببها التصادمات وتُلاحظ في الغرويات.","إضافة مادة متأينة تُتلف المخلوط الغروي فتترسب جسيماته، ولا تسبب الحركة البراونية.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O11' and q.type = 'mcq' and q.number = 7) and explanation = 'يذكر الكتاب أن الجسيمات المنتشرة في المخاليط الغروية السائلة تتحرك حركة عشوائية تُسمى الحركة البراونية، وأنها تنتج عن تصادم جسيمات الوسط مع الجسيمات المنتشرة. فالعبارة الصحيحة: تُلاحظ في المخاليط الغروية السائلة، وتنتج عن تصادم جسيمات الوسط بالجسيمات المنتشرة.';
update public.question_answers set explanation = 'الحليب مستحلب غروي؛ لأن الجسيمات المنتشرة السائلة تنتشر بين جسيمات وسط الانتشار السائل. فالإجابة: جسيماته المنتشرة سائلة ووسط انتشاره سائل.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O12' and q.type = 'mcq' and q.number = 1) and explanation = 'يذكر الكتاب أن الحليب مستحلب غروي؛ لأن الجسيمات المنتشرة السائلة تنتشر بين جسيمات وسط الانتشار السائل. فالإجابة: جسيماته المنتشرة سائلة ووسط انتشاره سائل.';
update public.question_answers set explanation = 'وسط الانتشار هو المادة الأكثر توافرًا في المخلوط الغروي. فالإجابة: المادة الأكثر توافرًا في المخلوط الغروي.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O12' and q.type = 'mcq' and q.number = 2) and explanation = 'يعرّف الكتاب وسط الانتشار بأنه المادة الأكثر توافرًا في المخلوط الغروي. فالإجابة: المادة الأكثر توافرًا في المخلوط الغروي.';
update public.question_answers set explanation = 'المخلوط الغروي الذي جسيماته المنتشرة سائلة ووسط انتشاره صلب يُسمى مستحلبًا صلبًا، ومن أمثلته الزبد والجبن. فالإجابة: مستحلب صلب.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O12' and q.type = 'mcq' and q.number = 3) and explanation = 'وفق الجدول 1-1، المخلوط الغروي الذي جسيماته المنتشرة سائلة ووسط انتشاره صلب يُسمى مستحلبًا صلبًا، ومن أمثلته الزبد والجبن. فالإجابة: مستحلب صلب.';
update public.question_answers set explanation = 'الغيوم ورذاذ مزيل العرق كلاهما قطيرات سائلة منتشرة في الهواء، فهما من نوع الهباء الجوي السائل. أما بقية الأزواج فيختلف فيها حال الجسيمات المنتشرة أو وسط الانتشار. فالإجابة: الغيوم، ورذاذ مزيل العرق.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O12' and q.type = 'mcq' and q.number = 6) and explanation = 'الغيوم ورذاذ مزيل العرق كلاهما قطيرات سائلة منتشرة في الهواء، فهما من نوع الهباء الجوي السائل في الجدول 1-1. أما بقية الأزواج فيختلف فيها حال الجسيمات المنتشرة أو وسط الانتشار. فالإجابة: الغيوم، ورذاذ مزيل العرق.';
update public.question_answers set explanation = 'الدم والجيلاتين من نوع (صلب في سائل): جسيمات منتشرة صلبة في وسط انتشار سائل. فالزوج الصحيح: الجيلاتين — صلب في سائل.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O12' and q.type = 'mcq' and q.number = 7) and explanation = 'يضع الجدول 1-1 الدم والجيلاتين تحت تصنيف (صلب في سائل): جسيمات منتشرة صلبة في وسط انتشار سائل. فالزوج الصحيح: الجيلاتين — صلب في سائل.';
update public.question_answers set model_answer = 'من أنواع المخاليط الغروية: (1) المستحلب: سائل منتشر في سائل، مثل الحليب والمايونيز. (2) المستحلب الصلب: سائل منتشر في صلب، مثل الزبد والجبن. (3) الرغوة الصلبة: غاز منتشر في صلب، مثل الصابون الذي يطفو وحلوى الخطمي. (4) الهباء الجوي الصلب: صلب منتشر في غاز، مثل الدخان والغبار في الهواء. ومن الأنواع الأخرى: الهباء الجوي السائل (سائل في غاز) كالغيوم والضباب، وصلب في سائل كالدم والجيلاتين، وصلب في صلب كالأحجار الكريمة الملونة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O12' and q.type = 'essay' and q.number = 1) and model_answer = 'من أنواع المخاليط الغروية (الجدول 1-1): (1) المستحلب: سائل منتشر في سائل، مثل الحليب والمايونيز. (2) المستحلب الصلب: سائل منتشر في صلب، مثل الزبد والجبن. (3) الرغوة الصلبة: غاز منتشر في صلب، مثل الصابون الذي يطفو وحلوى الخطمي. (4) الهباء الجوي الصلب: صلب منتشر في غاز، مثل الدخان والغبار في الهواء. ومن الأنواع الأخرى: الهباء الجوي السائل (سائل في غاز) كالغيوم والضباب، وصلب في سائل كالدم والجيلاتين، وصلب في صلب كالأحجار الكريمة الملونة.';
update public.question_answers set explanation = 'عند تحريك مادة متأينة (إلكتروليتية) في مخلوط غروي تتجمع الجسيمات المنتشرة معًا، ويتلف المخلوط الغروي، وتترسب جسيماته. فالإجابة: تتجمع الجسيمات المنتشرة وتترسب فيتلف المخلوط.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O13' and q.type = 'mcq' and q.number = 1) and explanation = 'يذكر الكتاب أنه عند تحريك مادة متأينة (إلكتروليتية) في مخلوط غروي تتجمع الجسيمات المنتشرة معًا، ويتلف المخلوط الغروي، وتترسب جسيماته. فالإجابة: تتجمع الجسيمات المنتشرة وتترسب فيتلف المخلوط.';
update public.question_answers set explanation = 'التسخين يُتلف المخلوط الغروي؛ لأن الحرارة تعطي الجسيمات المتصادمة طاقة حركية كافية للتغلب على القوى الكهروستاتيكية، ثم ترسبها في المخلوط. فالإجابة: لأن الحرارة تعطي الجسيمات المتصادمة طاقة حركية كافية للتغلب على القوى الكهروستاتيكية.', distractor_notes = '["لا يُفسَّر التلف بتبخر الوسط، بل بتغلب الجسيمات المتصادمة على القوى الكهروستاتيكية.","زيادة التنافر تزيد ثبات المخلوط وتمنع الترسب، فلا تفسر التلف.","لو ذابت الجسيمات لتكوّن محلول ولم تترسب؛ والملاحظ ترسبها.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O13' and q.type = 'mcq' and q.number = 2) and explanation = 'يذكر الكتاب أن التسخين يُتلف المخلوط الغروي؛ لأن الحرارة تعطي الجسيمات المتصادمة طاقة حركية كافية للتغلب على القوى الكهروستاتيكية، ثم ترسبها في المخلوط. فالإجابة: لأن الحرارة تعطي الجسيمات المتصادمة طاقة حركية كافية للتغلب على القوى الكهروستاتيكية.';
update public.question_answers set explanation = 'عند تحريك مادة متأينة (إلكتروليتية) في مخلوط غروي تتجمع جسيماته؛ فالمادة المتأينة تُسمى أيضًا مادة إلكتروليتية.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O13' and q.type = 'mcq' and q.number = 3) and explanation = 'يذكر الكتاب: «فعند تحريك مادة متأينة (إلكتروليتية) في مخلوط غروي...»، فالمادة المتأينة تُسمى أيضًا مادة إلكتروليتية.';
update public.question_answers set explanation = 'إذا تدخلنا في الطبقات الكهروستاتيكية فسوف تترسب الجسيمات المنتشرة: فالمادة المتأينة تتدخل فيها فتتجمع الجسيمات، والتسخين يعطي الجسيمات طاقة للتغلب على القوى الكهروستاتيكية. فالقاسم المشترك: كلاهما يتغلب على أثر الطبقات الكهروستاتيكية فتترسب الجسيمات.', distractor_notes = '["","الإجراءان يُتلفان المخلوط ويُرسبان جسيماته، فلا يُبقيانها منتشرة.","النتيجة ترسب الجسيمات وتلف المخلوط، لا تكوّن محلول متجانس.","تترسب الجسيمات في الحالتين، ولا يربطهما بزيادة تأثير تندال."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O13' and q.type = 'mcq' and q.number = 4) and explanation = 'يذكر الكتاب أنه إذا تدخلنا في الطبقات الكهروستاتيكية فسوف تترسب الجسيمات المنتشرة: فالمادة المتأينة تتدخل فيها فتتجمع الجسيمات، والتسخين يعطي الجسيمات طاقة للتغلب على القوى الكهروستاتيكية. فالقاسم المشترك: كلاهما يتغلب على أثر الطبقات الكهروستاتيكية فتترسب الجسيمات.';
update public.question_answers set distractor_notes = '["","جسيمات المخلوط الغروي لا تترسب بالترويق؛ فالترك دون تحريك يفصل المعلق فقط.","لا يمكن فصل مكونات المخلوط الغروي بالترشيح كما في الحليب.","تمرير الضوء يُظهر تأثير تندال فقط ولا يُرسب الجسيمات."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O13' and q.type = 'mcq' and q.number = 5) and distractor_notes is not distinct from '["","جسيمات المخلوط الغروي لا تترسب بالترويق؛ فالترك دون تحريك يفصل المعلق فقط.","لا يمكن فصل مكونات المخلوط الغروي بالترشيح كما ذكر الكتاب عن الحليب.","تمرير الضوء يُظهر تأثير تندال فقط ولا يُرسب الجسيمات."]'::jsonb;
update public.question_answers set distractor_notes = '["قوة التنافر تمنع الترسب، فلا يمكن أن تفسر الترسب الملاحظ.","تباعد الجسيمات يُبقيها منتشرة لا يُرسبها، فالترسب مرتبط بالتدخل في الطبقات الكهروستاتيكية.","","الذوبان لا يُنتج راسبًا؛ والملاحظ ترسب الجسيمات لا اختفاؤها."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O13' and q.type = 'mcq' and q.number = 6) and distractor_notes is not distinct from '["قوة التنافر تمنع الترسب، فلا يمكن أن تفسر الترسب الملاحظ.","تباعد الجسيمات يُبقيها منتشرة لا يُرسبها، والكتاب ربط الترسب بالتدخل في الطبقات الكهروستاتيكية.","","الذوبان لا يُنتج راسبًا؛ والملاحظ ترسب الجسيمات لا اختفاؤها."]'::jsonb;
update public.question_answers set distractor_notes = '["التسخين يزيد الطاقة الحركية لا ينقصها، فالترسب مرتبط بطاقة كافية للتغلب على القوى.","زيادة التنافر تُبقي الجسيمات منتشرة، فلا تفسر ترسبها عند التسخين.","التحول إلى أيونات ذائبة لا يُكوّن راسبًا، والملاحظ ترسب الجسيمات.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O13' and q.type = 'mcq' and q.number = 7) and distractor_notes is not distinct from '["التسخين يزيد الطاقة الحركية لا ينقصها، والكتاب يربط الترسب بطاقة كافية للتغلب على القوى.","زيادة التنافر تُبقي الجسيمات منتشرة، فلا تفسر ترسبها عند التسخين.","التحول إلى أيونات ذائبة لا يُكوّن راسبًا، والملاحظ ترسب الجسيمات.",""]'::jsonb;
update public.question_answers set explanation = 'المادتان السائلتان اللتان تذوب إحداهما في الأخرى بأي نسبة تُسميان المواد القابلة للامتزاج. فالإجابة: مواد قابلة للامتزاج.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O14' and q.type = 'mcq' and q.number = 1) and explanation = 'يذكر الكتاب أن المادتين السائلتين اللتين تذوب إحداهما في الأخرى بأي نسبة تُسميان المواد القابلة للامتزاج. فالإجابة: مواد قابلة للامتزاج.';
update public.question_answers set explanation = 'السوائل غير الممتزجة هي السوائل التي تمتزج معًا فترة قصيرة عند خلطها ثم تنفصل بعدها. فالإجابة: سوائل غير ممتزجة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O14' and q.type = 'mcq' and q.number = 2) and explanation = 'يعرّف الكتاب السوائل غير الممتزجة بأنها السوائل التي تمتزج معًا فترة قصيرة عند خلطها ثم تنفصل بعدها. فالإجابة: سوائل غير ممتزجة.';
update public.question_answers set explanation = 'الزيت لا يمتزج مع الخل؛ أي أن الزيت لا يذوب في الخل، فإذا خُلطا امتزجا فترة قصيرة ثم انفصلا. فالإجابة: الزيت والخل.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O14' and q.type = 'mcq' and q.number = 3) and explanation = 'يذكر الكتاب أن الزيت لا يمتزج مع الخل؛ أي أن الزيت لا يذوب في الخل، فإذا خُلطا امتزجا فترة قصيرة ثم انفصلا. فالإجابة: الزيت والخل.';
update public.question_answers set explanation = 'مانع التجمد محلول سائل: المذيب الماء والمذاب الإيثيلين جلايكول (سائل)، وهو مثال على المواد القابلة للامتزاج. فالإجابة: أنهما قابلان للامتزاج؛ يذوب أحدهما في الآخر.', distractor_notes = '["لو انفصلا لما تكوّن محلول متجانس كمانع التجمد.","الإيثيلين جلايكول مذاب في الماء، فهو ذائب لا غير ذائب.","","المستحلب مخلوط غروي غير متجانس، أما مانع التجمد فمحلول متجانس."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O14' and q.type = 'mcq' and q.number = 4) and explanation = 'مانع التجمد في الجدول 1-2 محلول سائل: المذيب الماء والمذاب الإيثيلين جلايكول (سائل)، ويذكره الكتاب مثالًا على المواد القابلة للامتزاج. فالإجابة: أنهما قابلان للامتزاج؛ يذوب أحدهما في الآخر.';
update public.question_answers set explanation = 'امتزاج السائلين فترة قصيرة ثم انفصالهما إلى طبقتين هو وصف السوائل غير الممتزجة. فالإجابة: السائلان غير ممتزجين.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O14' and q.type = 'mcq' and q.number = 5) and explanation = 'امتزاج السائلين فترة قصيرة ثم انفصالهما إلى طبقتين هو بالضبط وصف الكتاب للسوائل غير الممتزجة. فالإجابة: السائلان غير ممتزجين.';
update public.question_answers set explanation = 'المادة الذائبة هي المادة التي تذوب في المذيب، كالسكر الذي يذوب في الماء. فالإجابة: المادة التي تذوب في المذيب.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O15' and q.type = 'mcq' and q.number = 1) and explanation = 'يعرّف الكتاب المادة الذائبة بأنها المادة التي تذوب في المذيب، كالسكر الذي يذوب في الماء. فالإجابة: المادة التي تذوب في المذيب.';
update public.question_answers set explanation = 'الرمل لا يذوب في الماء، فهو مثال على المادة غير الذائبة، بينما السكر وكلوريد الصوديوم والإيثيلين جلايكول تذوب في الماء. فالإجابة: الرمل الناعم.', distractor_notes = '["السكر يذوب في الماء، وهو مثال على المادة الذائبة.","كلوريد الصوديوم مذاب في ماء البحر، فهو ذائب في الماء.","","الإيثيلين جلايكول مذاب في الماء في مانع التجمد، فهو ذائب في الماء."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O15' and q.type = 'mcq' and q.number = 2) and explanation = 'يذكر الكتاب أن الرمل لا يذوب في الماء، فهو مثال على المادة غير الذائبة، بينما السكر وكلوريد الصوديوم والإيثيلين جلايكول تذوب في الماء. فالإجابة: الرمل الناعم.';
update public.question_answers set explanation = 'ذوبان السكر في الماء لعمل شراب محلّى كالشاي مثالًا على المادة الذائبة؛ فالسكر يذوب في المذيب (الماء). فالإجابة: مادة ذائبة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O15' and q.type = 'mcq' and q.number = 3) and explanation = 'يذكر الكتاب ذوبان السكر في الماء لعمل شراب محلّى كالشاي مثالًا على المادة الذائبة؛ فالسكر يذوب في المذيب (الماء). فالإجابة: مادة ذائبة.';
update public.question_answers set explanation = 'بقاء حبيبات الرمل مميزة واستقرارها في القاع يعني أنها لم تذب في الماء؛ والرمل مثال على المادة غير الذائبة في الماء. فالإجابة: الرمل مادة غير ذائبة في الماء.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O15' and q.type = 'mcq' and q.number = 4) and explanation = 'بقاء حبيبات الرمل مميزة واستقرارها في القاع يعني أنها لم تذب في الماء؛ ويذكر الكتاب الرمل مثالًا على المادة غير الذائبة في الماء. فالإجابة: الرمل مادة غير ذائبة في الماء.';
update public.question_answers set explanation = 'المادة غير الذائبة هي المادة التي لا تذوب في المذيب، ومثالها الرمل الذي لا يذوب في الماء؛ فالوصف مرتبط بمذيب معين. كما أن الزيت لا يذوب في الخل. فالإجابة: مادة لا تذوب في مذيب معين، كالرمل في الماء.', distractor_notes = '["","تُعرَّف بالنسبة إلى «المذيب»، فالحكم يخص مذيبًا معينًا لا كل المذيبات.","المادة غير الذائبة لا تذوب أصلًا، فلا يصح وصفها بأنها تذوب ثم تترسب.","هذا وصف المادة الذائبة في المحلول لا غير الذائبة."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O15' and q.type = 'mcq' and q.number = 6) and explanation = 'يعرّف الكتاب المادة غير الذائبة بأنها المادة التي لا تذوب في المذيب، ومثالها الرمل الذي لا يذوب في الماء؛ فالوصف مرتبط بمذيب معين. كما أن الزيت لا يذوب في الخل. فالإجابة: مادة لا تذوب في مذيب معين، كالرمل في الماء.';
update public.question_answers set model_answer = '(1) يختفي السكر في الماء ولا يمكن تمييزه، ويتكون شراب متجانس محلّى؛ فالسكر مادة ذائبة في الماء لأنه يذوب فيه مكونًا محلولًا. (2) تبقى حبيبات الرمل مميزة وتستقر في القاع بعد الترك؛ فالرمل مادة غير ذائبة في الماء لأنه لا يذوب فيه. (3) يمتزج الزيت والخل فترة قصيرة ثم ينفصلان إلى طبقتين؛ فالزيت مادة غير ذائبة في الخل، إذ الزيت لا يمتزج مع الخل أي لا يذوب فيه.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O15' and q.type = 'essay' and q.number = 2) and model_answer = '(1) يختفي السكر في الماء ولا يمكن تمييزه، ويتكون شراب متجانس محلّى؛ فالسكر مادة ذائبة في الماء لأنه يذوب فيه مكونًا محلولًا. (2) تبقى حبيبات الرمل مميزة وتستقر في القاع بعد الترك؛ فالرمل مادة غير ذائبة في الماء لأنه لا يذوب فيه. (3) يمتزج الزيت والخل فترة قصيرة ثم ينفصلان إلى طبقتين؛ فالزيت مادة غير ذائبة في الخل، إذ يذكر الكتاب أن الزيت لا يمتزج مع الخل أي لا يذوب فيه.';
update public.question_answers set explanation = 'تركيز المحلول مقياس يعبّر عن كمية المذاب الذائبة في كمية محددة من المذيب أو المحلول؛ فهو نسبة بين كمية المذاب وكمية المذيب أو المحلول.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O01' and q.type = 'mcq' and q.number = 1) and explanation = 'يعرّف الكتاب تركيز المحلول بأنه مقياس يعبّر عن كمية المذاب الذائبة في كمية محددة من المذيب أو المحلول؛ فهو نسبة بين كمية المذاب وكمية المذيب أو المحلول.';
update public.question_answers set distractor_notes = '["المحلول المخفّف يحتوي على كمية أقل من المذاب، فهو عكس المطلوب.","المشبع يصف محلولًا يحتوي على أقصى كمية من المذاب، وليس هو الوصف النوعي للتركيز الذي يقابل «مخفّف».","","التجانس صفة لكل المحاليل ولا يدل على كمية المذاب."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O01' and q.type = 'mcq' and q.number = 3) and distractor_notes is not distinct from '["المحلول المخفّف يحتوي على كمية أقل من المذاب، فهو عكس المطلوب.","المشبع يصف محلولًا يحتوي على أقصى كمية من المذاب، وليس هو الوصف النوعي للتركيز الذي يقابل «مخفّف» في الكتاب.","","التجانس صفة لكل المحاليل ولا يدل على كمية المذاب."]'::jsonb;
update public.question_answers set explanation = 'كل طرائق التعبير عن التركيز تعبّر عنه بوصفه نسبة بين كمية المذاب وبين كمية المذيب أو المحلول كله.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O01' and q.type = 'mcq' and q.number = 6) and explanation = 'يذكر الكتاب أن كل طرائق التعبير عن التركيز تعبّر عنه بوصفه نسبة بين كمية المذاب وبين كمية المذيب أو المحلول كله.';
update public.question_answers set explanation = 'من طرائق التعبير الكمي عن التركيز: النسبة المئوية بدلالة الكتلة والحجم، والمولارية، والمولالية، والكسر المولي.', distractor_notes = '["الذائبية أقصى كمية من المذاب تذوب في كمية مذيب، وليست من طرائق التعبير عن تركيز المحلول.","الكثافة نسبة الكتلة إلى الحجم لمادة، ولا تعبّر عن نسبة المذاب في المحلول.","درجة الغليان خاصية فيزيائية وليست طريقة للتعبير عن التركيز.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O02' and q.type = 'mcq' and q.number = 1) and explanation = 'من طرائق التعبير الكمي عن التركيز في الجدول 1-3: النسبة المئوية بدلالة الكتلة والحجم، والمولارية، والمولالية، والكسر المولي.';
update public.question_answers set explanation = 'المولارية M = عدد مولات المذاب ÷ حجم المحلول باللتر.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O02' and q.type = 'mcq' and q.number = 2) and explanation = 'في الجدول 1-3: المولارية M = عدد مولات المذاب ÷ حجم المحلول باللتر.';
update public.question_answers set explanation = 'المولالية m = عدد مولات المذاب ÷ كتلة المذيب (kg)، وهي الطريقة الوحيدة التي مقامها كتلة المذيب.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O02' and q.type = 'mcq' and q.number = 3) and explanation = 'المولالية m = عدد مولات المذاب ÷ كتلة المذيب (kg)، وهي الطريقة الوحيدة في الجدول 1-3 التي مقامها كتلة المذيب.';
update public.question_answers set explanation = 'الكيميائي الذي يعمل على تفاعل في محلول مائي يستعمل المولارية غالبًا؛ لأنه يحتاج إلى معرفة عدد الجسيمات المشاركة في التفاعل، والمولارية تعطي عدد المولات في حجم معين من المحلول.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O02' and q.type = 'mcq' and q.number = 6) and explanation = 'يذكر الكتاب أن الكيميائي الذي يعمل على تفاعل في محلول مائي يستعمل المولارية غالبًا؛ لأنه يحتاج إلى معرفة عدد الجسيمات المشاركة في التفاعل، والمولارية تعطي عدد المولات في حجم معين من المحلول.';
update public.question_answers set explanation = 'الكسر المولي = عدد مولات المذاب أو المذيب ÷ (مولات المذاب + مولات المذيب).' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O02' and q.type = 'mcq' and q.number = 7) and explanation = 'الكسر المولي = عدد مولات المذاب أو المذيب ÷ (مولات المذاب + مولات المذيب)، كما في الجدول 1-3.';
update public.question_answers set explanation = 'النسبة المئوية بدلالة الحجم تصف عادة المحاليل التي يكون فيها المذيب والمذاب في الحالة السائلة.', distractor_notes = '["المذاب الصلب تُقاس كتلته عادة، فيُعبَّر عن تركيزه بالنسبة بدلالة الكتلة.","التشبع لا علاقة له باختيار النسبة بدلالة الحجم.","","هذا غير صحيح؛ النسبة بالحجم تخص عادة سائلًا في سائل."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O03' and q.type = 'mcq' and q.number = 2) and explanation = 'يذكر الكتاب أن النسبة المئوية بدلالة الحجم تصف عادة المحاليل التي يكون فيها المذيب والمذاب في الحالة السائلة.';
update public.question_answers set distractor_notes = '["","كلوريد الصوديوم صلب، فتُستعمل كتلته والنسبة بدلالة الكتلة.","السكر صلب، فالأنسب النسبة بدلالة الكتلة.","NaHCO₃ صلب، ويُعبَّر عن محلوله بالنسبة بدلالة الكتلة."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O03' and q.type = 'mcq' and q.number = 3) and distractor_notes is not distinct from '["","كلوريد الصوديوم صلب، فتُستعمل كتلته والنسبة بدلالة الكتلة.","السكر صلب، فالأنسب النسبة بدلالة الكتلة.","NaHCO₃ صلب، وقد عبّر الكتاب عن محلوله بالنسبة بدلالة الكتلة."]'::jsonb;
update public.question_answers set explanation = 'المولارية (M) هي عدد مولات المذاب الذائبة في لتر من المحلول.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O05' and q.type = 'mcq' and q.number = 1) and explanation = 'يعرّف الكتاب المولارية (M) بأنها عدد مولات المذاب الذائبة في لتر من المحلول.';
update public.question_answers set distractor_notes = '["هذا اسم المولالية (m).","","الكسر المولي طريقة أخرى نسبتها مولات المكوّن إلى المولات الكلية.","ليس اسمًا للمولارية."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O05' and q.type = 'mcq' and q.number = 2) and distractor_notes is not distinct from '["هذا اسم المولالية (m).","","الكسر المولي طريقة أخرى نسبتها مولات المكوّن إلى المولات الكلية.","ليس اسمًا للمولارية في الكتاب."]'::jsonb;
update public.question_answers set explanation = 'لحساب مولارية المحلول يجب معرفة حجم المحلول باللتر وعدد مولات المذاب.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O05' and q.type = 'mcq' and q.number = 5) and explanation = 'يذكر الكتاب أنه لحساب مولارية المحلول يجب معرفة حجم المحلول باللتر وعدد مولات المذاب.';
update public.question_answers set distractor_notes = '["عدد مولات المذاب الذائب في المحلول لا يتغير بالتسخين.","الكتل لا تتأثر بدرجة الحرارة.","","الكتلة المولية ثابتة للمادة."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O05' and q.type = 'mcq' and q.number = 7) and distractor_notes is not distinct from '["عدد مولات المذاب الذائب في المحلول لا يتغير بالتسخين.","الكتل لا تتأثر بدرجة الحرارة كما يذكر الكتاب.","","الكتلة المولية ثابتة للمادة."]'::jsonb;
update public.question_answers set explanation = 'في تحضير المحلول القياسي يُذاب المذاب في دورق حجمي، ويُضاف الماء حتى العلامة المحددة على الدورق، فيكون الحجم محددًا بدقة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O07' and q.type = 'mcq' and q.number = 4) and explanation = 'تبيّن خطوات الشكل 1-5 أن المذاب يُذاب في دورق حجمي، ويُضاف الماء حتى العلامة المحددة على الدورق، فيكون الحجم محددًا بدقة.';
update public.question_answers set distractor_notes = '["تبخير المذيب يزيد التركيز لا يقلله.","إضافة المذاب تزيد التركيز.","ليست طريقة التخفيف.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O07' and q.type = 'mcq' and q.number = 5) and distractor_notes is not distinct from '["تبخير المذيب يزيد التركيز لا يقلله.","إضافة المذاب تزيد التركيز.","ليست طريقة التخفيف المذكورة في الكتاب.",""]'::jsonb;
update public.question_answers set explanation = 'M₁ وV₁ تمثلان مولارية المحلول القياسي وحجمه، وM₂ وV₂ مولارية المحلول المخفف وحجمه.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O07' and q.type = 'mcq' and q.number = 6) and explanation = 'يذكر الكتاب أن M₁ وV₁ تمثلان مولارية المحلول القياسي وحجمه، وM₂ وV₂ مولارية المحلول المخفف وحجمه.';
update public.question_answers set explanation = 'يُرمز إلى المولالية بالرمز m، بينما يُرمز إلى المولارية بالرمز M.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O09' and q.type = 'mcq' and q.number = 2) and explanation = 'يرمز الكتاب إلى المولالية بالرمز m، بينما يرمز إلى المولارية بالرمز M.';
update public.question_answers set distractor_notes = '["بسط كلتيهما عدد مولات المذاب.","عكس الصحيح.","","ليس هذا أساس التمييز بينهما."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O09' and q.type = 'mcq' and q.number = 6) and distractor_notes is not distinct from '["بسط كلتيهما عدد مولات المذاب.","عكس الصحيح.","","ليس هذا أساس التمييز بينهما في الكتاب."]'::jsonb;
update public.question_answers set explanation = 'تركيز المحلول الذي يحتوي على 1 mol من المذاب في 1 kg من المذيب يساوي 1 m (محلول مولالي واحد).' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O09' and q.type = 'mcq' and q.number = 7) and explanation = 'يذكر الكتاب أن تركيز المحلول الذي يحتوي على 1 mol من المذاب في 1 kg من المذيب يساوي 1 m (محلول مولالي واحد).';
update public.question_answers set explanation = 'الكسر المولي هو نسبة عدد مولات المذاب أو المذيب في المحلول إلى عدد المولات الكلية للمذيب والمذاب.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O11' and q.type = 'mcq' and q.number = 1) and explanation = 'يعرّف الكتاب الكسر المولي بأنه نسبة عدد مولات المذاب أو المذيب في المحلول إلى عدد المولات الكلية للمذيب والمذاب.';
update public.question_answers set explanation = 'يُستعمل الرمز X للكسر المولي مع الإشارة إلى المذيب أو المذاب، مثل XA وXB.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O11' and q.type = 'mcq' and q.number = 2) and explanation = 'يستعمل الكتاب الرمز X للكسر المولي مع الإشارة إلى المذيب أو المذاب، مثل XA وXB.';
update public.question_answers set explanation = 'خطوات التحضير: تُقاس كتلة المذاب وتُضاف إلى دورق حجمي، ثم يُذاب في أقل كمية من الماء المقطر، ثم يُضاف الماء حتى العلامة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O13' and q.type = 'mcq' and q.number = 2) and explanation = 'خطوات الشكل 1-5: تُقاس كتلة المذاب وتُضاف إلى دورق حجمي، ثم يُذاب في أقل كمية من الماء المقطر، ثم يُضاف الماء حتى العلامة.';
update public.question_answers set explanation = 'في الخطوة الأخيرة يُضاف الماء المقطر حتى يصل مستوى المحلول إلى العلامة المحددة على الدورق.', distractor_notes = '["الذوبان يحدث قبل الخطوة الأخيرة، ثم يُكمل الحجم.","المطلوب أن يكون حجم المحلول لا الماء مساويًا لحجم الدورق.","","الحجم المحدد عند العلامة لا عند الفوهة."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L2-O13' and q.type = 'mcq' and q.number = 4) and explanation = 'في الخطوة 3 من الشكل 1-5 يُضاف الماء المقطر حتى يصل مستوى المحلول إلى العلامة المحددة على الدورق.';
update public.question_answers set explanation = 'الذوبان هو عملية إحاطة جسيمات المذاب بجسيمات المذيب؛ إذ تجذب جسيمات المذيب جسيمات المذاب وتفصلها عن بعضها وتحيط بها.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O01' and q.type = 'mcq' and q.number = 1) and explanation = 'يعرّف الكتاب الذوبان بأنه عملية إحاطة جسيمات المذاب بجسيمات المذيب؛ إذ تجذب جسيمات المذيب جسيمات المذاب وتفصلها عن بعضها وتحيط بها.';
update public.question_answers set explanation = 'إذا كانت قوى التجاذب المتكونة بين جسيمات المذاب والمذيب أكبر من قوى التجاذب بين جسيمات المذاب نفسه، فسوف تجذب جسيمات المذيب جسيمات المذاب وتفصلها وتحيط بها.', distractor_notes = '["","في هذه الحالة تبقى جسيمات المذاب متماسكة ولا يحدث الذوبان، كما في الجبس.","الكتلة لا تحدد حدوث الذوبان، بل المقارنة بين قوى التجاذب.","درجات الانصهار والغليان ليست شرط الذوبان."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O01' and q.type = 'mcq' and q.number = 3) and explanation = 'ينص الكتاب على أنه إذا كانت قوى التجاذب المتكونة بين جسيمات المذاب والمذيب أكبر من قوى التجاذب بين جسيمات المذاب نفسه، فسوف تجذب جسيمات المذيب جسيمات المذاب وتفصلها وتحيط بها.';
update public.question_answers set explanation = 'قاعدة «المذيب يذيب شبيهه» قاعدة عامة تُستعمل لتحديد ما إذا كانت عملية الذوبان تحدث في مذيب معين.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O01' and q.type = 'mcq' and q.number = 4) and explanation = 'يصف الكتاب قاعدة «المذيب يذيب شبيهه» بأنها قاعدة عامة تُستعمل لتحديد ما إذا كانت عملية الذوبان تحدث في مذيب معين.';
update public.question_answers set explanation = 'لتحديد ما إذا كان المذيب والمذاب متماثلين تجب دراسة قطبية المركبات ونوع الروابط بين الجزيئية فيها.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O01' and q.type = 'mcq' and q.number = 5) and explanation = 'يذكر الكتاب أنه لتحديد ما إذا كان المذيب والمذاب متماثلين تجب دراسة قطبية المركبات ونوع الروابط بين الجزيئية فيها.';
update public.question_answers set explanation = 'تحيط جسيمات المذيب بسطح المذاب الصلب، ثم تجذب جسيماته وتفصلها عن بعضها وتحيط بها، ثم تبتعد الجسيمات المحاطة عن المذاب الصلب وتتجه نحو المحلول.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O01' and q.type = 'mcq' and q.number = 6) and explanation = 'بحسب الكتاب: تحيط جسيمات المذيب بسطح المذاب الصلب، ثم تجذب جسيماته وتفصلها عن بعضها وتحيط بها، ثم تبتعد الجسيمات المحاطة عن المذاب الصلب وتتجه نحو المحلول.';
update public.question_answers set explanation = 'شرط الذوبان أن تتغلب قوى التجاذب بين المذاب والمذيب على قوى التجاذب بين جسيمات المذاب، فإذا كانت الأخيرة أقوى بقيت المادة متماسكة ولا تذوب، كما في الجبس.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O01' and q.type = 'mcq' and q.number = 7) and explanation = 'شرط الذوبان أن تتغلب قوى التجاذب بين المذاب والمذيب على قوى التجاذب بين جسيمات المذاب، فإذا كانت الأخيرة أقوى بقيت المادة متماسكة ولا تذوب، كما يذكر الكتاب عن الجبس.';
update public.question_answers set rubric = '[{"level":"4","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"2–3","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O01' and q.type = 'essay' and q.number = 1) and rubric is not distinct from '[{"level":"4","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات الكتاب."},{"level":"2–3","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb;
