update public.question_answers set explanation = 'أقطاب جزيئات الماء المشحونة تجذب أيونات الصوديوم والكلوريد، وهذا التجاذب أكبر من التجاذب بين الأيونات في البلورة، لذلك تنزلق الأيونات مبتعدة عن سطح البلورة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O02' and q.type = 'mcq' and q.number = 2) and explanation = 'يذكر الكتاب أن أقطاب جزيئات الماء المشحونة تجذب أيونات الصوديوم والكلوريد، وأن هذا التجاذب أكبر من التجاذب بين الأيونات في البلورة، لذلك تنزلق الأيونات مبتعدة عن سطح البلورة.';
update public.question_answers set explanation = 'أيون Na⁺ موجب، فتجذبه أقطاب جزيئات الماء ذات الشحنة المخالفة، وهي الطرف السالب جزئيًا من الجزيء (ذرة الأكسجين).' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O02' and q.type = 'mcq' and q.number = 3) and explanation = 'أيون Na⁺ موجب، فتجذبه أقطاب جزيئات الماء ذات الشحنة المخالفة، وهي الطرف السالب جزئيًا من الجزيء (ذرة الأكسجين)، كما يظهر في إحاطة جزيئات الماء بالأيونات في الشكل 1-9.';
update public.question_answers set explanation = 'لا يمكن إذابة جميع المركبات الأيونية في الماء؛ فالجبس لا يذوب لأن قوى التجاذب بين أيوناته قوية لا تستطيع قوى التجاذب بين جزيئات الماء والأيونات التغلب عليها.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O02' and q.type = 'mcq' and q.number = 4) and explanation = 'يقرر الكتاب أنه لا يمكن إذابة جميع المركبات الأيونية في الماء؛ فالجبس لا يذوب لأن قوى التجاذب بين أيوناته قوية لا تستطيع قوى التجاذب بين جزيئات الماء والأيونات التغلب عليها.';
update public.question_answers set explanation = 'تحيط جزيئات الماء بالأيونات وتسحبها نحو المحلول، معرّضة أيونات أخرى على سطح البلورة للذوبان، وهكذا تستمر العملية حتى تذوب البلورة كلها.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O02' and q.type = 'mcq' and q.number = 5) and explanation = 'بحسب الكتاب تحيط جزيئات الماء بالأيونات وتسحبها نحو المحلول، معرّضة أيونات أخرى على سطح البلورة للذوبان، وهكذا تستمر العملية حتى تذوب البلورة كلها.';
update public.question_answers set distractor_notes = '["كل المركبات الأيونية مكونة من أيونات مشحونة؛ الفرق في شدة التجاذب لا في وجود الشحنة.","المعطى أن كليهما أيوني؛ وبعض المركبات الأيونية لا تذوب.","قطبية الماء خاصية ثابتة له لا تتغير بتغير المذاب.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O02' and q.type = 'mcq' and q.number = 7) and distractor_notes is not distinct from '["كل المركبات الأيونية مكونة من أيونات مشحونة؛ الفرق في شدة التجاذب لا في وجود الشحنة.","المعطى أن كليهما أيوني؛ وعدم ذوبان بعض المركبات الأيونية أمر يقرره الكتاب.","قطبية الماء خاصية ثابتة له لا تتغير بتغير المذاب.",""]'::jsonb;
