update public.question_answers set distractor_notes = '["11 هو عدد ذرات الأكسجين في الصيغة، وليست كلها مرتبطة بالهيدروجين.","","22 هو عدد ذرات الهيدروجين في الصيغة، ومعظمها مرتبط بالكربون لا بالأكسجين.","العدد أقل من الصحيح؛ الجزيء يحتوي على 8 روابط O–H."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O03' and q.type = 'mcq' and q.number = 1) and distractor_notes is not distinct from '["11 هو عدد ذرات الأكسجين في الصيغة، وليست كلها مرتبطة بالهيدروجين.","","22 هو عدد ذرات الهيدروجين في الصيغة، ومعظمها مرتبط بالكربون لا بالأكسجين.","العدد أقل من الوارد في الكتاب؛ الجزيء يحتوي على 8 روابط O–H."]'::jsonb;
update public.question_answers set explanation = 'بمجرد ملامسة بلورات السكر الماءَ تصطدم جزيئات الماء بسطحها، وتصبح كل رابطة O–H في السكروز موقعًا لتكوين روابط هيدروجينية مع الماء.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O03' and q.type = 'mcq' and q.number = 2) and explanation = 'بمجرد ملامسة بلورات السكر الماءَ تصطدم جزيئات الماء بسطحها، وتصبح كل رابطة O–H في السكروز موقعًا لتكوين روابط هيدروجينية مع الماء، كما ينص الكتاب.';
update public.question_answers set explanation = 'قوى التجاذب بين جزيئات السكروز يتم التغلب عليها بقوى التجاذب التي تتكون بين جزيئاته وجزيئات الماء القطبية، فتترك جزيئات السكروز البلورة وتصبح ذائبة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O03' and q.type = 'mcq' and q.number = 3) and explanation = 'يذكر الكتاب أن قوى التجاذب بين جزيئات السكروز يتم التغلب عليها بقوى التجاذب التي تتكون بين جزيئاته وجزيئات الماء القطبية، فتترك جزيئات السكروز البلورة وتصبح ذائبة.';
update public.question_answers set explanation = 'عند ذوبان السكروز تترك جزيئاته البلورة وتصبح ذائبة في الماء؛ أي تبقى جزيئات كاملة مرتبطة بالماء بروابط هيدروجينية، لأنه مركب جزيئي لا يتكون من أيونات.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O03' and q.type = 'mcq' and q.number = 4) and explanation = 'يصف الكتاب ذوبان السكروز بأن جزيئاته تترك البلورة وتصبح ذائبة في الماء؛ أي تبقى جزيئات كاملة مرتبطة بالماء بروابط هيدروجينية، لأنه مركب جزيئي لا يتكون من أيونات.';
