update public.question_answers set explanation = 'التحريك إحدى ثلاث طرائق شائعة لزيادة التصادمات بين جسيمات المذاب والمذيب وزيادة سرعة الذوبان.', distractor_notes = '["التحريك يسرّع الذوبان ولا يبطئه.","سرعة ذوبان مكعب السكر تزداد عند تحريكه.","","التحريك لا يوقف الذوبان بل يسرّعه."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O04' and q.type = 'mcq' and q.number = 1) and explanation = 'يعدّ الكتاب التحريك إحدى ثلاث طرائق شائعة لزيادة التصادمات بين جسيمات المذاب والمذيب وزيادة سرعة الذوبان (الشكل 1-12).';
update public.question_answers set distractor_notes = '["","التحريك لا يكسر الجزيئات؛ هو ينقل الجسيمات الذائبة بعيدًا عن سطح التماس.","رفع درجة الحرارة عامل مستقل، والتحريك لا يسخّن المحلول تسخينًا يُذكر.","التحريك يؤثر في سرعة الذوبان لا في الذائبية."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O04' and q.type = 'mcq' and q.number = 2) and distractor_notes is not distinct from '["","التحريك لا يكسر الجزيئات؛ هو ينقل الجسيمات الذائبة بعيدًا عن سطح التماس.","رفع درجة الحرارة عامل مستقل في الكتاب، والتحريك لا يسخّن المحلول تسخينًا يُذكر.","التحريك يؤثر في سرعة الذوبان لا في الذائبية."]'::jsonb;
update public.question_answers set explanation = 'من دون تحريك المحلول تتحرك الجسيمات الذائبة بعيدًا عن مناطق التماس ببطء، فتقل التصادمات الجديدة ويكون الذوبان أبطأ.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O04' and q.type = 'mcq' and q.number = 3) and explanation = 'يذكر الكتاب أنه من دون تحريك المحلول تتحرك الجسيمات الذائبة بعيدًا عن مناطق التماس ببطء، فتقل التصادمات الجديدة ويكون الذوبان أبطأ.';
update public.question_answers set explanation = 'تثبيت حجم المكعب ودرجة الحرارة يجعل التحريك المتغير الوحيد، والتحريك يزيد سرعة الذوبان، فيذوب مكعب السكر في الكوب المحرّك أسرع.', distractor_notes = '["التحريك يسرّع الذوبان، فلا يكون الكوب الساكن أسرع.","التحريك المتغير الوحيد بين الكوبين وهو يؤثر في سرعة الذوبان.","السكر يذوب في الشاي المثلج ولكن ببطء.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O04' and q.type = 'mcq' and q.number = 4) and explanation = 'تثبيت حجم المكعب ودرجة الحرارة يجعل التحريك المتغير الوحيد، والتحريك يزيد سرعة الذوبان، فيذوب مكعب السكر في الكوب المحرّك أسرع (الشكل 1-12).';
update public.question_answers set explanation = 'يحدث الذوبان عند تصادم جسيمات المذاب والمذيب معًا، والطرائق الثلاث هي طرائق لزيادة التصادمات بين جسيمات المذاب والمذيب وزيادة سرعة الذوبان.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O04' and q.type = 'mcq' and q.number = 5) and explanation = 'يحدث الذوبان عند تصادم جسيمات المذاب والمذيب معًا، ويصف الكتاب الطرائق الثلاث بأنها طرائق لزيادة التصادمات بين جسيمات المذاب والمذيب وزيادة سرعة الذوبان.';
update public.question_answers set distractor_notes = '["العبارة عكست الأثر؛ التحريك يغير السرعة لا الذائبية.","الذائبية لا تتغير بالتحريك عند ثبوت درجة الحرارة.","","التحريك يزيد سرعة الذوبان."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O04' and q.type = 'mcq' and q.number = 6) and distractor_notes is not distinct from '["العبارة عكست الأثر؛ التحريك يغير السرعة لا الذائبية.","الذائبية لا تتغير بالتحريك عند ثبوت درجة الحرارة.","","التحريك يزيد سرعة الذوبان كما يبين الشكل 1-12."]'::jsonb;
