update public.question_answers set explanation = 'ملعقة من السكر المطحون تذوب أسرع من الكمية نفسها التي تكون في صورة مكعبات، لأن مساحة سطحها أكبر.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O05' and q.type = 'mcq' and q.number = 1) and explanation = 'ينص الكتاب على أن ملعقة من السكر المطحون تذوب أسرع من الكمية نفسها التي تكون في صورة مكعبات، لأن مساحة سطحها أكبر.';
