update public.question_answers set explanation = 'نص قانون هنري: «تتناسب ذائبية الغاز في سائل (S) تناسبًا طرديًا مع ضغط الغاز (P) الموجود فوق السائل عند ثبوت درجة الحرارة».' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O06' and q.type = 'mcq' and q.number = 1) and explanation = 'نص قانون هنري في الكتاب: «تتناسب ذائبية الغاز في سائل (S) تناسبًا طرديًا مع ضغط الغاز (P) الموجود فوق السائل عند ثبوت درجة الحرارة».';
update public.question_answers set explanation = 'يُمثَّل قانون هنري بالعلاقة S₁/P₁ = S₂/P₂، أي إن ناتج قسمة الذائبية على الضغط ثابت عند درجة حرارة معينة، وهذا تعبير عن التناسب الطردي.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O06' and q.type = 'mcq' and q.number = 2) and explanation = 'يمثّل الكتاب قانون هنري بالعلاقة S₁/P₁ = S₂/P₂، أي إن ناتج قسمة الذائبية على الضغط ثابت عند درجة حرارة معينة، وهذا تعبير عن التناسب الطردي.';
update public.question_answers set explanation = 'في قانون هنري يمثل S الذائبية ويمثل P الضغط.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O06' and q.type = 'mcq' and q.number = 3) and explanation = 'يوضح الكتاب في مربع قانون هنري أن S يمثل الذائبية وP يمثل الضغط.';
update public.question_answers set explanation = 'ينص قانون هنري على أنه «يبقى ناتج قسمة الذائبية على الضغط ثابتًا عند درجة حرارة معينة»، أي S/P = ثابت.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O06' and q.type = 'mcq' and q.number = 4) and explanation = 'ينص الكتاب على أنه «يبقى ناتج قسمة الذائبية على الضغط ثابتًا عند درجة حرارة معينة»، أي S/P = ثابت.';
update public.question_answers set explanation = 'المشروبات الغازية تحتوي على غاز CO₂ المذاب في محلول مائي تحت ضغط أعلى من الضغط الجوي.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O07' and q.type = 'mcq' and q.number = 1) and explanation = 'يذكر الكتاب أن المشروبات الغازية تحتوي على غاز CO₂ المذاب في محلول مائي تحت ضغط أعلى من الضغط الجوي.';
update public.question_answers set explanation = 'يمكن وصف انخفاض ذائبية غاز ثاني أكسيد الكربون في المشروب الغازي بعد فتح العبوة بقانون هنري، الذي يربط ذائبية الغاز بضغطه فوق السائل.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O07' and q.type = 'mcq' and q.number = 3) and explanation = 'ينص الكتاب على أنه «يمكن وصف انخفاض ذائبية غاز ثاني أكسيد الكربون في المشروب الغازي بعد فتح العبوة بقانون هنري» الذي يربط ذائبية الغاز بضغطه فوق السائل.';
update public.question_answers set explanation = 'الضغط الذي فوق السائل في القارورة المغلقة يحافظ على بقاء CO₂ ذائبًا في المحلول ويمنعه من التطاير.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O07' and q.type = 'mcq' and q.number = 4) and explanation = 'يوضح الشكل 1-17 أن الضغط الذي فوق السائل في القارورة المغلقة يحافظ على بقاء CO₂ ذائبًا في المحلول ويمنعه من التطاير.';
update public.question_answers set explanation = 'عملية تصاعد فقاعات CO₂ وتطايرها تستمر حتى يفقد المحلول غاز CO₂ كله تقريبًا، ويصبح المحلول بلا طعم.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O07' and q.type = 'mcq' and q.number = 5) and explanation = 'يذكر الكتاب أن عملية تصاعد فقاعات CO₂ وتطايرها تستمر حتى يفقد المحلول غاز CO₂ كله تقريبًا، ويصبح المحلول بلا طعم.';
update public.question_answers set explanation = 'خلال تسرب CO₂ من المحلول يزداد الضغط داخل القارورة المغلقة. وبارتفاع الضغط فوق السائل تزداد ذائبية الغاز وفق قانون هنري، فيتباطأ خروج CO₂ من المحلول ويبقى جزء منه مذابًا.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O07' and q.type = 'mcq' and q.number = 6) and explanation = 'يذكر الكتاب في المفردات أنه خلال تسرب CO₂ من المحلول يزداد الضغط داخل القارورة المغلقة. وبارتفاع الضغط فوق السائل تزداد ذائبية الغاز وفق قانون هنري، فيتباطأ خروج CO₂ من المحلول ويبقى جزء منه مذابًا.';
update public.question_answers set explanation = 'المحلول غير المشبع هو المحلول الذي يحتوي على كمية مذاب أقل مما في المحلول المشبع عند درجة حرارة وضغط معينين.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O09' and q.type = 'mcq' and q.number = 1) and explanation = 'يعرّف الكتاب المحلول غير المشبع بأنه المحلول الذي يحتوي على كمية مذاب أقل مما في المحلول المشبع عند درجة حرارة وضغط معينين.';
update public.question_answers set explanation = 'المحلول غير المشبع يمكن إضافة كميات أكبر من المذاب إليه لتذوب، لأنه يحتوي على كمية أقل من أقصى ما يمكن أن يذوب.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O09' and q.type = 'mcq' and q.number = 2) and explanation = 'يذكر الكتاب أن المحلول غير المشبع يمكن إضافة كميات أكبر من المذاب إليه لتذوب، لأنه يحتوي على كمية أقل من أقصى ما يمكن أن يذوب.';
update public.question_answers set explanation = 'ثلاث طرائق شائعة لزيادة التصادمات وسرعة الذوبان: التحريك، وزيادة مساحة سطح المذاب، ورفع درجة حرارة المذيب.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O12' and q.type = 'mcq' and q.number = 1) and explanation = 'يبين الشكل 1-12 ثلاث طرائق شائعة لزيادة التصادمات وسرعة الذوبان: التحريك، وزيادة مساحة سطح المذاب، ورفع درجة حرارة المذيب.';
update public.question_answers set distractor_notes = '["كتلة المذيب لا تتغير بالتسخين، والسبب تغير الذائبية نفسها.","المذاب يبقى المادة نفسها؛ الذي يتغير هو أقصى كمية تذوب.","الذائبية تختلف باختلاف المواد عند الدرجة نفسها.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O13' and q.type = 'mcq' and q.number = 6) and distractor_notes is not distinct from '["كتلة المذيب لا تتغير بالتسخين، والسبب تغير الذائبية نفسها.","المذاب يبقى المادة نفسها؛ الذي يتغير هو أقصى كمية تذوب.","الذائبية تختلف باختلاف المواد عند الدرجة نفسها، كما يبين الجدول 1-4.",""]'::jsonb;
update public.question_answers set explanation = 'في المحلول المشبع يصل النظام إلى حالة اتزان ديناميكي تتساوى فيها سرعة الذوبان وسرعة التبلور، لذا لا تتغير كمية المذاب الذائبة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O14' and q.type = 'mcq' and q.number = 2) and explanation = 'في المحلول المشبع يصل النظام إلى حالة اتزان ديناميكي تتساوى فيها سرعة الذوبان وسرعة التبلور، لذا لا تتغير كمية المذاب الذائبة (الشكل 1-13).';
update public.question_answers set distractor_notes = '["التبريد لا يزيد الذائبية؛ فذائبية معظم المواد الصلبة تقل بانخفاض الحرارة.","","لو تبلورت الزيادة لنتج محلول مشبع لا فوق مشبع.","التبريد لا يهدف إلى تبخير المذيب، بل إلى إبقاء الزيادة ذائبة."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O16' and q.type = 'mcq' and q.number = 2) and distractor_notes is not distinct from '["التبريد لا يزيد الذائبية؛ فذائبية معظم المواد الصلبة تقل بانخفاض الحرارة.","","لو تبلورت الزيادة لنتج محلول مشبع لا فوق مشبع.","التبريد لا يهدف إلى تبخير المذيب، والكتاب يربط الطريقة ببقاء الزيادة ذائبة."]'::jsonb;
update public.question_answers set explanation = 'المحاليل فوق المشبعة غير ثابتة؛ فعند إضافة قطعة صغيرة جدًّا من المذاب تسمى نواة التبلور تترسب المادة المذابة الزائدة بسرعة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O16' and q.type = 'mcq' and q.number = 3) and explanation = 'المحاليل فوق المشبعة غير ثابتة؛ فعند إضافة قطعة صغيرة جدًّا من المذاب تسمى نواة التبلور تترسب المادة المذابة الزائدة بسرعة (الشكل 1-15).';
update public.question_answers set explanation = 'تنخفض ذائبية Ca(OH)₂ من 0.189 عند 0 °C إلى 0.076 عند 100 °C، فهي من المواد القليلة التي تقل ذائبيتها بزيادة درجة الحرارة (مثل كبريتات السيريوم).' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O17' and q.type = 'mcq' and q.number = 3) and explanation = 'تنخفض ذائبية Ca(OH)₂ من 0.189 عند 0 °C إلى 0.076 عند 100 °C، فهي من المواد القليلة التي تقل ذائبيتها بزيادة درجة الحرارة (مثل كبريتات السيريوم في الشكل 1-14).';
update public.question_answers set explanation = 'مقدار الزيادة = 487.2 − 203.9 = 283.3 g، والنسبة = (283.3 / 203.9) × 100 ≈ 139% أي نحو 140%.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O17' and q.type = 'mcq' and q.number = 4) and explanation = 'مقدار الزيادة = 487.2 − 203.9 = 283.3 g، والنسبة = (283.3 / 203.9) × 100 ≈ 139% أي نحو 140%، كما ورد في الكتاب.';
update public.question_answers set explanation = 'عند 20 °C: NaCl (35.9) > KCl (34.2)، وعند 60 °C: KCl (45.8) > NaCl (37.1)؛ فمنحنيا الذائبية يتقاطعان بين 20 °C و60 °C.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O17' and q.type = 'mcq' and q.number = 5) and explanation = 'عند 20 °C: NaCl (35.9) > KCl (34.2)، وعند 60 °C: KCl (45.8) > NaCl (37.1)؛ فمنحنيا الذائبية يتقاطعان بين 20 °C و60 °C، وهذا ما يظهر في الشكل 1-14.';
update public.question_answers set distractor_notes = '["ارتفاع الحرارة لا يغير قطبية جسيمات الغاز.","","التفسير يعتمد على الطاقة الحركية لا على تغير الضغط.","ارتفاع الحرارة يزيد الطاقة الحركية ولا يقللها."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L3-O18' and q.type = 'mcq' and q.number = 2) and distractor_notes is not distinct from '["ارتفاع الحرارة لا يغير قطبية جسيمات الغاز.","","التفسير في الكتاب يعتمد على الطاقة الحركية لا على تغير الضغط.","ارتفاع الحرارة يزيد الطاقة الحركية ولا يقللها."]'::jsonb;
update public.question_answers set explanation = 'الخواص الجامعة هي الخواص الفيزيائية للمحاليل التي تتأثر بعدد جسيمات المذاب وليس بطبيعتها، فالبديل الصحيح هو «الخواص الفيزيائية للمحاليل التي تتأثر بعدد جسيمات المذاب وليس بطبيعتها».' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O01' and q.type = 'mcq' and q.number = 1) and explanation = 'عرّف الكتاب الخواص الجامعة بأنها الخواص الفيزيائية للمحاليل التي تتأثر بعدد جسيمات المذاب وليس بطبيعتها، فالبديل الصحيح هو «الخواص الفيزيائية للمحاليل التي تتأثر بعدد جسيمات المذاب وليس بطبيعتها».';
update public.question_answers set explanation = 'الانخفاض في الضغط البخاري يعتمد على عدد جسيمات المذاب في المحلول، ولذلك فهو من الخواص الجامعة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O01' and q.type = 'mcq' and q.number = 5) and explanation = 'ذكر الكتاب أن الانخفاض في الضغط البخاري يعتمد على عدد جسيمات المذاب في المحلول، ولذلك فهو من الخواص الجامعة.';
update public.question_answers set explanation = 'هذا هو تعريف الخواص الجامعة: الخواص الفيزيائية للمحاليل التي تتأثر بعدد جسيمات المذاب وليس بطبيعتها؛ فالإجابة «الخواص الجامعة».' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O01' and q.type = 'mcq' and q.number = 7) and explanation = 'هذا هو تعريف الكتاب للخواص الجامعة: الخواص الفيزيائية للمحاليل التي تتأثر بعدد جسيمات المذاب وليس بطبيعتها؛ فالإجابة «الخواص الجامعة».';
update public.question_answers set explanation = 'إضافة الملح تقلل درجة تجمد الماء فيبقى سائلًا عند درجات أقل من 0 °C وينصهر الجليد، وهذه هي خاصية الانخفاض في درجة التجمد.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O02' and q.type = 'mcq' and q.number = 5) and explanation = 'إضافة الملح تقلل درجة تجمد الماء فيبقى سائلًا عند درجات أقل من 0 °C وينصهر الجليد، وهذه هي خاصية الانخفاض في درجة التجمد (الشكل 1-21).';
update public.question_answers set explanation = 'الضغط الأسموزي هو كمية الضغط الإضافي الناتج عن انتقال جزيئات الماء إلى المحلول المركز، وهو خاصية جامعة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O02' and q.type = 'mcq' and q.number = 6) and explanation = 'عرّف الكتاب الضغط الأسموزي بأنه كمية الضغط الإضافي الناتج عن انتقال جزيئات الماء إلى المحلول المركز، وهو خاصية جامعة.';
update public.question_answers set explanation = 'تتناسب قيمة الارتفاع في درجة الغليان ΔTb تناسبًا طرديًا مع مولالية المحلول (ΔTb = Kb·m)، فالإجابة «يتناسب طرديًا مع المولالية».' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O03' and q.type = 'mcq' and q.number = 1) and explanation = 'نص الكتاب: تتناسب قيمة الارتفاع في درجة الغليان ΔTb تناسبًا طرديًا مع مولالية المحلول (ΔTb = Kb·m)، فالإجابة «يتناسب طرديًا مع المولالية».';
update public.question_answers set explanation = 'المولالية مرتبطة بالكسر المولي الذي يتضمن عدد جسيمات المذاب، وتعبر عن المذيب بالكتلة بدلًا من الحجم، ولذلك لا تتأثر بتغير درجة الحرارة التي تتغير في أثناء التسخين للغليان.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O03' and q.type = 'mcq' and q.number = 5) and explanation = 'ذكر الكتاب أن المولالية مرتبطة بالكسر المولي الذي يتضمن عدد جسيمات المذاب، وأنها تعبر عن المذيب بالكتلة بدلًا من الحجم، ولذلك لا تتأثر بتغير درجة الحرارة التي تتغير في أثناء التسخين للغليان.';
update public.question_answers set explanation = 'Kb هو الفرق بين درجة غليان محلول يحتوي على 1 m من مذاب غير متطاير وغير متأين ودرجة غليان المذيب النقي، ووحدته °C/m.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O03' and q.type = 'mcq' and q.number = 7) and explanation = 'عرّف الكتاب Kb بأنه الفرق بين درجة غليان محلول يحتوي على 1 m من مذاب غير متطاير وغير متأين ودرجة غليان المذيب النقي، ووحدته °C/m.';
update public.question_answers set explanation = 'المذاب غير المتطاير يؤثر في درجة غليان المذيب لأنه يقلل الضغط البخاري له، فيحتاج المحلول إلى درجة أعلى ليعادل ضغطه البخاري الضغط الجوي.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O04' and q.type = 'mcq' and q.number = 1) and explanation = 'ذكر الكتاب أن المذاب غير المتطاير يؤثر في درجة غليان المذيب لأنه يقلل الضغط البخاري له، فيحتاج المحلول إلى درجة أعلى ليعادل ضغطه البخاري الضغط الجوي.';
update public.question_answers set explanation = 'الضغط الأسموزي هو كمية الضغط الإضافي الناتج عن انتقال جزيئات الماء إلى المحلول المركز عبر الغشاء شبه المنفذ.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O06' and q.type = 'mcq' and q.number = 1) and explanation = 'عرّف الكتاب الضغط الأسموزي بأنه كمية الضغط الإضافي الناتج عن انتقال جزيئات الماء إلى المحلول المركز (عبر الغشاء شبه المنفذ في الشكل 1-22).';
update public.question_answers set explanation = 'يعتمد الضغط الأسموزي على عدد جسيمات المذاب في كمية محددة من المحلول، وهو خاصية جامعة للمحاليل.', distractor_notes = '["الضغط الأسموزي خاصية جامعة لا تعتمد على نوع المذاب أو حجم جسيماته.","","الضغط الأسموزي لا يرتبط بمساحة الغشاء، بل بعدد جسيمات المذاب.","الضغط الأسموزي ينتج عن انتقال الماء عبر الغشاء لا عن الضغط الجوي."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O06' and q.type = 'mcq' and q.number = 3) and explanation = 'نص الكتاب: يعتمد الضغط الأسموزي على عدد جسيمات المذاب في كمية محددة من المحلول، وهو خاصية جامعة للمحاليل.';
update public.question_answers set explanation = 'المواد المتأينة التي تنتج عددًا قليلًا من الأيونات في المحلول تسمى مواد متأينة ضعيفة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O07' and q.type = 'mcq' and q.number = 2) and explanation = 'عرّف الكتاب المواد المتأينة التي تنتج عددًا قليلًا من الأيونات في المحلول بأنها مواد متأينة ضعيفة.';
update public.question_answers set explanation = 'كلوريد الصوديوم مادة متأينة قوية تتفكك في الماء إلى Na⁺ وCl⁻ فيوصل محلوله التيار، أما السكروز فمادة غير متأينة تذوب جزيئاتها دون تفكك فلا يوصل محلوله التيار.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O07' and q.type = 'mcq' and q.number = 4) and explanation = 'كلوريد الصوديوم مادة متأينة قوية تتفكك في الماء إلى Na⁺ وCl⁻ فيوصل محلوله التيار، أما السكروز فمادة غير متأينة تذوب جزيئاته دون تفكك فلا يوصل محلوله التيار (الشكل 1-18).';
update public.question_answers set explanation = 'الجليسرول مذاب غير متأين، بينما NaCl وNa₂SO₄ وAlCl₃ مواد متأينة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O07' and q.type = 'mcq' and q.number = 5) and explanation = 'ذكر الكتاب أن الجليسرول مذاب غير متأين، بينما NaCl وNa₂SO₄ وAlCl₃ مواد متأينة.';
update public.question_answers set explanation = 'يُميَّز بينهما بعدد الأيونات الناتجة: المواد المتأينة القوية تنتج أيونات كثيرة في المحلول، والضعيفة تنتج عددًا قليلًا من الأيونات.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O07' and q.type = 'mcq' and q.number = 6) and explanation = 'يميز الكتاب بينهما بعدد الأيونات الناتجة: المواد المتأينة القوية تنتج أيونات كثيرة في المحلول، والضعيفة تنتج عددًا قليلًا من الأيونات.';
update public.question_answers set explanation = 'القليل من المركبات الجزيئية يتأين في الماء ويكوّن محلولًا متأينًا، والمادة التي تنتج عددًا قليلًا من الأيونات متأينة ضعيفة؛ فـ X مادة متأينة ضعيفة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O07' and q.type = 'mcq' and q.number = 7) and explanation = 'ذكر الكتاب أن القليل من المركبات الجزيئية يتأين في الماء ويكوّن محلولًا متأينًا، وأن المادة التي تنتج عددًا قليلًا من الأيونات متأينة ضعيفة؛ فـ X مادة متأينة ضعيفة.';
update public.question_answers set explanation = 'الضغط البخاري هو الضغط الناتج عن بخار السائل عندما يكون في حالة اتزان ديناميكي مع سائله في وعاء مغلق عند درجة حرارة وضغط ثابتين.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O09' and q.type = 'mcq' and q.number = 1) and explanation = 'عرّف الكتاب الضغط البخاري بأنه الضغط الناتج عن بخار السائل عندما يكون في حالة اتزان ديناميكي مع سائله في وعاء مغلق عند درجة حرارة وضغط ثابتين.';
update public.question_answers set explanation = 'في المحلول يحتل المذاب جزءًا من مساحة السطح، فيتحول عدد أقل من جسيمات المذيب إلى الحالة الغازية وينخفض الضغط البخاري.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O09' and q.type = 'mcq' and q.number = 3) and explanation = 'في المحلول يحتل المذاب جزءًا من مساحة السطح (الشكل 1-19 b)، فيتحول عدد أقل من جسيمات المذيب إلى الحالة الغازية وينخفض الضغط البخاري.';
update public.question_answers set explanation = 'سطح المحلول يشغله مذاب ومذيب معًا، فيقل عدد جسيمات المذيب المتبخرة وينخفض الضغط البخاري.', distractor_notes = '["هذا تصور المذيب النقي.","جسيمات المذيب تبقى على السطح ويتبخر بعضها.","","المذاب غير المتطاير لا يتبخر."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O09' and q.type = 'mcq' and q.number = 7) and explanation = 'يبين الشكل 1-19 b أن سطح المحلول يشغله مذاب ومذيب معًا، فيقل عدد جسيمات المذيب المتبخرة وينخفض الضغط البخاري.';
update public.question_answers set explanation = 'الانخفاض في درجة التجمد ΔTf هو درجة تجمد المذيب النقي مطروحًا منها درجة تجمد المحلول.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O10' and q.type = 'mcq' and q.number = 2) and explanation = 'عرّف الكتاب الانخفاض في درجة التجمد ΔTf بأنه درجة تجمد المذيب النقي مطروحًا منها درجة تجمد المحلول.';
update public.question_answers set explanation = 'إضافة الأملاح إلى الجليد تقلل درجة تجمده، مما يؤدي إلى انصهار الجليد على الطرق.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O11' and q.type = 'mcq' and q.number = 1) and explanation = 'ذكر الكتاب (الشكل 1-21) أن إضافة الأملاح إلى الجليد تقلل درجة تجمده، مما يؤدي إلى انصهار الجليد على الطرق.';
update public.question_answers set explanation = 'إضافة الملح إلى الجليد عند صنع الآيس كريم تقلل درجة التجمد، مما يسمح للماء الناتج بتجميد الآيس كريم.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O11' and q.type = 'mcq' and q.number = 2) and explanation = 'ذكر الكتاب أن إضافة الملح إلى الجليد عند صنع الآيس كريم تقلل درجة التجمد، مما يسمح للماء الناتج بتجميد الآيس كريم.';
update public.question_answers set explanation = 'مقاوم التجمد (مانع تكوّن الجليد) يحتوي على مذاب غير متأين هو جليكول الإيثيلين، ويستعمل لمنع تجمد الماء في الشتاء.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O11' and q.type = 'mcq' and q.number = 3) and explanation = 'ذكر الكتاب أن مقاوم التجمد (مانع تكوّن الجليد) يحتوي على مذاب غير متأين هو جليكول الإيثيلين، ويستعمل لمنع تجمد الماء في الشتاء.';
update public.question_answers set explanation = 'وجود الملح في المناطق القطبية من المحيط ضروري لمنع المياه من التجمد، مما يسمح بالمحافظة على الحياة البحرية.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O11' and q.type = 'mcq' and q.number = 4) and explanation = 'ذكر الكتاب أن وجود الملح في المناطق القطبية من المحيط ضروري لمنع المياه من التجمد، مما يسمح بالمحافظة على الحياة البحرية.';
update public.question_answers set explanation = 'الخاصية الأسموزية هي انتشار المذيب خلال غشاء شبه منفذ من المحلول الأقل تركيزًا إلى المحلول الأعلى تركيزًا.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O12' and q.type = 'mcq' and q.number = 1) and explanation = 'عرّف الكتاب الخاصية الأسموزية بأنها انتشار المذيب خلال غشاء شبه منفذ من المحلول الأقل تركيزًا إلى المحلول الأعلى تركيزًا.';
update public.question_answers set distractor_notes = '["التفسير يتعلق بخاصية الغشاء لا بخفة الجزيئات.","الغشاء شبه المنفذ يسمح لبعض الجسيمات (جزيئات الماء) بالعبور.","","جزيئات المذاب لا تنتقل لأنها لا تستطيع العبور وليس لانجذابها لجهة."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L4-O12' and q.type = 'mcq' and q.number = 3) and distractor_notes is not distinct from '["التفسير يتعلق بخاصية الغشاء لا بخفة الجزيئات، والكتاب لا يعلل بالكتلة.","الغشاء شبه المنفذ يسمح لبعض الجسيمات (جزيئات الماء) بالعبور.","","جزيئات المذاب لا تنتقل لأنها لا تستطيع العبور وليس لانجذابها لجهة."]'::jsonb;
update public.question_answers set explanation = 'المحاليل القاعدية طعمها مرّ ولها ملمس زلق، كما في قطعة الصابون عندما تبتل؛ فالخاصيتان هما: طعمها مر، وملمسها زلق.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O01' and q.type = 'mcq' and q.number = 2) and explanation = 'ذكر الكتاب أن المحاليل القاعدية طعمها مرّ ولها ملمس زلق، كما في قطعة الصابون عندما تبتل؛ فالخاصيتان هما: طعمها مر، وملمسها زلق.';
update public.question_answers set explanation = 'الليمون والجريب فروت طعمهما لاذع لاحتوائهما على حمضي الستريك والأسكوربيك.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O01' and q.type = 'mcq' and q.number = 3) and explanation = 'بيّن الكتاب أن الليمون والجريب فروت طعمهما لاذع لاحتوائهما على حمضي الستريك والأسكوربيك.';
update public.question_answers set distractor_notes = '["","التوصيل في المحاليل يتم بحركة الأيونات، لا بإلكترونات حرة كما في الفلزات.","جزيئات الماء وحدها لا توصل، فالماء النقي غير موصل للكهرباء.","ذوبان غازات الهواء ليس سبب التوصيل؛ السبب هو تأين الحمض أو القاعدة."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O01' and q.type = 'mcq' and q.number = 5) and distractor_notes is not distinct from '["","التوصيل في المحاليل يتم بحركة الأيونات، لا بإلكترونات حرة كما في الفلزات.","جزيئات الماء وحدها لا توصل، فالماء النقي غير موصل للكهرباء.","ذوبان غازات الهواء ليس سبب التوصيل الذي ذكره الكتاب؛ السبب هو تأين الحمض أو القاعدة."]'::jsonb;
update public.question_answers set distractor_notes = '["تغيّر لون ورق تبّاع الشمس ناتج عن تفاعل كيميائي، فهو من الخواص الكيميائية.","تفاعل الحمض مع الفلز ينتج مادة جديدة (H₂)، فهو خاصية كيميائية.","إنتاج غاز CO₂ من الكربونات تغيّر كيميائي، فهو خاصية كيميائية.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O01' and q.type = 'mcq' and q.number = 6) and distractor_notes is not distinct from '["تغيّر لون ورق تبّاع الشمس ناتج عن تفاعل كيميائي، وقد عدّه الكتاب من الخواص الكيميائية.","تفاعل الحمض مع الفلز ينتج مادة جديدة (H₂)، فهو خاصية كيميائية.","إنتاج غاز CO₂ من الكربونات تغيّر كيميائي، فهو خاصية كيميائية.",""]'::jsonb;
update public.question_answers set explanation = 'الملمس الزلق من الخواص الفيزيائية للمحاليل القاعدية، وتوصيل المحلول للكهرباء يدل على وجود أيونات؛ فالمادة قاعدة ومن أمثلتها الصابون.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O01' and q.type = 'mcq' and q.number = 7) and explanation = 'الملمس الزلق من الخواص الفيزيائية للمحاليل القاعدية، وتوصيل المحلول للكهرباء يدل على وجود أيونات؛ والصابون مثال الكتاب على ذلك، فالمادة قاعدة ومن أمثلتها الصابون.';
update public.question_answers set explanation = 'الخواص الكيميائية للأحماض: تحويل تبّاع الشمس الأزرق إلى الأحمر، والتفاعل مع فلزات مثل Mg وZn منتجة H₂، والتفاعل مع الكربونات والكربونات الهيدروجينية منتجة CO₂.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O02' and q.type = 'mcq' and q.number = 7) and explanation = 'الخواص الكيميائية للأحماض كما في الكتاب: تحويل تبّاع الشمس الأزرق إلى الأحمر، والتفاعل مع فلزات مثل Mg وZn منتجة H₂، والتفاعل مع الكربونات والكربونات الهيدروجينية منتجة CO₂.';
update public.question_answers set explanation = 'جميع جزيئات HCl تتحول إلى أيونات هيدرونيوم وأيونات كلوريد، فالجسيمات الرئيسة هي H₃O⁺ وCl⁻.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O03' and q.type = 'mcq' and q.number = 3) and explanation = 'يبيّن الشكل 2-11 أن جميع جزيئات HCl تتحول إلى أيونات هيدرونيوم وأيونات كلوريد، فالجسيمات الرئيسة هي H₃O⁺ وCl⁻.';
update public.question_answers set explanation = 'المحلول الحمضي هو المحلول الذي يحتوي على أيونات هيدروجين أكثر من أيونات الهيدروكسيد.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O05' and q.type = 'mcq' and q.number = 1) and explanation = 'عرّف الكتاب المحلول الحمضي بأنه المحلول الذي يحتوي على أيونات هيدروجين أكثر من أيونات الهيدروكسيد.';
update public.question_answers set explanation = 'أيون الهيدرونيوم هو أيون هيدروجين مرتبط مع جزيء ماء برابطة تساهمية، ويمكن استعمال الرمزين H⁺ وH₃O⁺ بالتبادل.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O05' and q.type = 'mcq' and q.number = 6) and explanation = 'عرّف الكتاب أيون الهيدرونيوم بأنه أيون هيدروجين مرتبط مع جزيء ماء برابطة تساهمية، ويمكن استعمال الرمزين H⁺ وH₃O⁺ بالتبادل.';
update public.question_answers set explanation = 'عندما يقل [H⁺] نحو اليمين تزداد قيمة [OH⁻]، والنقطة التي يتساوى فيها تركيزا الأيونين تمثّل المحلول المتعادل.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O05' and q.type = 'mcq' and q.number = 7) and explanation = 'يبيّن الشكل 2-3 أنه عندما يقل [H⁺] نحو اليمين تزداد قيمة [OH⁻]، والنقطة التي يتساوى فيها تركيزا الأيونين تمثّل المحلول المتعادل.';
update public.question_answers set explanation = 'تنص نظرية أرهينيوس على أن الحمض منتج لأيون H⁺ والقاعدة منتجة لأيون OH⁻.', distractor_notes = '["هذان تعريفا برونستد – لوري.","هذان تعريفا لويس.","الترتيب معكوس؛ الحمض ينتج H⁺ والقاعدة تنتج OH⁻.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O06' and q.type = 'mcq' and q.number = 3) and explanation = 'يلخص الجدول 2-2 نظرية أرهينيوس بأن الحمض منتج لأيون H⁺ والقاعدة منتجة لأيون OH⁻.';
update public.question_answers set distractor_notes = '["المياه تحمل كميات كبيرة من كربونات الصوديوم الذائبة لا هيدروكسيده.","الأمونيا مثال آخر على القصور، لكنها ليست سبب قاعدية بحيرة ناترون.","","حمض الكربونيك حمض، ولا يجعل الماء قاعديًا."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O07' and q.type = 'mcq' and q.number = 3) and distractor_notes is not distinct from '["ذكر الكتاب أن المياه تحمل كميات كبيرة من كربونات الصوديوم الذائبة لا هيدروكسيده.","الأمونيا مثال آخر على القصور، لكنها ليست سبب قاعدية بحيرة ناترون.","","حمض الكربونيك حمض، ولا يجعل الماء قاعديًا."]'::jsonb;
update public.question_answers set explanation = 'قصور أرهينيوس يستلزم نظرية أكثر دقة تشمل القواعد جميعها، وهي نظرية برونستد – لوري التي تعرّف القاعدة بأنها مستقبلة لأيون الهيدروجين، فتشمل الأمونيا.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O07' and q.type = 'mcq' and q.number = 7) and explanation = 'بيّن الكتاب أن قصور أرهينيوس يستلزم نظرية أكثر دقة تشمل القواعد جميعها، وهي نظرية برونستد – لوري التي تعرّف القاعدة بأنها مستقبلة لأيون الهيدروجين، فتشمل الأمونيا.';
update public.question_answers set explanation = 'بعض المواد التي لا تحتوي على مجموعة الهيدروكسيد لا تُعدّ قواعد أرهينيوس لكنها قواعد برونستد – لوري، ومنها الأمونيا التي تستقبل H⁺.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O08' and q.type = 'mcq' and q.number = 7) and explanation = 'ذكر الكتاب أن بعض المواد التي لا تحتوي على مجموعة الهيدروكسيد لا تُعدّ قواعد أرهينيوس لكنها قواعد برونستد – لوري، ومنها الأمونيا التي تستقبل H⁺.';
update public.question_answers set explanation = 'بفقد HNO₃ لأيون H⁺ ينتج NO₃⁻، وهو القاعدة المرافقة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O09' and q.type = 'mcq' and q.number = 2) and explanation = 'بفقد HNO₃ لأيون H⁺ ينتج NO₃⁻، وهو القاعدة المرافقة كما في الجدول 2-1.';
update public.question_answers set explanation = 'يمنح HCO₃⁻ أيون H⁺ فيتحول إلى CO₃²⁻، وهي القاعدة المرافقة له.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O09' and q.type = 'mcq' and q.number = 3) and explanation = 'يمنح HCO₃⁻ أيون H⁺ فيتحول إلى CO₃²⁻، وهي القاعدة المرافقة له كما في الجدول 2-1.';
update public.question_answers set explanation = 'يستقبل CO₃²⁻ أيون H⁺ فينتج HCO₃⁻ وهو الحمض المرافق له.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O10' and q.type = 'mcq' and q.number = 3) and explanation = 'يستقبل CO₃²⁻ أيون H⁺ فينتج HCO₃⁻ وهو الحمض المرافق له كما في الجدول 2-1.';
update public.question_answers set explanation = 'لـ PCl₃ زوج إلكترونات حر على الفوسفور يستطيع منحه ولا مدار فارغ لديه ليستقبل، فهو قاعدة لويس.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O12' and q.type = 'mcq' and q.number = 7) and explanation = 'لـ PCl₃ زوج إلكترونات حر على الفوسفور يستطيع منحه ولا مدار فارغ لديه ليستقبل، فهو قاعدة لويس (وهو سؤال التقويم 10 في الكتاب).';
update public.question_answers set explanation = 'الماء والمواد الأخرى التي تستطيع أن تسلك سلوك الأحماض والقواعد تسمى مواد مترددة (أمفوتيرية) Amphoteric؛ فهي تسلك سلوك الحمض أو القاعدة بحسب المادة التي تتفاعل معها.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O13' and q.type = 'mcq' and q.number = 1) and explanation = 'يسمي الكتاب الماء والمواد الأخرى التي تستطيع أن تسلك سلوك الأحماض والقواعد مواد مترددة (أمفوتيرية) Amphoteric؛ فهي تسلك سلوك الحمض أو القاعدة بحسب المادة التي تتفاعل معها.';
update public.question_answers set explanation = 'الماء يسلك سلوك الحمض أو القاعدة بحسب طبيعة المواد المذابة في المحلول؛ فيكون قاعدة مع HF وحمضًا مع NH₃.', distractor_notes = '["","سلوك الماء لا يرتبط بدرجة الحرارة، بل بطبيعة المادة المذابة التي يتفاعل معها.","زيادة كمية الماء أو نقصها لا تغير دوره؛ فدوره يتحدد بالمادة التي يمنحها البروتون أو يستقبله منها.","الماء النقي والمحاليل كلاهما يسلك فيه الماء سلوكًا يتحدد بالمادة المذابة، لا بدرجة نقائه."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O13' and q.type = 'mcq' and q.number = 6) and explanation = 'يبين الكتاب أن الماء يسلك سلوك الحمض أو القاعدة بحسب طبيعة المواد المذابة في المحلول؛ فيكون قاعدة مع HF وحمضًا مع NH₃.';
update public.question_answers set explanation = 'الحمض الذي يستطيع أن يمنح أيون هيدروجين واحدًا فقط لكل جزيء هو حمض أحادي البروتون، مثل HCl وHF وCH₃COOH.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O14' and q.type = 'mcq' and q.number = 1) and explanation = 'يعرّف الكتاب الحمض الذي يستطيع أن يمنح أيون هيدروجين واحدًا فقط لكل جزيء بأنه حمض أحادي البروتون، مثل HCl وHF وCH₃COOH.';
update public.question_answers set explanation = 'لأن حمض الإيثانويك أحادي البروتون تُكتب صيغته غالبًا في صورة CH₃COOH لتأكيد حقيقة أن ذرة هيدروجين واحدة فقط من الذرات الأربع قابلة للتأين.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O14' and q.type = 'mcq' and q.number = 3) and explanation = 'يذكر الكتاب أنه لأن حمض الإيثانويك أحادي البروتون تُكتب صيغته غالبًا في صورة CH₃COOH لتأكيد حقيقة أن ذرة هيدروجين واحدة فقط من الذرات الأربع قابلة للتأين.';
update public.question_answers set explanation = 'حمض النيتريك HNO₃ يمنح أيون هيدروجين واحدًا فقط لكل جزيء، وهو من الأحماض الأحادية البروتون.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O15' and q.type = 'mcq' and q.number = 1) and explanation = 'حمض النيتريك HNO₃ يمنح أيون هيدروجين واحدًا فقط لكل جزيء، وهو من أمثلة الكتاب على الأحماض الأحادية البروتون.';
update public.question_answers set explanation = 'صيغة حمض البيركلوريك HClO₄، وهو حمض أحادي البروتون.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O15' and q.type = 'mcq' and q.number = 3) and explanation = 'صيغة حمض البيركلوريك كما في الكتاب HClO₄، وهو حمض أحادي البروتون.';
update public.question_answers set model_answer = 'من الأمثلة: حمض الهيدروكلوريك HCl، فلوريد الهيدروجين (حمض الهيدروفلوريك) HF، حمض البيركلوريك HClO₄، حمض النيتريك HNO₃، حمض الهيدروبروميك HBr، حمض الإيثانويك CH₃COOH (يكفي أربعة).' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O15' and q.type = 'essay' and q.number = 1) and model_answer = 'من أمثلة الكتاب: حمض الهيدروكلوريك HCl، فلوريد الهيدروجين (حمض الهيدروفلوريك) HF، حمض البيركلوريك HClO₄، حمض النيتريك HNO₃، حمض الهيدروبروميك HBr، حمض الإيثانويك CH₃COOH (يكفي أربعة).';
update public.question_answers set explanation = 'حمض الفوسفوريك H₃PO₄ يحتوي على ثلاث ذرات هيدروجين قابلة للتأين في كل جزيء، فيسمى حمضًا ثلاثي البروتونات.', distractor_notes = '["الحمض الأحادي يمنح أيون هيدروجين واحدًا، وحمض الفوسفوريك فيه ثلاث ذرات قابلة للتأين.","الحمض الثنائي فيه ذرتا هيدروجين قابلتان للتأين، وحمض الفوسفوريك فيه ثلاث.","","وجود الفوسفور لا يمنع الحمضية؛ فذرات الهيدروجين فيه قابلة للتأين وهو يُصنَّف حمضًا."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O16' and q.type = 'mcq' and q.number = 3) and explanation = 'يذكر الكتاب أن حمض الفوسفوريك H₃PO₄ يحتوي على ثلاث ذرات هيدروجين قابلة للتأين في كل جزيء، فيسمى حمضًا ثلاثي البروتونات.';
update public.question_answers set explanation = 'يمكن استعمال مصطلح حمض متعدد البروتونات لأي حمض يحتوي على أكثر من ذرة هيدروجين قابلة للتأين، فيشمل الثنائية والثلاثية البروتونات.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O16' and q.type = 'mcq' and q.number = 6) and explanation = 'يذكر الكتاب أنه يمكن استعمال مصطلح حمض متعدد البروتونات لأي حمض يحتوي على أكثر من ذرة هيدروجين قابلة للتأين، فيشمل الثنائية والثلاثية البروتونات.';
update public.question_answers set explanation = 'الأنهيدريد الحمضي حمض منزوع منه جزيء ماء، وهو أكسيد يستطيع أن يتحد مع الماء ليكوّن حمضًا، مثل CO₂ الذي يكوّن H₂CO₃.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O17' and q.type = 'mcq' and q.number = 1) and explanation = 'يصف الكتاب الأنهيدريد الحمضي بأنه حمض منزوع منه جزيء ماء، وهو أكسيد يستطيع أن يتحد مع الماء ليكوّن حمضًا، مثل CO₂ الذي يكوّن H₂CO₃.';
update public.question_answers set explanation = 'ثاني أكسيد الكربون CO₂ أكسيد لافلز يتحد مع الماء مكوّنًا حمض الكربونيك H₂CO₃، فهو أنهيدريد حمضي.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O17' and q.type = 'mcq' and q.number = 2) and explanation = 'ثاني أكسيد الكربون CO₂ أكسيد لافلز يتحد مع الماء مكوّنًا حمض الكربونيك H₂CO₃، فهو أنهيدريد حمضي كما يذكر الكتاب.';
update public.question_answers set explanation = 'إذا تُرك لينتشر في الغلاف الجوي اتحد مع الماء الموجود في الهواء مكوّنًا حمض الكبريتيك الذي يسقط في صورة مطر حمضي؛ فهو أكسيد لافلز يعمل أنهيدريدًا حمضيًا.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O17' and q.type = 'mcq' and q.number = 5) and explanation = 'يذكر الكتاب أن SO₃ إذا تُرك لينتشر في الغلاف الجوي اتحد مع الماء الموجود في الهواء مكوّنًا حمض الكبريتيك الذي يسقط في صورة مطر حمضي؛ فهو أكسيد لافلز يعمل أنهيدريدًا حمضيًا.';
update public.question_answers set distractor_notes = '["CO₂ أكسيد لافلز فهو أنهيدريد حمضي، والذي يذيب الصخور الجيرية حمض لا قاعدة.","","تكوّن الكهوف مرتبط بماء المطر الحمضي الناتج من CO₂، والإذابة بطيئة عبر آلاف السنين.","CaO أكسيد فلزي يكوّن مع الماء قاعدة Ca(OH)₂ لا حمضًا."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O17' and q.type = 'mcq' and q.number = 6) and distractor_notes is not distinct from '["CO₂ أكسيد لافلز فهو أنهيدريد حمضي، والذي يذيب الصخور الجيرية حمض لا قاعدة.","","يربط الكتاب تكوّن الكهوف بماء المطر الحمضي الناتج من CO₂، والإذابة بطيئة عبر آلاف السنين.","CaO أكسيد فلزي يكوّن مع الماء قاعدة Ca(OH)₂ لا حمضًا."]'::jsonb;
update public.question_answers set explanation = 'بنزع جزيء ماء من H₂SO₄ نحصل على: H₂SO₄ − H₂O = SO₃، وهذا يتفق مع أن SO₃ يتحد مع الماء مكوّنًا حمض الكبريتيك.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O17' and q.type = 'mcq' and q.number = 7) and explanation = 'بنزع جزيء ماء من H₂SO₄ نحصل على: H₂SO₄ − H₂O = SO₃، وهذا يتفق مع الكتاب الذي يذكر أن SO₃ يتحد مع الماء مكوّنًا حمض الكبريتيك.';
update public.question_answers set explanation = 'أكسيد الكالسيوم CaO يكوّن عندما يذوب في الماء القاعدة هيدروكسيد الكالسيوم: CaO + H₂O → Ca(OH)₂.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O18' and q.type = 'mcq' and q.number = 1) and explanation = 'يذكر الكتاب أن أكسيد الكالسيوم CaO يكوّن عندما يذوب في الماء القاعدة هيدروكسيد الكالسيوم: CaO + H₂O → Ca(OH)₂.';
update public.question_answers set explanation = 'يسمى أكسيد الكالسيوم CaO الجير الحي، وناتج ذوبانه في الماء Ca(OH)₂ الجير المطفأ.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O18' and q.type = 'mcq' and q.number = 2) and explanation = 'يسمي الكتاب أكسيد الكالسيوم CaO الجير الحي، وناتج ذوبانه في الماء Ca(OH)₂ الجير المطفأ.';
update public.question_answers set explanation = 'ملح إبسوم بلورات من ملح كبريتات الماغنسيوم صيغتها MgSO₄·7H₂O.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O19' and q.type = 'mcq' and q.number = 1) and explanation = 'ملح إبسوم بلورات من ملح كبريتات الماغنسيوم صيغتها كما في الكتاب MgSO₄·7H₂O.';
update public.question_answers set explanation = 'تفاعل SO₃ مع MgO ينتج بلورات من ملح كبريتات الماغنسيوم تُعرف بملح إبسوم MgSO₄·7H₂O، أي كبريتات ماغنسيوم مرتبطة بسبعة جزيئات ماء.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O19' and q.type = 'mcq' and q.number = 2) and explanation = 'يذكر الكتاب أن تفاعل SO₃ مع MgO ينتج بلورات من ملح كبريتات الماغنسيوم تُعرف بملح إبسوم MgSO₄·7H₂O، أي كبريتات ماغنسيوم مرتبطة بسبعة جزيئات ماء.';
update public.question_answers set distractor_notes = '["هذا ليس من استعمالات ملح إبسوم.","تسليك المصارف استعمال لهيدروكسيد الصوديوم NaOH، لا لملح إبسوم.","","تنظيف السيراميك استعمال لحمض الهيدروكلوريك HCl."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O19' and q.type = 'mcq' and q.number = 3) and distractor_notes is not distinct from '["لم يذكر الكتاب هذا الاستعمال لملح إبسوم.","تسليك المصارف استعمال لهيدروكسيد الصوديوم NaOH كما في الكتاب، لا لملح إبسوم.","","تنظيف السيراميك استعمال لحمض الهيدروكلوريك HCl كما في الكتاب."]'::jsonb;
update public.question_answers set explanation = 'التفاعل SO₃(g) + MgO(s) → MgSO₄(s) ينتج بلورات من ملح كبريتات الماغنسيوم تُعرف باسم ملح إبسوم.', distractor_notes = '["","CO₂ مع MgO يكوّن كربونات لا كبريتات، والتفاعل المقصود هو مع SO₃.","تفاعل SO₃ مع CaO ينتج كبريتات الكالسيوم لا كبريتات الماغنسيوم.","هذا التفاعل ينتج كبريتات الكالسيوم وغاز الهيدروجين، لا ملح إبسوم."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O19' and q.type = 'mcq' and q.number = 6) and explanation = 'يذكر الكتاب التفاعل SO₃(g) + MgO(s) → MgSO₄(s)، وأنه ينتج بلورات من ملح كبريتات الماغنسيوم تُعرف باسم ملح إبسوم.';
update public.question_answers set explanation = 'حمض لويس في هذا التفاعل هو جزيء SO₃، إذ يستقبل زوج إلكترونات من قاعدة لويس (أيون الأكسيد O²⁻).', distractor_notes = '["أيون O²⁻ يعطي زوج الإلكترونات فهو قاعدة لويس لا حمضها.","Mg²⁺ ليس طرفًا في زوج الحمض والقاعدة؛ فالزوج هو SO₃ وO²⁻.","MgSO₄ ناتج التفاعل لا أحد المتفاعلين.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O20' and q.type = 'mcq' and q.number = 1) and explanation = 'يذكر الكتاب أن حمض لويس في هذا التفاعل هو جزيء SO₃، إذ يستقبل زوج إلكترونات من قاعدة لويس (أيون الأكسيد O²⁻).';
update public.question_answers set explanation = 'يرتبط SO₃ بأيون O²⁻ الذي يعطيه زوج إلكترونات، فيتكوّن أيون الكبريتات SO₄²⁻.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O20' and q.type = 'mcq' and q.number = 4) and explanation = 'يرتبط SO₃ بأيون O²⁻ الذي يعطيه زوج إلكترونات، فيتكوّن أيون الكبريتات SO₄²⁻، كما في تراكيب لويس في الكتاب.';
update public.question_answers set distractor_notes = '["التفاعل المقصود مع SO₃ لا مع CO₂.","الهدف منع تكوّن حمض الكبريتيك في الجو، والناتج ملح MgSO₄.","بخار الماء من أبراج التبريد لا علاقة له بتفاعل MgO مع SO₃.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O20' and q.type = 'mcq' and q.number = 6) and distractor_notes is not distinct from '["التفاعل المقصود في الكتاب مع SO₃ لا مع CO₂.","الهدف منع تكوّن حمض الكبريتيك في الجو، والناتج ملح MgSO₄.","بخار الماء من أبراج التبريد لا علاقة له بتفاعل MgO مع SO₃.",""]'::jsonb;
update public.question_answers set explanation = 'المحلول الحمضي يحتوي على أيونات هيدروجين أكثر من أيونات الهيدروكسيد، أي [H⁺] > [OH⁻].' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O21' and q.type = 'mcq' and q.number = 1) and explanation = 'يذكر الكتاب أن المحلول الحمضي يحتوي على أيونات هيدروجين أكثر من أيونات الهيدروكسيد، أي [H⁺] > [OH⁻].';
update public.question_answers set model_answer = 'التأين الذاتي: H₂O(l) + H₂O(l) ⇌ H₃O⁺(aq) + OH⁻(aq) (أو H₂O ⇌ H⁺ + OH⁻)، وينتج أعدادًا متساوية من H⁺ وOH⁻، فيتساوى التركيزان ويكون الماء النقي متعادلًا. عند إذابة HCl يتأين: HCl → H⁺ + Cl⁻، فيزداد [H⁺]، ويقل [OH⁻] لأن التركيزين يتغيران في اتجاهين متعاكسين، فيصبح [H⁺] > [OH⁻] ويصير المحلول حمضيًا.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O21' and q.type = 'essay' and q.number = 3) and model_answer = 'التأين الذاتي: H₂O(l) + H₂O(l) ⇌ H₃O⁺(aq) + OH⁻(aq) (أو H₂O ⇌ H⁺ + OH⁻)، وينتج أعدادًا متساوية من H⁺ وOH⁻، فيتساوى التركيزان ويكون الماء النقي متعادلًا. عند إذابة HCl يتأين: HCl → H⁺ + Cl⁻، فيزداد [H⁺]، ويقل [OH⁻] لأن التركيزين يتغيران في اتجاهين متعاكسين (الشكل 2-3)، فيصبح [H⁺] > [OH⁻] ويصير المحلول حمضيًا.';
update public.question_answers set explanation = 'ذرة الهيدروجين القابلة للتأين في حمض الإيثانويك مرتبطة بذرة الأكسجين الأعلى كهروسالبية من الهيدروجين، فتكون الرابطة O–H قطبية.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O22' and q.type = 'mcq' and q.number = 1) and explanation = 'يذكر الكتاب أن ذرة الهيدروجين القابلة للتأين في حمض الإيثانويك مرتبطة بذرة الأكسجين الأعلى كهروسالبية من الهيدروجين، فتكون الرابطة O–H قطبية.';
update public.question_answers set explanation = 'كل ذرة هيدروجين في البنزين مرتبطة بذرة كربون كهروسالبيتها تساوي تقريبًا كهروسالبية الهيدروجين، فالروابط غير قطبية ولا تتأين ذرات الهيدروجين، فالبنزين ليس حمضًا.', distractor_notes = '["الفرق قليل لا كبير، ولو كانت الروابط قطبية لأمكن أن يتأين الهيدروجين.","","عدم حمضية البنزين لا تُعلَّل بالذوبان، بل بعدم قطبية الروابط C–H.","كثرة ذرات الهيدروجين لا تمنع التأين؛ المعيار قطبية الرابطة."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O22' and q.type = 'mcq' and q.number = 3) and explanation = 'يذكر الكتاب أن كل ذرة هيدروجين في البنزين مرتبطة بذرة كربون كهروسالبيتها تساوي تقريبًا كهروسالبية الهيدروجين، فالروابط غير قطبية ولا تتأين ذرات الهيدروجين، فالبنزين ليس حمضًا.';
update public.question_answers set distractor_notes = '["الهيدروجين المرتبط بالكربون لا يتأين لأن الرابطة غير قطبية، كما في البنزين.","CH₃COOH فيه أربع ذرات هيدروجين ويتأين منها واحدة، فالانفراد ليس شرطًا.","يرتبط التأين بالرابطة القطبية مع ذرة عالية الكهروسالبية مثل O وF، لا بالفلزات.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O22' and q.type = 'mcq' and q.number = 4) and distractor_notes is not distinct from '["الهيدروجين المرتبط بالكربون لا يتأين لأن الرابطة غير قطبية، كما في البنزين.","CH₃COOH فيه أربع ذرات هيدروجين ويتأين منها واحدة، فالانفراد ليس شرطًا.","يربط الكتاب التأين بالرابطة القطبية مع ذرة عالية الكهروسالبية مثل O وF، لا بالفلزات.",""]'::jsonb;
update public.question_answers set explanation = 'الأكسجين أكثر كهروسالبية من الهيدروجين فيجذب إلكترونات الرابطة نحوه ويحمل δ⁻، وتحمل ذرة الهيدروجين δ⁺، وهذا ما يجعلها قابلة للتأين.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O22' and q.type = 'mcq' and q.number = 5) and explanation = 'الأكسجين أكثر كهروسالبية من الهيدروجين فيجذب إلكترونات الرابطة نحوه ويحمل δ⁻، وتحمل ذرة الهيدروجين δ⁺، كما في الشكل 2-9، وهذا ما يجعلها قابلة للتأين.';
update public.question_answers set explanation = 'كلٌّ من H₂SO₄ وH₂CO₃ يستطيع أن يمنح أيوني هيدروجين؛ لأن كليهما يحتوي على ذرتي هيدروجين مرتبطتين مع ذرتي أكسجين بروابط قطبية.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O22' and q.type = 'mcq' and q.number = 6) and explanation = 'يذكر الكتاب أن كلًّا من H₂SO₄ وH₂CO₃ يستطيع أن يمنح أيوني هيدروجين؛ لأن كليهما يحتوي على ذرتي هيدروجين مرتبطتين مع ذرتي أكسجين بروابط قطبية.';
update public.question_answers set explanation = 'معظم الأحماض والقواعد وفق أرهينيوس تتفق مع تعريف برونستد – لوري، وأن نظرية لويس أشمل لأنها تضم تفاعلات لا ينتقل فيها H⁺ مثل SO₃ مع MgO وBF₃ مع NH₃.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L1-O23' and q.type = 'mcq' and q.number = 5) and explanation = 'يبين الكتاب أن معظم الأحماض والقواعد وفق أرهينيوس تتفق مع تعريف برونستد – لوري، وأن نظرية لويس أشمل لأنها تضم تفاعلات لا ينتقل فيها H⁺ مثل SO₃ مع MgO وBF₃ مع NH₃.';
update public.question_answers set explanation = 'حمض النيتريك HNO₃ من الأحماض القوية؛ إذ يتأين كليًا: HNO₃ → H⁺ + NO₃⁻، أما HF وH₂CO₃ وHClO فأحماض ضعيفة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L2-O01' and q.type = 'mcq' and q.number = 4) and explanation = 'حمض النيتريك HNO₃ من الأحماض القوية في الجدول 2-3؛ إذ يتأين كليًا: HNO₃ → H⁺ + NO₃⁻، أما HF وH₂CO₃ وHClO فأحماض ضعيفة.';
update public.question_answers set explanation = 'الأحماض HF وH₂S وCH₃COOH جميعها من الأحماض الضعيفة، وتُكتب معادلات تأينها بسهمي اتزان لأنها تتأين جزئيًا.', distractor_notes = '["","HCl حمض قوي يتأين كليًا، فلا تتكون المجموعة من أحماض ضعيفة فقط.","هذه الأحماض الثلاثة قوية كلها.","H₂SO₄ حمض قوي في تأينه الأول، وإن كان الحمضان الآخران ضعيفين."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L2-O01' and q.type = 'mcq' and q.number = 5) and explanation = 'الأحماض HF وH₂S وCH₃COOH جميعها من الأحماض الضعيفة في الجدول 2-3، وتُكتب معادلات تأينها بسهمي اتزان لأنها تتأين جزئيًا.';
update public.question_answers set explanation = 'الأمونيا قاعدة ضعيفة تستقبل أيون H⁺ من الماء فتكوّن NH₄⁺ وOH⁻، ولأنها تتأين جزئيًا يتكون مخلوط اتزان، فتُكتب المعادلة بسهمي اتزان.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L2-O03' and q.type = 'mcq' and q.number = 1) and explanation = 'الأمونيا قاعدة ضعيفة تستقبل أيون H⁺ من الماء فتكوّن NH₄⁺ وOH⁻، ولأنها تتأين جزئيًا يتكون مخلوط اتزان، فتُكتب المعادلة بسهمي اتزان كما في الجدول 2-6.';
update public.question_answers set explanation = 'Ka = [H₃O⁺][CH₃COO⁻] / [CH₃COOH] = (1.3 × 10⁻³)(1.3 × 10⁻³) / 0.099 = 1.69 × 10⁻⁶ / 0.099 = 1.7 × 10⁻⁵ (بمنزلتين معنويتين)، وهي قريبة من القيمة المرجعية لـ Ka.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L2-O04' and q.type = 'mcq' and q.number = 7) and explanation = 'Ka = [H₃O⁺][CH₃COO⁻] / [CH₃COOH] = (1.3 × 10⁻³)(1.3 × 10⁻³) / 0.099 = 1.69 × 10⁻⁶ / 0.099 = 1.7 × 10⁻⁵ (بمنزلتين معنويتين)، وهي قريبة من القيمة في الجدول 2-4.';
update public.question_answers set distractor_notes = '["KOH قاعدة قوية تتحلل كليًا.","Ba(OH)₂ قاعدة قوية تتحلل كليًا.","","CsOH قاعدة قوية تتحلل كليًا منتجة Cs⁺ وOH⁻."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L2-O06' and q.type = 'mcq' and q.number = 2) and distractor_notes is not distinct from '["KOH قاعدة قوية تتحلل كليًا (الجدول 2-5).","Ba(OH)₂ قاعدة قوية في الجدول 2-5 تتحلل كليًا.","","CsOH قاعدة قوية تتحلل كليًا منتجة Cs⁺ وOH⁻."]'::jsonb;
update public.question_answers set explanation = 'RbOH وCa(OH)₂ كلاهما من القواعد القوية، فيتحلل ما يذوب منهما كليًا إلى أيونات فلزية وأيونات OH⁻.', distractor_notes = '["","NH₃ قاعدة ضعيفة تتأين جزئيًا (Kb = 2.5 × 10⁻⁵).","الإيثيل أمين C₂H₅NH₂ قاعدة ضعيفة.","الأنيلين والميثيل أمين كلاهما قاعدتان ضعيفتان."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L2-O06' and q.type = 'mcq' and q.number = 3) and explanation = 'RbOH وCa(OH)₂ كلاهما في الجدول 2-5 لمعادلات تأين القواعد القوية، فيتحلل ما يذوب منهما كليًا إلى أيونات فلزية وأيونات OH⁻.';
update public.question_answers set explanation = 'هيدروكسيد البوتاسيوم قاعدة قوية تتحلل كليًا إلى أيونات البوتاسيوم وأيونات الهيدروكسيد، فتُكتب المعادلة بسهم واحد.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L2-O06' and q.type = 'mcq' and q.number = 5) and explanation = 'هيدروكسيد البوتاسيوم قاعدة قوية تتحلل كليًا إلى أيونات البوتاسيوم وأيونات الهيدروكسيد، فتُكتب المعادلة بسهم واحد كما في الجدول 2-5.';
update public.question_answers set explanation = 'ثابت حاصل الذائبية لـ Ca(OH)₂ صغير، مما يدل على أن كمية قليلة من OH⁻ توجد في المحلول المشبع؛ ولذلك يُعد مصدرًا ضعيفًا لأيونات OH⁻.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L2-O07' and q.type = 'mcq' and q.number = 2) and explanation = 'يذكر الكتاب أن ثابت حاصل الذائبية لـ Ca(OH)₂ صغير، مما يدل على أن كمية قليلة من OH⁻ توجد في المحلول المشبع؛ ولذلك يُعد مصدرًا ضعيفًا لأيونات OH⁻.';
update public.question_answers set distractor_notes = '["","قوة القاعدة تحدَّد بدرجة تأين ما يذوب منها، لا بكمية OH⁻ التي تتأثر بالذائبية.","صغر Ksp يدل على قلة الذوبان، وكل ما يذوب من Ca(OH)₂ يتأين كليًا.","الحكم صحيح لكن السبب خاطئ؛ فكمية OH⁻ في المحلول المشبع قليلة."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L2-O07' and q.type = 'mcq' and q.number = 5) and distractor_notes is not distinct from '["","قوة القاعدة تحدَّد بدرجة تأين ما يذوب منها، لا بكمية OH⁻ التي تتأثر بالذائبية.","صغر Ksp يدل على قلة الذوبان، وكل ما يذوب من Ca(OH)₂ يتأين كليًا.","الحكم صحيح لكن السبب خاطئ؛ فالكتاب يذكر أن كمية OH⁻ في المحلول المشبع قليلة."]'::jsonb;
update public.question_answers set distractor_notes = '["","العلاقة معكوسة؛ فكلما صغرت Kb كانت القاعدة أضعف.","Kb تُستعمل للقواعد الضعيفة التي تتأين جزئيًا، أما التحلل الكلي فصفة القواعد القوية.","Kb ثابت اتزان يعبر عن مدى التأين، لا عن تركيز القاعدة المذابة."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L2-O08' and q.type = 'mcq' and q.number = 1) and distractor_notes is not distinct from '["","العلاقة معكوسة؛ فالكتاب ينص على أنه كلما صغرت Kb كانت القاعدة أضعف.","Kb تُستعمل للقواعد الضعيفة التي تتأين جزئيًا، أما التحلل الكلي فصفة القواعد القوية.","Kb ثابت اتزان يعبر عن مدى التأين، لا عن تركيز القاعدة المذابة."]'::jsonb;
update public.question_answers set explanation = 'القيمة 4.3 × 10⁻¹⁰ صغيرة جدًا، فالأنيلين يتأين بدرجة ضئيلة جدًا وينتج تركيزًا قليلًا جدًا من OH⁻، وتبقى معظم جزيئاته غير متأينة؛ فهو قاعدة ضعيفة جدًا.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L2-O08' and q.type = 'mcq' and q.number = 4) and explanation = 'القيمة 4.3 × 10⁻¹⁰ صغيرة جدًا، فالأنيلين يتأين بدرجة ضئيلة جدًا وينتج تركيزًا قليلًا جدًا من OH⁻، وتبقى معظم جزيئاته غير متأينة؛ فهو أضعف قواعد الجدول 2-6.';
update public.question_answers set distractor_notes = '["7.00 هي قيمة كل من pH و pOH في المحلول المتعادل فقط، وليست مجموعهما.","هذه قيمة Kw وهي حاصل ضرب التركيزين لا مجموع الرقمين.","لا تدعم أي علاقة هذا العدد؛ المجموع ثابت يساوي 14.00.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L3-O07' and q.type = 'mcq' and q.number = 3) and distractor_notes is not distinct from '["7.00 هي قيمة كل من pH و pOH في المحلول المتعادل فقط، وليست مجموعهما.","هذه قيمة Kw وهي حاصل ضرب التركيزين لا مجموع الرقمين.","لا تدعم أي علاقة في الكتاب هذا العدد؛ المجموع ثابت يساوي 14.00.",""]'::jsonb;
update public.question_answers set distractor_notes = '["[H⁺] هو تركيز الجزء المتأين لا الباقي غير المتأين.","إضافة [H⁺] خطأ؛ فالتأين يستهلك جزءًا من الحمض لا يزيده.","","هذا تقريب لا يُعتمد هنا؛ إذ يُطرح [H⁺] من التركيز الابتدائي."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L3-O09' and q.type = 'mcq' and q.number = 2) and distractor_notes is not distinct from '["[H⁺] هو تركيز الجزء المتأين لا الباقي غير المتأين.","إضافة [H⁺] خطأ؛ فالتأين يستهلك جزءًا من الحمض لا يزيده.","","هذا تقريب لا يُعتمد في حل الكتاب؛ إذ يطرح [H⁺] من التركيز الابتدائي."]'::jsonb;
update public.question_answers set distractor_notes = '["الأقطاب والشاشة من مكونات مقياس pH الرقمي لا ورق الكاشف.","لا يُقاس تيار في ورق الكاشف؛ المعتمد هو تغيّر اللون.","لا يُعتمد عدّ القطرات؛ الطريقة مقارنة اللون بمقياس معياري.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L3-O10' and q.type = 'mcq' and q.number = 1) and distractor_notes is not distinct from '["الأقطاب والشاشة من مكونات مقياس pH الرقمي لا ورق الكاشف.","لا يُقاس تيار في ورق الكاشف؛ المعتمد هو تغيّر اللون.","الكتاب لا يعتمد عدّ القطرات؛ الطريقة مقارنة اللون بمقياس معياري.",""]'::jsonb;
update public.question_answers set distractor_notes = '["الورق معالج بكواشف يتغير لونها بتغير تركيز H⁺؛ فهو يتأثر به.","الكاشف يتغير لونه بتغير تركيز H⁺ ولا يقيس OH⁻ وحده.","قيم pH للمحاليل في التدريج المعتمد من 0 إلى 14، وليست سالبة.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L3-O10' and q.type = 'mcq' and q.number = 4) and distractor_notes is not distinct from '["الورق معالج بكواشف يتغير لونها بتغير تركيز H⁺؛ فهو يتأثر به.","الكاشف يتغير لونه بتغير تركيز H⁺ ولا يقيس OH⁻ وحده.","قيم pH للمحاليل في تدريج الكتاب من 0 إلى 14، وليست سالبة.",""]'::jsonb;
update public.question_answers set explanation = 'تفاعل التعادل هو تفاعل محلول حمض مع محلول قاعدة ينتج ملحًا وماءً. فالبديل الصحيح «تفاعل محلول حمض مع محلول قاعدة ينتج ملحًا وماءً».' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O01' and q.type = 'mcq' and q.number = 1) and explanation = 'تفاعل التعادل كما عرّفه الكتاب: تفاعل محلول حمض مع محلول قاعدة ينتج ملحًا وماءً. فالبديل الصحيح «تفاعل محلول حمض مع محلول قاعدة ينتج ملحًا وماءً».';
update public.question_answers set explanation = 'كواشف الأحماض والقواعد هي الأصباغ الكيميائية التي تتأثر ألوانها بالمحاليل الحمضية والقاعدية، ويستعملها الكيميائيون بدلًا من مقياس pH لتحري نقطة التكافؤ.', distractor_notes = '["هذا وصف المحلول القياسي، لا الكاشف.","هذا وصف مقياس pH، والكواشف تُستعمل بديلًا منه.","","هذا وصف الأملاح التي يحدث لها تميّه، لا الكواشف."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O02' and q.type = 'mcq' and q.number = 1) and explanation = 'عرّف الكتاب كواشف الأحماض والقواعد بأنها الأصباغ الكيميائية التي تتأثر ألوانها بالمحاليل الحمضية والقاعدية، ويستعملها الكيميائيون بدلًا من مقياس pH لتحري نقطة التكافؤ.';
update public.question_answers set explanation = 'تسمى النقطة التي يتغير لون الكاشف عندها نقطة النهاية للمعايرة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O02' and q.type = 'mcq' and q.number = 2) and explanation = 'حسب الكتاب: تسمى النقطة التي يتغير لون الكاشف عندها نقطة النهاية للمعايرة.';
update public.question_answers set explanation = 'نقطة التكافؤ هي النقطة التي يتساوى عندها عدد مولات H⁺ من الحمض مع عدد مولات OH⁻ من القاعدة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O02' and q.type = 'mcq' and q.number = 3) and explanation = 'نقطة التكافؤ كما في الكتاب: النقطة التي يتساوى عندها عدد مولات H⁺ من الحمض مع عدد مولات OH⁻ من القاعدة.';
update public.question_answers set distractor_notes = '["الكاشف المناسب لمعايرة حمض ضعيف بقاعدة قوية هو الفينولفثالين، لأن نقطة التكافؤ فيها بين 8 و9.","","الكواشف تستعمل لتحري نقطة التكافؤ في المعايرة، لا لقياس سعة المحلول المنظم.","لا يصلح كاشف واحد لكل المعايرات؛ لأن نقطة التكافؤ لا تكون دائمًا عند pH = 7."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O02' and q.type = 'mcq' and q.number = 4) and distractor_notes is not distinct from '["الكاشف الذي ذكره الكتاب لمعايرة حمض ضعيف بقاعدة قوية هو الفينولفثالين، لأن نقطة التكافؤ فيها بين 8 و9.","","الكواشف تستعمل لتحري نقطة التكافؤ في المعايرة، لا لقياس سعة المحلول المنظم.","لا يصلح كاشف واحد لكل المعايرات؛ لأن نقطة التكافؤ لا تكون دائمًا عند pH = 7."]'::jsonb;
update public.question_answers set distractor_notes = '["البروموثيمول الأزرق يناسب معايرة حمض قوي بقاعدة قوية، ونقطة التكافؤ هنا بين pH 8 و9.","الميثيل البرتقالي يتغير لونه في وسط حمضي بعيد عن نقطة تكافؤ هذه المعايرة (بين 8 و9).","الكريستال البنفسجي يتغير لونه عند قيم pH منخفضة جدًا (قرب 0 إلى 2) بعيدًا عن نقطة التكافؤ.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O02' and q.type = 'mcq' and q.number = 5) and distractor_notes is not distinct from '["البروموثيمول الأزرق ذكره الكتاب لمعايرة حمض قوي بقاعدة قوية، ونقطة التكافؤ هنا بين pH 8 و9.","الميثيل البرتقالي يتغير لونه في وسط حمضي بعيد عن نقطة تكافؤ هذه المعايرة (بين 8 و9).","الكريستال البنفسجي يتغير لونه عند قيم pH منخفضة جدًا (قرب 0 إلى 2) بعيدًا عن نقطة التكافؤ.",""]'::jsonb;
update public.question_answers set explanation = 'دور الكاشف أن يبيّن بدقة -عن طريق تغير لونه- أنه قد تمت إضافة كمية كافية من المحلول القياسي لتعادل المحلول المجهول؛ لذا يجب أن يتغير لونه عند نقطة التكافؤ.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O02' and q.type = 'mcq' and q.number = 7) and explanation = 'ذكر الكتاب أن دور الكاشف أن يبيّن بدقة -عن طريق تغير لونه- أنه قد تمت إضافة كمية كافية من المحلول القياسي لتعادل المحلول المجهول؛ لذا يجب أن يتغير لونه عند نقطة التكافؤ.';
update public.question_answers set explanation = 'تميّه الأملاح عملية تتفاعل فيها الأملاح مع الماء؛ حيث تستقبل الأيونات السالبة من الملح المتأين أيونات الهيدروجين من الماء، أو تمنح الأيونات الموجبة من الملح المتفكك أيونات الهيدروجين للماء.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O04' and q.type = 'mcq' and q.number = 1) and explanation = 'عرّف الكتاب تميّه الأملاح بأنه عملية تتفاعل فيها الأملاح مع الماء؛ حيث تستقبل الأيونات السالبة من الملح المتأين أيونات الهيدروجين من الماء، أو تمنح الأيونات الموجبة من الملح المتفكك أيونات الهيدروجين للماء.';
update public.question_answers set explanation = 'NH₄⁺(aq) + H₂O(l) ⇌ NH₃(aq) + H₃O⁺(aq)؛ أي أن الأيون الموجب يمنح أيون هيدروجين للماء.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O04' and q.type = 'mcq' and q.number = 3) and explanation = 'حسب الكتاب: NH₄⁺(aq) + H₂O(l) ⇌ NH₃(aq) + H₃O⁺(aq)؛ أي أن الأيون الموجب يمنح أيون هيدروجين للماء.';
update public.question_answers set explanation = 'أيونات K⁺ لا تتفاعل مع الماء بسبب تعادلها مع أيونات OH⁻ وتكوين محلول قاعدي قوي من KOH؛ أي أن K⁺ مصدره قاعدة قوية فلا يحدث له تميّه، بينما يتميّه F⁻.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O04' and q.type = 'mcq' and q.number = 7) and explanation = 'ذكر الكتاب أن أيونات K⁺ لا تتفاعل مع الماء بسبب تعادلها مع أيونات OH⁻ وتكوين محلول قاعدي قوي من KOH؛ أي أن K⁺ مصدره قاعدة قوية فلا يحدث له تميّه، بينما يتميّه F⁻.';
update public.question_answers set explanation = 'المحاليل المنظمة محاليل تقاوم التغيرات في قيم pH عند إضافة كميات محددة من الأحماض أو القواعد.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O06' and q.type = 'mcq' and q.number = 1) and explanation = 'عرّف الكتاب المحاليل المنظمة بأنها محاليل تقاوم التغيرات في قيم pH عند إضافة كميات محددة من الأحماض أو القواعد.';
update public.question_answers set explanation = 'سعة المحلول المنظم : كمية الحمض أو القاعدة التي يستطيع المحلول المنظم أن يستوعبها دون تغير مهم في pH.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O06' and q.type = 'mcq' and q.number = 2) and explanation = 'سعة المحلول المنظم كما في الكتاب: كمية الحمض أو القاعدة التي يستطيع المحلول المنظم أن يستوعبها دون تغير مهم في pH.';
update public.question_answers set explanation = 'عند إضافة الكمية نفسها من HCl أو NaOH إلى 1 L من محلول منظم فقد يتغير pH بما لا يزيد على 0.1 وحدة.', distractor_notes = '["","التغير بمقدار وحدة كاملة يعني تغير [H⁺] عشرة أضعاف، وهذا أكبر مما يحدث للمحلول المنظم.","التغير بمقدار 5 وحدات هو ما يحدث للماء النقي (من 7.0 إلى 2.0 أو 12.0).","10 وحدات تغير هائل لا يحدث حتى في الماء النقي بهذه الكمية."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O06' and q.type = 'mcq' and q.number = 4) and explanation = 'ذكر الكتاب أنه عند إضافة الكمية نفسها من HCl أو NaOH إلى 1 L من محلول منظم فقد يتغير pH بما لا يزيد على 0.1 وحدة.';
update public.question_answers set explanation = 'قدرة المحلول المنظم على مقاومة تغير pH يتم تجاوزها في حالة إضافة كمية كبيرة من الحمض أو القاعدة؛ لأن له سعة محدودة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O06' and q.type = 'mcq' and q.number = 5) and explanation = 'ذكر الكتاب أن قدرة المحلول المنظم على مقاومة تغير pH يتم تجاوزها في حالة إضافة كمية كبيرة من الحمض أو القاعدة؛ لأن له سعة محدودة.';
update public.question_answers set explanation = 'كلما زادت تراكيز الجزيئات والأيونات المنظمة في المحلول زادت سعة المحلول المنظم.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O06' and q.type = 'mcq' and q.number = 6) and explanation = 'حسب الكتاب: كلما زادت تراكيز الجزيئات والأيونات المنظمة في المحلول زادت سعة المحلول المنظم.';
update public.question_answers set explanation = 'من المحاليل المنظمة ما يكون كل منها أكثر فاعلية عند pH معين (مثل 3.20 لـ HF/F⁻ و9.4 لـ NH₄⁺/NH₃)، فمنها الحمضي ومنها القاعدي.', distractor_notes = '["توجد محاليل منظمة عند pH 3.20 و4.76 و9.4 وغيرها، فليست كلها 7.","","للمحلول المنظم سعة محدودة تُتجاوز عند إضافة كمية كبيرة.","محلول NaCl مثلًا ليس منظمًا؛ فالمحلول المنظم يحتوي على مكونات تقاوم تغير pH."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O06' and q.type = 'mcq' and q.number = 7) and explanation = 'يبين الجدول 2-7 محاليل منظمة يكون كل منها أكثر فاعلية عند pH معين (مثل 3.20 لـ HF/F⁻ و9.4 لـ NH₄⁺/NH₃)، فمنها الحمضي ومنها القاعدي.';
update public.question_answers set explanation = 'المحلول المنظم خليط من حمض ضعيف مع قاعدته المرافقة، أو قاعدة ضعيفة مع حمضها المرافق.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O07' and q.type = 'mcq' and q.number = 1) and explanation = 'حسب الكتاب: المحلول المنظم خليط من حمض ضعيف مع قاعدته المرافقة، أو قاعدة ضعيفة مع حمضها المرافق.';
update public.question_answers set explanation = 'HF حمض ضعيف، وNaF يعطي أيون F⁻ وهو قاعدته المرافقة؛ فالخليط HF/NaF محلول منظم.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O07' and q.type = 'mcq' and q.number = 2) and explanation = 'HF حمض ضعيف، وNaF يعطي أيون F⁻ وهو قاعدته المرافقة؛ فالخليط HF/NaF محلول منظم كما في مثال الكتاب.';
update public.question_answers set explanation = 'NH₃ قاعدة ضعيفة، وNH₄⁺ (من NH₄Cl) حمضها المرافق؛ فهما الزوج NH₄⁺/NH₃.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O07' and q.type = 'mcq' and q.number = 3) and explanation = 'NH₃ قاعدة ضعيفة، وNH₄⁺ (من NH₄Cl) حمضها المرافق؛ فهما الزوج NH₄⁺/NH₃ الوارد في الجدول 2-7.';
update public.question_answers set explanation = 'المحلول المنظم يكون أكثر فاعلية عندما يساوي تركيز الحمض تركيز القاعدة المرافقة له أو يكاد يكون مساويًا؛ فعندها يستطيع استهلاك الحمض أو القاعدة المضافين بقدر متقارب.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O07' and q.type = 'mcq' and q.number = 7) and explanation = 'ذكر الكتاب أن المحلول المنظم يكون أكثر فاعلية عندما يساوي تركيز الحمض تركيز القاعدة المرافقة له أو يكاد يكون مساويًا؛ فعندها يستطيع استهلاك الحمض أو القاعدة المضافين بقدر متقارب.';
update public.question_answers set explanation = 'من المهم بقاء pH للدم في الجسم ضمن مدى 7.1 إلى 7.7.', distractor_notes = '["هذا مدى pH العصارة المعدية لا الدم.","هذا مدى pH مياه أحواض الأحياء المائية لقناديل البحر.","","هذا مدى حمضي لا يناسب الدم؛ فالدم قاعدي قليلًا."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O08' and q.type = 'mcq' and q.number = 1) and explanation = 'ذكر الكتاب أن من المهم بقاء pH للدم في الجسم ضمن مدى 7.1 إلى 7.7.';
update public.question_answers set distractor_notes = '["المحافظة على تراكيب البروتينات مرتبطة بمدى pH الدم (7.1 إلى 7.7).","صحة قناديل البحر مرتبطة بمدى pH أحواض الأحياء المائية (8.1 إلى 8.4).","لا يرتبط pH العصارة المعدية بغاز CO₂؛ بل بهضم الطعام.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O08' and q.type = 'mcq' and q.number = 2) and distractor_notes is not distinct from '["المحافظة على تراكيب البروتينات مرتبطة في الكتاب بمدى pH الدم (7.1 إلى 7.7).","صحة قناديل البحر مرتبطة بمدى pH أحواض الأحياء المائية (8.1 إلى 8.4).","لم يربط الكتاب pH العصارة المعدية بغاز CO₂؛ بل بهضم الطعام.",""]'::jsonb;
update public.question_answers set distractor_notes = '["","HF/F⁻ نظام منظم يكون أكثر فاعلية عند pH = 3.20، وليس من أنظمة الدم.","NH₄⁺/NH₃ نظام منظم أكثر فاعلية عند pH = 9.4، وليس من أنظمة الدم.","هذا النظام أكثر فاعلية عند pH = 10.70، وليس من أنظمة الدم."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O08' and q.type = 'mcq' and q.number = 3) and distractor_notes is not distinct from '["","HF/F⁻ نظام منظم يكون أكثر فاعلية عند pH = 3.20، ولم يذكره الكتاب للدم.","NH₄⁺/NH₃ نظام منظم أكثر فاعلية عند pH = 9.4، ولم يذكره الكتاب للدم.","هذا النظام أكثر فاعلية عند pH = 10.70، ولم يذكره الكتاب للدم."]'::jsonb;
update public.question_answers set distractor_notes = '["هذا مدى pH الدم في جسم الإنسان.","هذا مدى pH العصارة المعدية.","","مدى حمضي قليلًا لا يناسب قناديل البحر؛ والمطلوب لقناديل البحر مدى قاعدي قليلًا."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O08' and q.type = 'mcq' and q.number = 4) and distractor_notes is not distinct from '["هذا مدى pH الدم في جسم الإنسان.","هذا مدى pH العصارة المعدية.","","مدى حمضي قليلًا لم يذكره الكتاب؛ والمطلوب لقناديل البحر مدى قاعدي قليلًا."]'::jsonb;
update public.question_answers set explanation = 'الدم يحافظ على pH ضمن مدى ضيق بين 7.1 و7.7، وخارج هذا المستوى تفقد البروتينات في الجسم تراكيبها ومقدرتها على أداء عملها.', distractor_notes = '["هذا غير صحيح، ومدى pH الطبيعي للدم 7.1 إلى 7.7 وليس 7 تمامًا.","مدى pH العصارة المعدية (1.6 إلى 1.8) يختلف كثيرًا عن مدى pH الدم.","هذه مبالغة غير صحيحة؛ والأثر الصحيح هو فقد البروتينات تراكيبها ووظائفها.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O08' and q.type = 'mcq' and q.number = 5) and explanation = 'ذكر الكتاب أن الدم يحافظ على pH ضمن مدى ضيق بين 7.1 و7.7، وخارج هذا المستوى تفقد البروتينات في الجسم تراكيبها ومقدرتها على أداء عملها.';
update public.question_answers set explanation = 'قيمة pH للعصارة المعدية يجب أن تبقى بين 1.6 و1.8 فهي شديدة الحمضية، أما الدم فبين 7.1 و7.7 وحوض قناديل البحر بين 8.1 و8.4، والماء النقي pH له 7.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O08' and q.type = 'mcq' and q.number = 6) and explanation = 'يذكر الكتاب أن قيمة pH للعصارة المعدية يجب أن تبقى بين 1.6 و1.8 فهي شديدة الحمضية، أما الدم فبين 7.1 و7.7 وحوض قناديل البحر بين 8.1 و8.4، والماء النقي pH له 7.';
update public.question_answers set explanation = 'تفاعل التعادل إحلال مزدوج ينتج ملحًا وماء: Ca²⁺ من القاعدة مع Cl⁻ من الحمض يكوّنان CaCl₂. وكل 1 mol من Ca(OH)₂ يحتوي 2 mol OH⁻ فيحتاج إلى 2 mol HCl وينتج 2 mol H₂O: Ca(OH)₂ + 2HCl → CaCl₂ + 2H₂O.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O09' and q.type = 'mcq' and q.number = 6) and explanation = 'تفاعل التعادل إحلال مزدوج ينتج ملحًا وماء: Ca²⁺ من القاعدة مع Cl⁻ من الحمض يكوّنان CaCl₂. وكل 1 mol من Ca(OH)₂ يحتوي 2 mol OH⁻ فيحتاج إلى 2 mol HCl وينتج 2 mol H₂O: Ca(OH)₂ + 2HCl → CaCl₂ + 2H₂O، كما في مثال Mg(OH)₂ في الكتاب.';
update public.question_answers set explanation = 'الحجم المضاف = القراءة النهائية − القراءة الابتدائية = 18.78 − 0.50 = 18.28 mL.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O10' and q.type = 'mcq' and q.number = 6) and explanation = 'الحجم المضاف = القراءة النهائية − القراءة الابتدائية = 18.78 − 0.50 = 18.28 mL، وهو الحجم الذي تبينه القراءة الدقيقة للسحاحة في الشكل 2-25.';
update public.question_answers set distractor_notes = '["","مداه (3.2–4.4) أقل بكثير من 7، فيتغير لونه قبل نقطة التكافؤ.","مداه (8.2–10.0) لا يشمل 7؛ وهو الكاشف المناسب لمعايرة حمض ضعيف بقاعدة قوية.","مداه (10.0–12.0) أعلى بكثير من 7، فيتغير لونه بعد تجاوز نقطة التكافؤ."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O13' and q.type = 'mcq' and q.number = 1) and distractor_notes is not distinct from '["","مداه (3.2–4.4) أقل بكثير من 7، فيتغير لونه قبل نقطة التكافؤ.","مداه (8.2–10.0) لا يشمل 7؛ وهو الكاشف الذي يختاره الكتاب لمعايرة حمض ضعيف بقاعدة قوية.","مداه (10.0–12.0) أعلى بكثير من 7، فيتغير لونه بعد تجاوز نقطة التكافؤ."]'::jsonb;
update public.question_answers set explanation = 'القيمة 8.7 تقع داخل مدى الفينولفثالين (8.2–10.0)، فيتغير لونه عند نقطة التكافؤ؛ وهو الكاشف المناسب لمعايرة حمض ضعيف بقاعدة قوية.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O13' and q.type = 'mcq' and q.number = 2) and explanation = 'القيمة 8.7 تقع داخل مدى الفينولفثالين (8.2–10.0)، فيتغير لونه عند نقطة التكافؤ؛ وهو الكاشف المناسب لمعايرة حمض ضعيف بقاعدة قوية كما في الشكل 2-22b.';
update public.question_answers set distractor_notes = '["استعمل الكمية 0.01 mol بدل 0.005 mol المعطاة.","حسب pOH بدل pH، أو طرح الناتج من 14 دون مبرر؛ فالمحلول حمضي.","افترض أن الماء يقاوم التغير كالمحلول المنظم، فلم يتغير pH إلا 0.1 وحدة.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O14' and q.type = 'mcq' and q.number = 7) and distractor_notes is not distinct from '["استعمل كمية الكتاب (0.01 mol) بدل 0.005 mol المعطاة.","حسب pOH بدل pH، أو طرح الناتج من 14 دون مبرر؛ فالمحلول حمضي.","افترض أن الماء يقاوم التغير كالمحلول المنظم، فلم يتغير pH إلا 0.1 وحدة.",""]'::jsonb;
update public.question_answers set distractor_notes = '["التخفيف يقلل تراكيز المكونات فتقل السعة.","تقليل التراكيز يقلل كمية الحمض أو القاعدة التي يمكن استيعابها.","","السعة ترتبط بتراكيز المكونات المنظمة لا بدرجة الحرارة."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O15' and q.type = 'mcq' and q.number = 3) and distractor_notes is not distinct from '["التخفيف يقلل تراكيز المكونات فتقل السعة.","تقليل التراكيز يقلل كمية الحمض أو القاعدة التي يمكن استيعابها.","","الكتاب يربط السعة بتراكيز المكونات المنظمة لا بدرجة الحرارة."]'::jsonb;
update public.question_answers set explanation = 'عند تساوي تركيزي الحمض وقاعدته المرافقة يكون pH مساويًا pKa للحمض، وللزوج NH₄⁺/NH₃ القيمة 9.4، وهو المناسب (يلزم NH₄Cl لتوفير NH₄⁺).' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C2-L4-O16' and q.type = 'mcq' and q.number = 3) and explanation = 'عند تساوي تركيزي الحمض وقاعدته المرافقة يكون pH مساويًا pKa للحمض، وللزوج NH₄⁺/NH₃ القيمة 9.4، وهو المناسب كما في السؤال 52 من الكتاب (يلزم NH₄Cl لتوفير NH₄⁺).';
update public.question_answers set explanation = 'الأكسدة حاليًا هي فقدان ذرات المادة للإلكترونات، مثل تأكسد الصوديوم: Na → Na⁺ + e⁻.', distractor_notes = '["هذا تعريف الاختزال لا الأكسدة.","","ليس تعريف الأكسدة؛ والاتحاد بالهيدروجين يرتبط تاريخيًا بالاختزال لا بالأكسدة.","انتقال البروتونات يخص تفاعلات الأحماض والقواعد، أما الأكسدة فتتعلق بالإلكترونات."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L1-O01' and q.type = 'mcq' and q.number = 1) and explanation = 'يعرّف الكتاب الأكسدة حاليًا بأنها فقدان ذرات المادة للإلكترونات، مثل تأكسد الصوديوم: Na → Na⁺ + e⁻.';
update public.question_answers set explanation = 'يسمى التفاعل الذي تنتقل فيه الإلكترونات من إحدى الذرات إلى ذرة أخرى تفاعل الأكسدة والاختزال، كما في تفاعل Mg مع O₂.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L1-O01' and q.type = 'mcq' and q.number = 3) and explanation = 'يسمي الكتاب التفاعل الذي تنتقل فيه الإلكترونات من إحدى الذرات إلى ذرة أخرى تفاعل الأكسدة والاختزال، كما في تفاعل Mg مع O₂.';
update public.question_answers set explanation = 'كلمة الأكسدة أُطلقت فيما مضى على التفاعلات التي تتضمن اتحاد المادة بالأكسجين، مثل احتراق المغنيسيوم وصدأ الحديد.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L1-O01' and q.type = 'mcq' and q.number = 4) and explanation = 'يذكر الكتاب أن كلمة الأكسدة أُطلقت فيما مضى على التفاعلات التي تتضمن اتحاد المادة بالأكسجين، مثل احتراق المغنيسيوم وصدأ الحديد.';
update public.question_answers set explanation = 'العامل المختزل هو المادة التي تتأكسد؛ أي تفقد إلكترونات فيزيد عدد تأكسدها.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L1-O03' and q.type = 'mcq' and q.number = 1) and explanation = 'العامل المختزل هو المادة التي تتأكسد؛ أي تفقد إلكترونات فيزيد عدد تأكسدها (الجدول 1-3).';
update public.question_answers set explanation = 'كلٌّ من العامل المختزل والعامل المؤكسد مادة متفاعلة؛ فالعاملان من المتفاعلات، كما في 2K + Cl₂ حيث K المختزل وCl₂ المؤكسد.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L1-O03' and q.type = 'mcq' and q.number = 5) and explanation = 'يصف الجدول 1-3 كلًّا من X (المختزل) وY (المؤكسد) بأنها «المادة المتفاعلة»؛ فالعاملان من المتفاعلات، كما في 2K + Cl₂ حيث K المختزل وCl₂ المؤكسد.';
update public.question_answers set explanation = 'عدد التأكسد لذرة في المركب الأيوني هو عدد الإلكترونات التي فقدتها الذرة أو اكتسبتها عندما كوّنت الأيون.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L1-O04' and q.type = 'mcq' and q.number = 1) and explanation = 'يعرّف الكتاب عدد التأكسد لذرة في المركب الأيوني بأنه عدد الإلكترونات التي فقدتها الذرة أو اكتسبتها عندما كوّنت الأيون.';
update public.question_answers set explanation = 'عدد التأكسد أداة يستعملها العلماء لمساعدتهم على الاحتفاظ بمسار حركة الإلكترونات في تفاعلات الأكسدة والاختزال.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L1-O04' and q.type = 'mcq' and q.number = 4) and explanation = 'يذكر الكتاب أن عدد التأكسد أداة يستعملها العلماء لمساعدتهم على الاحتفاظ بمسار حركة الإلكترونات في تفاعلات الأكسدة والاختزال.';
update public.question_answers set distractor_notes = '["الذرة التي تجذب الإلكترونات نحوها تُعامل كأنها اكتسبتها، أي اختُزلت لا تأكسدت.","","الذرة الأقل كهروسالبية تُعامل كأنها فقدت الإلكترونات فتتأكسد.","يُعدّ هذا التفاعل أكسدة واختزالًا رغم عدم تكوّن أيونات، اعتمادًا على الكهروسالبية."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L1-O06' and q.type = 'mcq' and q.number = 1) and distractor_notes is not distinct from '["الذرة التي تجذب الإلكترونات نحوها تُعامل كأنها اكتسبتها، أي اختُزلت لا تأكسدت.","","الذرة الأقل كهروسالبية تُعامل كأنها فقدت الإلكترونات فتتأكسد.","يعدّ الكتاب هذا التفاعل أكسدة واختزال رغم عدم تكوّن أيونات، اعتمادًا على الكهروسالبية."]'::jsonb;
update public.question_answers set explanation = 'في تفاعلات المركبات الجزيئية تُختزل الذرات الأعلى كهروسالبية، وتتأكسد الذرات ذات الكهروسالبية الأقل.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L1-O06' and q.type = 'mcq' and q.number = 2) and explanation = 'يلخص الكتاب: في تفاعلات المركبات الجزيئية تُختزل الذرات الأعلى كهروسالبية، وتتأكسد الذرات ذات الكهروسالبية الأقل.';
update public.question_answers set explanation = 'تزداد الكهروسالبية من اليسار إلى اليمين عبر الدورة، وتقل في الاتجاه نحو أسفل المجموعة الواحدة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L1-O06' and q.type = 'mcq' and q.number = 3) and explanation = 'يبين الشكل 4-3 أن الكهروسالبية تزداد من اليسار إلى اليمين عبر الدورة، وتقل في الاتجاه نحو أسفل المجموعة الواحدة.';
update public.question_answers set distractor_notes = '["FeO أكسيد الحديد(II)، والصدأ أكسيد الحديد(III).","FeCl₃ كلوريد الحديد(III) وليس أكسيدًا؛ والصدأ ناتج عن الأكسجين.","","FeS كبريتيد الحديد(II)، ولا يتكون من تفاعل الحديد مع الهواء الرطب."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L1-O09' and q.type = 'mcq' and q.number = 1) and distractor_notes is not distinct from '["FeO أكسيد الحديد(II)، والكتاب يذكر أن الصدأ أكسيد الحديد(III).","FeCl₃ كلوريد الحديد(III) وليس أكسيدًا؛ والصدأ ناتج عن الأكسجين.","","FeS كبريتيد الحديد(II)، ولا يتكون من تفاعل الحديد مع الهواء الرطب."]'::jsonb;
update public.question_answers set explanation = 'الحديد يتأكسد عندما يلامسه الهواء الرطب، مكوّنًا Fe₂O₃ (الصدأ).', distractor_notes = '["","في الفراغ لا يوجد أكسجين ولا رطوبة يتفاعل معهما الحديد.","الدهان طريقة لحماية الحديد من الأكسدة لا سبب لها.","الصدأ يرتبط بالهواء الرطب لا الجاف."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L1-O09' and q.type = 'mcq' and q.number = 2) and explanation = 'يذكر الكتاب أن الحديد يتأكسد عندما يلامسه الهواء الرطب، مكوّنًا Fe₂O₃ (الصدأ).';
update public.question_answers set explanation = 'من طرائق حماية الحديد من الأكسدة الطلاء والدهان وإضافة المواد البلاستيكية؛ إذ تمنع وصول الهواء الرطب إلى سطحه.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L1-O09' and q.type = 'mcq' and q.number = 3) and explanation = 'يذكر الكتاب طرائق لحماية الحديد من الأكسدة، منها الطلاء والدهان وإضافة المواد البلاستيكية؛ إذ تمنع وصول الهواء الرطب إلى سطحه.';
update public.question_answers set explanation = 'هيبوكلوريت الصوديوم NaClO في مبيض الغسيل عامل مؤكسد يؤدي إلى أكسدة البقع والأصباغ ومواد أخرى.', distractor_notes = '["NaClO عامل مؤكسد لا مختزل.","عمل المبيض قائم على الأكسدة لا على الحمضية.","المبيض يغيّر البقع كيميائيًا بأكسدتها.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L1-O09' and q.type = 'mcq' and q.number = 4) and explanation = 'يذكر الكتاب أن هيبوكلوريت الصوديوم NaClO في مبيض الغسيل عامل مؤكسد يؤدي إلى أكسدة البقع والأصباغ ومواد أخرى.';
update public.question_answers set explanation = 'عند كسر الكبسولة يحدث تفاعل بين مادتين تنتقل فيه الإلكترونات، فتتحول الطاقة الكيميائية إلى طاقة ضوئية.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L1-O09' and q.type = 'mcq' and q.number = 6) and explanation = 'يذكر الكتاب أنه عند كسر الكبسولة يحدث تفاعل بين مادتين تنتقل فيه الإلكترونات، فتتحول الطاقة الكيميائية إلى طاقة ضوئية.';
update public.question_answers set explanation = 'بعض التفاعلات تحدث فقط في المحاليل القاعدية، وعند وزنها يمكن إضافة أيونات الهيدروكسيد OH⁻ وجزيئات الماء H₂O إلى طرفي المعادلة؛ لذا فالإجابة: أيونات OH⁻ وجزيئات H₂O.', distractor_notes = '["هذا ما يُضاف في الوسط الحمضي، أما في الوسط القاعدي فلا تُترك أيونات H⁺ في المعادلة النهائية.","أيونات OH⁻ وحدها لا تكفي عادة لوزن الأكسجين والهيدروجين معًا، والمطلوب إضافة OH⁻ وجزيئات الماء.","","لا تُكتب H⁺ وOH⁻ معًا في معادلة نهائية؛ فهما يتحدان ماءً، والمطلوب في القاعدي OH⁻ وH₂O."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L2-O01' and q.type = 'mcq' and q.number = 1) and explanation = 'ينص الكتاب على أن بعض التفاعلات تحدث فقط في المحاليل القاعدية، وعند وزنها يمكن إضافة أيونات الهيدروكسيد OH⁻ وجزيئات الماء H₂O إلى طرفي المعادلة؛ لذا فالإجابة: أيونات OH⁻ وجزيئات H₂O.';
update public.question_answers set explanation = 'خطوات طريقة عدد التأكسد بالترتيب: تحديد أعداد التأكسد، ثم تحديد الذرات المتأكسدة والمختزلة، ثم تحديد التغير، ثم جعل التغير متساويًا بضبط المعاملات، ثم الطريقة التقليدية. فالخطوة التالية لتحديد التغير هي مساواة التغير بضبط المعاملات.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L2-O02' and q.type = 'mcq' and q.number = 2) and explanation = 'خطوات طريقة عدد التأكسد بالترتيب (الجدول 4-3): تحديد أعداد التأكسد، ثم تحديد الذرات المتأكسدة والمختزلة، ثم تحديد التغير، ثم جعل التغير متساويًا بضبط المعاملات، ثم الطريقة التقليدية. فالخطوة التالية لتحديد التغير هي مساواة التغير بضبط المعاملات.';
update public.question_answers set explanation = 'أيونات الهيدروجين H⁺ وجزيئات الماء توجد في المحلول بوفرة، وتستطيع المشاركة في تفاعل الأكسدة والاختزال في صورة متفاعلات أو نواتج؛ لذا تُضاف بالعدد الكافي لوزن الأكسجين والهيدروجين والشحنة.', distractor_notes = '["","لا يتغير عدد تأكسد H (1+) ولا O (2−) فيها عادة؛ فهي لا تتأكسد ولا تختزل في هذه التفاعلات.","هي ليست متفرجة؛ إذ تُضاف تحديدًا لوزن ذرات O وH والشحنة.","المطلوب تساوي الشحنة في الطرفين لا أن تساوي صفرًا؛ فقد تتساوى الشحنة في الطرفين دون أن تساوي صفرًا."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L2-O04' and q.type = 'mcq' and q.number = 1) and explanation = 'يذكر الكتاب أن أيونات الهيدروجين H⁺ وجزيئات الماء توجد في المحلول بوفرة، وتستطيع المشاركة في تفاعل الأكسدة والاختزال في صورة متفاعلات أو نواتج؛ لذا تُضاف بالعدد الكافي لوزن الأكسجين والهيدروجين والشحنة.';
update public.question_answers set distractor_notes = '["المواد المتأكسدة والمختزلة تُحدد من التغير في أعداد التأكسد، لا من نوع الوسط.","","طريقة عدد التأكسد تُستعمل في الوسط الحمضي.","في كل الأوساط يجب أن يتساوى عدد الإلكترونات المفقودة والمكتسبة."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L2-O04' and q.type = 'mcq' and q.number = 5) and distractor_notes is not distinct from '["المواد المتأكسدة والمختزلة تُحدد من التغير في أعداد التأكسد، لا من نوع الوسط.","","طريقة عدد التأكسد استُعملت في الكتاب في وسط حمضي (المثال 4-3).","في كل الأوساط يجب أن يتساوى عدد الإلكترونات المفقودة والمكتسبة."]'::jsonb;
update public.question_answers set explanation = 'نصف التفاعل هو أحد جزأي تفاعل الأكسدة والاختزال؛ أي تفاعل الأكسدة (فقد الإلكترونات) أو تفاعل الاختزال (كسب الإلكترونات).' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L2-O05' and q.type = 'mcq' and q.number = 1) and explanation = 'يعرّف الكتاب نصف التفاعل بأنه أحد جزأي تفاعل الأكسدة والاختزال؛ أي تفاعل الأكسدة (فقد الإلكترونات) أو تفاعل الاختزال (كسب الإلكترونات).';
update public.question_answers set explanation = 'أيون الفضة Ag⁺ يكتسب إلكترونًا واحدًا فيختزل إلى فلز الفضة: Ag⁺ + e⁻ → Ag، بينما يتأكسد الحديد إلى Fe³⁺.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L2-O05' and q.type = 'mcq' and q.number = 3) and explanation = 'أيون الفضة Ag⁺ يكتسب إلكترونًا واحدًا فيختزل إلى فلز الفضة: Ag⁺ + e⁻ → Ag، كما في الجدول 5-3، بينما يتأكسد الحديد إلى Fe³⁺.';
update public.question_answers set explanation = 'الحديد يتأكسد من صفر إلى 3+: Fe → Fe³⁺ + 3e⁻، والفلور يختزل من صفر إلى 1−، وجزيء F₂ يكتسب إلكترونين: F₂ + 2e⁻ → 2F⁻.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L2-O05' and q.type = 'mcq' and q.number = 6) and explanation = 'الحديد يتأكسد من صفر إلى 3+: Fe → Fe³⁺ + 3e⁻، والفلور يختزل من صفر إلى 1−، وجزيء F₂ يكتسب إلكترونين: F₂ + 2e⁻ → 2F⁻، كما في الجدول 5-3.';
update public.question_answers set explanation = 'يظهر النيتروجين في HNO₃ وCu(NO₃)₂ وNO₂ فيصعب وزن المعادلة بالطريقة التقليدية، لذا تُوزن بطريقة عدد التأكسد بمساواة الزيادة في عدد تأكسد Cu بالنقصان في عدد تأكسد N.', distractor_notes = '["العنصر الذي يظهر أكثر من مرة في كل جهة (كالنيتروجين هنا) يصعب وزنه بالطريقة التقليدية.","تتطلب طريقة نصف التفاعل أولًا كتابة المعادلة الأيونية الكلية، ولا تُطبَّق مباشرة على المعادلة الجزيئية.","التفاعل هنا في وسط حمضي (HNO₃)، وليس سبب اختيار الطريقة نوع الوسط القاعدي.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L2-O07' and q.type = 'mcq' and q.number = 1) and explanation = 'يظهر النيتروجين في HNO₃ وCu(NO₃)₂ وNO₂ فيصعب وزن المعادلة بالطريقة التقليدية، لذا تُوزن بطريقة عدد التأكسد بمساواة الزيادة في عدد تأكسد Cu بالنقصان في عدد تأكسد N كما في المثال 3-3.';
update public.question_answers set distractor_notes = '["","يمكن وزن هذا التفاعل نفسه بطريقة نصف التفاعل؛ وطريقة عدد التأكسد ليست الوحيدة للمعادلات الأيونية.","لا يكفي عدّ الذرات هنا؛ فالشحنة غير متساوية ولا بد من مساواة الإلكترونات المفقودة والمكتسبة.","المعادلات الأيونية تُوزن بالطريقتين المقررتين، ولا يمنع وجود الأيونات الوزن."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C3-L2-O07' and q.type = 'mcq' and q.number = 2) and distractor_notes is not distinct from '["","الكتاب وزن هذا التفاعل نفسه بطريقة نصف التفاعل؛ وطريقة عدد التأكسد ليست الوحيدة للمعادلات الأيونية.","لا يكفي عدّ الذرات هنا؛ فالشحنة غير متساوية ولا بد من مساواة الإلكترونات المفقودة والمكتسبة.","المعادلات الأيونية تُوزن بالطريقتين المقررتين، ولا يمنع وجود الأيونات الوزن."]'::jsonb;
update public.question_answers set explanation = 'الكيمياء الكهربائية هي دراسة عمليات الأكسدة والاختزال التي تتحول من خلالها الطاقة الكيميائية إلى طاقة كهربائية، وبالعكس؛ فالإجابة: دراسة عمليات الأكسدة والاختزال التي تتحول بها الطاقة الكيميائية إلى كهربائية وبالعكس.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O01' and q.type = 'mcq' and q.number = 1) and explanation = 'يعرّف الكتاب الكيمياء الكهربائية بأنها دراسة عمليات الأكسدة والاختزال التي تتحول من خلالها الطاقة الكيميائية إلى طاقة كهربائية، وبالعكس؛ فالإجابة: دراسة عمليات الأكسدة والاختزال التي تتحول بها الطاقة الكيميائية إلى كهربائية وبالعكس.';
update public.question_answers set explanation = 'الأكسدة فقدان الذرات للإلكترونات أو الزيادة في عدد التأكسد، وأن الاختزال اكتساب الإلكترونات أو النقص في عدد التأكسد؛ فالإجابة: فقدان الذرات للإلكترونات أو الزيادة في عدد التأكسد.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O01' and q.type = 'mcq' and q.number = 6) and explanation = 'تذكر مراجعة المفردات في الكتاب أن الأكسدة فقدان الذرات للإلكترونات أو الزيادة في عدد التأكسد، وأن الاختزال اكتساب الإلكترونات أو النقص في عدد التأكسد؛ فالإجابة: فقدان الذرات للإلكترونات أو الزيادة في عدد التأكسد.';
update public.question_answers set explanation = 'الكيمياء الكهربائية تدرس تفاعلات الأكسدة والاختزال التي تتحول فيها الطاقة الكيميائية إلى كهربائية (كالبطارية) وبالعكس (كالخلية التي يُمرَّر فيها تيار لإحداث تفاعل)، والخلية الكهروكيميائية تشمل الحالتين؛ لذا فكلا الجهازين من مجالها.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O01' and q.type = 'mcq' and q.number = 7) and explanation = 'الكيمياء الكهربائية تدرس تفاعلات الأكسدة والاختزال التي تتحول فيها الطاقة الكيميائية إلى كهربائية (كالبطارية) وبالعكس (كالخلية التي يُمرَّر فيها تيار لإحداث تفاعل)، والخلية الكهروكيميائية في الكتاب تشمل الحالتين؛ لذا فكلا الجهازين من مجالها.';
update public.question_answers set explanation = 'الخلية الجلفانية نوع من الخلايا الكهروكيميائية تحول الطاقة الكيميائية إلى طاقة كهربائية بواسطة تفاعل الأكسدة والاختزال التلقائي.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O02' and q.type = 'mcq' and q.number = 1) and explanation = 'يعرّف الكتاب الخلية الجلفانية بأنها نوع من الخلايا الكهروكيميائية تحول الطاقة الكيميائية إلى طاقة كهربائية بواسطة تفاعل الأكسدة والاختزال التلقائي، وهذا نص البديل الصحيح.';
update public.question_answers set explanation = 'عند كتابة رمز الخلية يُكتب أولًا نصف تفاعل الأكسدة (الأنود) باستعمال رمز المادة المتفاعلة ثم الناتجة، ثم يُكتب نصف تفاعل الاختزال على اليمين؛ فالذي يُكتب يسارًا نصف خلية الأنود الذي تحدث فيه الأكسدة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O03' and q.type = 'mcq' and q.number = 2) and explanation = 'قاعدة الكتاب: اكتب أولًا نصف تفاعل الأكسدة (الأنود) باستعمال رمز المادة المتفاعلة ثم الناتجة، ثم اكتب نصف تفاعل الاختزال على اليمين؛ فالذي يُكتب يسارًا نصف خلية الأنود الذي تحدث فيه الأكسدة.';
update public.question_answers set explanation = 'الخارصين يتأكسد (Zn → Zn²⁺) فيُكتب يسارًا بالمتفاعل ثم الناتج، وأيونات الهيدروجين تُختزل (2H⁺ → H₂) فتُكتب يمينًا؛ فالرمز Zn | Zn²⁺(1M) || H⁺(1M) | H₂.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O03' and q.type = 'mcq' and q.number = 6) and explanation = 'الخارصين يتأكسد (Zn → Zn²⁺) فيُكتب يسارًا بالمتفاعل ثم الناتج، وأيونات الهيدروجين تُختزل (2H⁺ → H₂) فتُكتب يمينًا؛ فالرمز Zn | Zn²⁺(1M) || H⁺(1M) | H₂ كما في الكتاب.';
update public.question_answers set explanation = 'القنطرة الملحية ممر لتدفق الأيونات من جهة إلى أخرى، أي من نصف خلية إلى الآخر.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O04' and q.type = 'mcq' and q.number = 1) and explanation = 'يعرّف الكتاب القنطرة الملحية بأنها ممر لتدفق الأيونات من جهة إلى أخرى، أي من نصف خلية إلى الآخر.';
update public.question_answers set explanation = 'تتراكم أيونات الخارصين الموجبة حول قطب الخارصين خلال تأكسده، وتتراكم أيونات الكبريتات السالبة حول قطب النحاس خلال اختزاله، وهذا التراكم يوقف أي استمرار للتفاعل؛ وحل المشكلة هو القنطرة الملحية.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O04' and q.type = 'mcq' and q.number = 3) and explanation = 'يبين الكتاب أن أيونات الخارصين الموجبة تتراكم حول قطب الخارصين خلال تأكسده، وأيونات الكبريتات السالبة تتراكم حول قطب النحاس خلال اختزاله، وهذا التراكم يوقف أي استمرار للتفاعل؛ وحل المشكلة هو القنطرة الملحية.';
update public.question_answers set explanation = 'عند الأنود (Zn) تتكون أيونات Zn²⁺ موجبة، فتتجه إليه الأيونات السالبة من القنطرة، وعند الكاثود (Cu) تُستهلك أيونات Cu²⁺ فتبقى أيونات SO₄²⁻ زائدة، فتتجه إليه الأيونات الموجبة؛ فالسالبة نحو الخارصين والموجبة نحو النحاس.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O04' and q.type = 'mcq' and q.number = 4) and explanation = 'عند الأنود (Zn) تتكون أيونات Zn²⁺ موجبة، فتتجه إليه الأيونات السالبة من القنطرة، وعند الكاثود (Cu) تُستهلك أيونات Cu²⁺ فتبقى أيونات SO₄²⁻ زائدة، فتتجه إليه الأيونات الموجبة؛ كما في الشكل 4-2: السالبة نحو الخارصين والموجبة نحو النحاس.';
update public.question_answers set explanation = 'يُحفظ محلول القنطرة بجل هلامي أو أي غطاء يسمح للأيونات بالحركة خلاله، على ألا يختلط المحلولان في الكأسين.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O04' and q.type = 'mcq' and q.number = 6) and explanation = 'ينص الكتاب على أن محلول القنطرة يُحفظ بجل هلامي أو أي غطاء يسمح للأيونات بالحركة خلاله، على ألا يختلط المحلولان في الكأسين.';
update public.question_answers set explanation = 'لا يمكن تحديد جهد اختزال القطب بصورة مباشرة؛ لأن نصف تفاعل الاختزال لا بد أن يقترن بنصف تفاعل الأكسدة، والجهد الناتج يساوي فرق الجهد لنصفي التفاعل.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O05' and q.type = 'mcq' and q.number = 3) and explanation = 'يذكر الكتاب أنه لا يمكن تحديد جهد اختزال القطب بصورة مباشرة؛ لأن نصف تفاعل الاختزال لا بد أن يقترن بنصف تفاعل الأكسدة، والجهد الناتج يساوي فرق الجهد لنصفي التفاعل.';
update public.question_answers set explanation = 'بما أن جهد القطب لا يُقاس منفردًا، اتفق الكيميائيون على قياس جهود الأقطاب جميعها مقابل قطب مرجعي واحد عُيِّن جهده 0.000 V، فتصبح الجهود منسوبة إلى مرجع واحد يمكن مقارنتها وترتيبها.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O05' and q.type = 'mcq' and q.number = 4) and explanation = 'بما أن جهد القطب لا يُقاس منفردًا، اتفق الكيميائيون على قياس جهود الأقطاب جميعها مقابل قطب مرجعي واحد عُيِّن جهده 0.000 V، فتصبح الجهود منسوبة إلى مرجع واحد يمكن مقارنتها وترتيبها، كما في الجدول 4-1.';
update public.question_answers set explanation = 'قطب الهيدروجين القياسي يعمل بوصفه نصف تفاعل اختزال أو نصف تفاعل أكسدة اعتمادًا على نصف الخلية الموصول به؛ فهو كاثود مع الخارصين وأنود مع النحاس.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O05' and q.type = 'mcq' and q.number = 5) and explanation = 'يذكر الكتاب أن قطب الهيدروجين القياسي يعمل بوصفه نصف تفاعل اختزال أو نصف تفاعل أكسدة اعتمادًا على نصف الخلية الموصول به؛ فهو كاثود مع الخارصين وأنود مع النحاس.';
update public.question_answers set explanation = 'إذا كان الجهد المحسوب موجبًا فالتفاعل تلقائي، أما إذا كانت القيمة سالبة فالتفاعل غير تلقائي.', distractor_notes = '["الجهد السالب يدل على أن التفاعل غير تلقائي كما هو مكتوب.","القاعدة تربط التلقائية بالجهد الموجب، والصفر لا يدل على تلقائية التفاعل.","التنبؤ بالتلقائية من إشارة الجهد أحد الاستعمالين المهمين لجهود الاختزال.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O07' and q.type = 'mcq' and q.number = 1) and explanation = 'ينص الكتاب على أنه إذا كان الجهد المحسوب موجبًا فالتفاعل تلقائي، أما إذا كانت القيمة سالبة فالتفاعل غير تلقائي.';
update public.question_answers set explanation = 'الجهد السالب يعني أن التفاعل غير تلقائي كما هو مكتوب، وفي حالة عكس تفاعل غير تلقائي يكون له جهد خلية موجب، أي إن التفاعل العكسي تلقائي وجهده +0.46 V.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O07' and q.type = 'mcq' and q.number = 7) and explanation = 'الجهد السالب يعني أن التفاعل غير تلقائي كما هو مكتوب، ويذكر الكتاب أنه في حالة عكس تفاعل غير تلقائي يكون له جهد خلية موجب، أي إن التفاعل العكسي تلقائي وجهده +0.46 V.';
update public.question_answers set explanation = 'الخلية الكهروكيميائية جهاز يستعمل تفاعل الأكسدة والاختزال لإنتاج طاقة كهربائية، أو يستعمل الطاقة الكهربائية لإحداث تفاعل كيميائي.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O08' and q.type = 'mcq' and q.number = 1) and explanation = 'يعرّف الكتاب الخلية الكهروكيميائية بأنها جهاز يستعمل تفاعل الأكسدة والاختزال لإنتاج طاقة كهربائية، أو يستعمل الطاقة الكهربائية لإحداث تفاعل كيميائي.';
update public.question_answers set explanation = 'جهد الخلية هو القوة الدافعة الكهربائية الناشئة عن فرق طاقة الوضع الكهربائية بين القطبين، وهو إشارة إلى كمية الطاقة المتوفرة لدفع الإلكترونات من الأنود إلى الكاثود.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O09' and q.type = 'mcq' and q.number = 3) and explanation = 'يعرّف الكتاب جهد الخلية بأنه القوة الدافعة الكهربائية الناشئة عن فرق طاقة الوضع الكهربائية بين القطبين، وهو إشارة إلى كمية الطاقة المتوفرة لدفع الإلكترونات من الأنود إلى الكاثود.';
update public.question_answers set explanation = 'قوة الجاذبية تسحب الغواص نحو وضع منخفض من الطاقة، وأن الإلكترونات تتدفق في الخلية من الأنود إلى الكاثود لوجود فرق طاقة وضع كهربائية؛ فالحركة في الحالتين تلقائية من الطاقة الأعلى إلى الأدنى.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O09' and q.type = 'mcq' and q.number = 7) and explanation = 'يوضح الكتاب أن قوة الجاذبية تسحب الغواص نحو وضع منخفض من الطاقة، وأن الإلكترونات تتدفق في الخلية من الأنود إلى الكاثود لوجود فرق طاقة وضع كهربائية؛ فالحركة في الحالتين تلقائية من الطاقة الأعلى إلى الأدنى.';
update public.question_answers set explanation = 'جهد الاختزال هو مدى قابلية المادة لاكتساب الإلكترونات (الاختزال هو اكتساب الإلكترونات).' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O10' and q.type = 'mcq' and q.number = 1) and explanation = 'يعرّف الكتاب جهد الاختزال بأنه مدى قابلية المادة لاكتساب الإلكترونات (الاختزال هو اكتساب الإلكترونات).';
update public.question_answers set explanation = 'يجب أن يُقاس جهد القطب تحت الظروف القياسية، وهي غمس القطب في محلول أيوناته تركيزه 1M عند 25°C و1 atm.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O10' and q.type = 'mcq' and q.number = 3) and explanation = 'ينص الكتاب على أن جهد القطب يجب أن يُقاس تحت الظروف القياسية، وهي غمس القطب في محلول أيوناته تركيزه 1M عند 25°C و1 atm.';
update public.question_answers set distractor_notes = '["","القيمة الموجبة أكبر من السالبة، فجهد الفضة أكبر.","الإشارتان معكوستان عن القيمتين الصحيحتين.","القيمتان مختلفتان؛ فلكل نصف خلية جهد اختزال قياسي خاص."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O10' and q.type = 'mcq' and q.number = 4) and distractor_notes is not distinct from '["","القيمة الموجبة أكبر من السالبة، فجهد الفضة أكبر.","الإشارتان معكوستان عن قيمتي الجدول 4-1.","القيمتان مختلفتان؛ فلكل نصف خلية جهد اختزال قياسي خاص."]'::jsonb;
update public.question_answers set explanation = 'تفسَّر الإشارة السالبة بأن أيونات الهيدروجين عند قطب الهيدروجين تكتسب الإلكترونات أسهل من أيونات الخارصين، لذا جهد اختزال أيونات الهيدروجين أعلى من جهد اختزال أيونات الخارصين، ولما كان جهد الهيدروجين 0.00 V فجهد الخارصين سالب.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O11' and q.type = 'mcq' and q.number = 2) and explanation = 'يفسر الكتاب الإشارة السالبة بأن أيونات الهيدروجين عند قطب الهيدروجين تكتسب الإلكترونات أسهل من أيونات الخارصين، لذا جهد اختزال أيونات الهيدروجين أعلى من جهد اختزال أيونات الخارصين، ولما كان جهد الهيدروجين 0.00 V فجهد الخارصين سالب.';
update public.question_answers set distractor_notes = '["الإشارتان واتجاها التدفق معكوسة عن القيم الصحيحة.","الخارصين جهده −0.762 V وتتدفق الإلكترونات بعيدًا عنه.","النحاس جهده +0.342 V وتتدفق الإلكترونات نحوه.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O11' and q.type = 'mcq' and q.number = 7) and distractor_notes is not distinct from '["الإشارتان واتجاها التدفق معكوسة عن القيم في الكتاب.","الخارصين جهده −0.762 V وتتدفق الإلكترونات بعيدًا عنه.","النحاس جهده +0.342 V وتتدفق الإلكترونات نحوه.",""]'::jsonb;
update public.question_answers set distractor_notes = '["بطارية الحاسوب المحمول مثال على البطاريات الثانوية.","","بطارية المركم الرصاصي ثانوية تُشحن عندما يعمل المحرك.","بطاريات NiCad المستعملة في آلات الحلاقة ثانوية قابلة للشحن."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O01' and q.type = 'mcq' and q.number = 4) and distractor_notes is not distinct from '["بطارية الحاسوب المحمول مثال الكتاب على البطاريات الثانوية.","","بطارية المركم الرصاصي ثانوية تُشحن عندما يعمل المحرك.","بطاريات NiCad المستعملة في آلات الحلاقة ثانوية قابلة للشحن."]'::jsonb;
update public.question_answers set explanation = 'بطارية السيارة والحاسوب المحمول مثالان على البطاريات الثانوية التي تُسمّى في بعض الأحيان بطاريات التخزين.', distractor_notes = '["الخلية الجافة خلية جلفانية محلولها الموصل عجينة رطبة، ومعظمها أولي.","خلايا الوقود تُزوَّد بالوقود من مصدر خارجي ولا تُشحن، وليست اسمًا للبطاريات الثانوية.","الخلية الإلكتروليتية تستعمل الكهرباء لإحداث تفاعل غير تلقائي، وليست اسمًا للبطاريات الثانوية.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O01' and q.type = 'mcq' and q.number = 6) and explanation = 'يذكر الكتاب أن بطارية السيارة والحاسوب المحمول مثالان على البطاريات الثانوية التي تُسمّى في بعض الأحيان بطاريات التخزين.';
update public.question_answers set explanation = 'بطاريات الليثيوم يمكن أن تكون أولية أو ثانوية اعتمادًا على تفاعلات الاختزال التي دُمجت مع تأكسد الليثيوم؛ فالمعيار هو قابلية التفاعل للانعكاس.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O01' and q.type = 'mcq' and q.number = 7) and explanation = 'ينص الكتاب على أن بطاريات الليثيوم يمكن أن تكون أولية أو ثانوية اعتمادًا على تفاعلات الاختزال التي دُمجت مع تأكسد الليثيوم؛ فالمعيار هو قابلية التفاعل للانعكاس.';
update public.question_answers set explanation = 'المحلول الموصل الشائع في خلية الوقود محلول قلوي من هيدروكسيد البوتاسيوم KOH، وتستعمل أيونات OH⁻ منه في تفاعل الأنود.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O02' and q.type = 'mcq' and q.number = 2) and explanation = 'يذكر الكتاب أن المحلول الموصل الشائع في خلية الوقود محلول قلوي من هيدروكسيد البوتاسيوم KOH، وتستعمل أيونات OH⁻ منه في تفاعل الأنود.';
update public.question_answers set explanation = 'اختزال الأكسجين ينتج 4 أيونات هيدروكسيد تعمل على تعويض أيونات الهيدروكسيد المستخدمة عند الأنود، فلا يُستهلك المحلول القلوي.', distractor_notes = '["الذي يختزل الأكسجين هو الإلكترونات، وأيونات OH⁻ ناتج الاختزال لا عامله.","KOH يبقى ذائبًا في المحلول الموصل، ولا يترسب.","","الدائرة الخارجية تنقل الإلكترونات، أما الأيونات فتنتقل في المحلول الموصل."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O02' and q.type = 'mcq' and q.number = 5) and explanation = 'ينص الكتاب على أن اختزال الأكسجين ينتج 4 أيونات هيدروكسيد تعمل على تعويض أيونات الهيدروكسيد المستخدمة عند الأنود، فلا يُستهلك المحلول القلوي.';
update public.question_answers set explanation = 'التآكل هو خسارة الفلز الناتجة عن تفاعل أكسدة واختزال بين الفلز والمواد التي في البيئة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O03' and q.type = 'mcq' and q.number = 1) and explanation = 'يعرّف الكتاب التآكل بأنه خسارة الفلز الناتجة عن تفاعل أكسدة واختزال بين الفلز والمواد التي في البيئة.';
update public.question_answers set explanation = 'تآكل الحديد هو المعروف بالصدأ، وهو مثال على تفاعل أكسدة واختزال تلقائي يحدث في الطبيعة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O03' and q.type = 'mcq' and q.number = 2) and explanation = 'يذكر الكتاب أن تآكل الحديد هو المعروف بالصدأ، وهو مثال على تفاعل أكسدة واختزال تلقائي يحدث في الطبيعة.';
update public.question_answers set distractor_notes = '["FeO أكسيد الحديد II، أما الصدأ فيتكون من اتحاد أيونات Fe³⁺ بالأكسجين.","Fe(OH)₂ هيدروكسيد الحديد II، وليس صيغة الصدأ.","","FeCl₃ كلوريد الحديد III، ولا يدخل الكلور في معادلة تكوّن الصدأ."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O03' and q.type = 'mcq' and q.number = 3) and distractor_notes is not distinct from '["FeO أكسيد الحديد II، أما الصدأ فيتكون من اتحاد أيونات Fe³⁺ بالأكسجين.","Fe(OH)₂ هيدروكسيد الحديد II، وليس الصيغة التي يذكرها الكتاب للصدأ.","","FeCl₃ كلوريد الحديد III، ولا يدخل الكلور في معادلة تكوّن الصدأ."]'::jsonb;
update public.question_answers set explanation = 'تفاعلات الأكسدة والاختزال التلقائية تحدث في الخلايا الجلفانية، كما تحدث في الطبيعة بشكل تلقائي، ومن ذلك تآكل الحديد.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O03' and q.type = 'mcq' and q.number = 4) and explanation = 'يبين الكتاب أن تفاعلات الأكسدة والاختزال التلقائية تحدث في الخلايا الجلفانية، كما تحدث في الطبيعة بشكل تلقائي، ومن ذلك تآكل الحديد.';
update public.question_answers set explanation = 'الصدأ يحدث عند توافر كل من الماء والأكسجين، لذا فقطعة الحديد المتروكة معرضة للهواء والرطوبة أكثر عرضة للصدأ.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O03' and q.type = 'mcq' and q.number = 6) and explanation = 'يذكر الكتاب أن الصدأ يحدث عند توافر كل من الماء والأكسجين، لذا فقطعة الحديد المتروكة معرضة للهواء والرطوبة أكثر عرضة للصدأ.';
update public.question_answers set explanation = 'أيونات H⁺ تُزوَّد على الأرجح من تكوّن حمض الكربونيك الناتج عن ذوبان CO₂ من الهواء في الماء.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O04' and q.type = 'mcq' and q.number = 3) and explanation = 'يذكر الكتاب أن أيونات H⁺ تُزوَّد على الأرجح من تكوّن حمض الكربونيك الناتج عن ذوبان CO₂ من الهواء في الماء.';
update public.question_answers set explanation = 'يجب أن يكون الأنود المضحي فلزًا يتأكسد أسهل من الحديد؛ ومثاله المغنيسيوم الذي يُلف حول أنابيب الحديد المدفونة فيتآكل بدلًا منها.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O04' and q.type = 'mcq' and q.number = 6) and explanation = 'يجب أن يكون الأنود المضحي فلزًا يتأكسد أسهل من الحديد؛ ويذكر الكتاب المغنيسيوم الذي يُلف حول أنابيب الحديد المدفونة فيتآكل بدلًا منها.';
update public.question_answers set explanation = 'تستعمل البطارية القلوية عجينة KOH، وتستعمل بطارية NiCad محلول KOH، فكلتاهما تستعمل محلولًا قاعديًا من هيدروكسيد البوتاسيوم.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O06' and q.type = 'mcq' and q.number = 5) and explanation = 'تستعمل البطارية القلوية عجينة KOH، وتستعمل بطارية NiCad محلول KOH (الشكل 4-10)، فكلتاهما تستعمل محلولًا قاعديًا من هيدروكسيد البوتاسيوم.';
update public.question_answers set explanation = 'وجود الخارصين على هيئة مسحوق يوفر مساحة سطح أكبر للتفاعل، وهذا من أسباب كفاءة البطارية القلوية.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O07' and q.type = 'mcq' and q.number = 2) and explanation = 'يذكر الكتاب أن وجود الخارصين على هيئة مسحوق يوفر مساحة سطح أكبر للتفاعل، وهذا من أسباب كفاءة البطارية القلوية.';
update public.question_answers set distractor_notes = '["عمل الحافظة غلافًا لا يزيد الكفاءة، والقلوية أكثر كفاءة.","عمود الكربون كاثود غير فعال، ووجوده يزيد الحجم ولا يزيد الكفاءة.","الخارصين في القلوية يتأكسد عند الأنود؛ وإلا لما أنتجت تيارًا.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O07' and q.type = 'mcq' and q.number = 5) and distractor_notes is not distinct from '["عمل الحافظة غلافًا لا يزيد الكفاءة، والكتاب يعدّ القلوية أكثر كفاءة.","عمود الكربون كاثود غير فعال، ووجوده يزيد الحجم ولا يزيد الكفاءة.","الخارصين في القلوية يتأكسد عند الأنود؛ وإلا لما أنتجت تيارًا.",""]'::jsonb;
update public.question_answers set explanation = 'الخلية القلوية الجافة الأكثر كفاءة حلت محل خلية الخارصين والكربون الجافة في الكثير من التطبيقات.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O07' and q.type = 'mcq' and q.number = 7) and explanation = 'ينص الكتاب على أن الخلية القلوية الجافة الأكثر كفاءة حلت محل خلية الخارصين والكربون الجافة في الكثير من التطبيقات.';
update public.question_answers set common_errors = '["القول إن القلوية قابلة للشحن","القول إن القلوية لا تحتوي على خارصين","ذكر «أرخص» سببًا دون أساس علمي"]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O07' and q.type = 'essay' and q.number = 1) and common_errors is not distinct from '["القول إن القلوية قابلة للشحن","القول إن القلوية لا تحتوي على خارصين","ذكر «أرخص» سببًا دون أساس من الكتاب"]'::jsonb;
update public.question_answers set explanation = 'خلايا الوقود تختلف عن البطاريات الأخرى لأنها تزود بالوقود باستمرار من مصدر خارجي.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O08' and q.type = 'mcq' and q.number = 1) and explanation = 'ينص الكتاب على أن خلايا الوقود تختلف عن البطاريات الأخرى لأنها تزود بالوقود باستمرار من مصدر خارجي.';
update public.question_answers set explanation = 'البطارية خلية جلفانية أو أكثر في عبوة واحدة تنتج التيار الكهربائي.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O09' and q.type = 'mcq' and q.number = 1) and explanation = 'يعرّف الكتاب البطارية بأنها خلية جلفانية أو أكثر في عبوة واحدة تنتج التيار الكهربائي.';
update public.question_answers set model_answer = 'خلية الخارصين والكربون: جافة، لأن محلولها الموصل عجينة رطبة من ZnCl₂ وMnO₂ وNH₄Cl. البطارية القلوية: جافة، لأن محلولها الموصل عجينة من KOH. المركم الرصاصي: ليست جافة، لأن محلولها الموصل محلول سائل من حمض الكبريتيك. خلية الوقود القلوية: ليست جافة، لأن محلولها الموصل محلول قلوي من KOH (أو غشاء PEM)، لا عجينة رطبة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O09' and q.type = 'essay' and q.number = 3) and model_answer = 'خلية الخارصين والكربون: جافة، لأن محلولها الموصل عجينة رطبة من ZnCl₂ وMnO₂ وNH₄Cl. البطارية القلوية: جافة، لأن محلولها الموصل عجينة من KOH (يسميها الكتاب الخلية القلوية الجافة). المركم الرصاصي: ليست جافة، لأن محلولها الموصل محلول سائل من حمض الكبريتيك. خلية الوقود القلوية: ليست جافة، لأن محلولها الموصل محلول قلوي من KOH (أو غشاء PEM)، لا عجينة رطبة.';
update public.question_answers set distractor_notes = '["الكربون لا يتأكسد في الخلية.","هذا ليس سبب انخفاض الجهد.","","أيونات NH₄⁺ تُستهلك في تفاعل الكاثود ولا تزيد."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O11' and q.type = 'mcq' and q.number = 4) and distractor_notes is not distinct from '["الكربون لا يتأكسد في الخلية.","الكتاب لا يعزو انخفاض الجهد إلى ذلك.","","أيونات NH₄⁺ تُستهلك في تفاعل الكاثود ولا تزيد."]'::jsonb;
update public.question_answers set distractor_notes = '["الماء يتكوّن في التفاعل الكلي ولا يُستهلك، فيقل تركيز الحمض.","الحمض يُستهلك في أثناء توليد التيار كما توضح المعادلة الكلية.","PbSO₄ صلب يتكوّن ويبقى مكانه ولا يتفكك عند توليد التيار.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O12' and q.type = 'mcq' and q.number = 3) and distractor_notes is not distinct from '["الماء يتكوّن في التفاعل الكلي ولا يُستهلك، فيقل تركيز الحمض.","الكتاب ينص على أن الحمض يُستهلك في أثناء توليد التيار كما توضح المعادلة الكلية.","PbSO₄ صلب يتكوّن ويبقى مكانه ولا يتفكك عند توليد التيار.",""]'::jsonb;
update public.question_answers set explanation = 'كلٌّ من PbO₂ وPb وPbSO₄ مادة صلبة، لذا تبقى في مكان تكوّنها نفسه، فتكون المواد المتفاعلة في الأماكن المطلوبة في الاستعمال والشحن.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O12' and q.type = 'mcq' and q.number = 7) and explanation = 'يذكر الكتاب أن كلًّا من PbO₂ وPb وPbSO₄ مادة صلبة، لذا تبقى في مكان تكوّنها نفسه، فتكون المواد المتفاعلة في الأماكن المطلوبة في الاستعمال والشحن.';
update public.question_answers set explanation = 'الليثيوم أخف فلز معروف، وله أقل جهد اختزال قياسي (−3.04 V) بالنسبة إلى العناصر الفلزية الأخرى.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O13' and q.type = 'mcq' and q.number = 1) and explanation = 'ينص الكتاب على أن الليثيوم أخف فلز معروف، وله أقل جهد اختزال قياسي (−3.04 V) بالنسبة إلى العناصر الفلزية الأخرى.';
update public.question_answers set explanation = 'المركم الرصاصي ثقيل جدًّا فلا يكون عمليًا في السيارات الكهربائية، وأن الحل كان بطارية خفيفة الوزن تخزن كميات كبيرة من الطاقة بالنسبة إلى حجمها، فركّز المهندسون على الليثيوم.', distractor_notes = '["المركم يزود المحرك بطاقة ابتدائية عالية جدًّا.","المركم الرصاصي بطارية ثانوية قابلة للشحن.","","الليثيوم أخف فلز معروف، والرصاص ثقيل."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L2-O13' and q.type = 'mcq' and q.number = 7) and explanation = 'يذكر الكتاب أن المركم الرصاصي ثقيل جدًّا فلا يكون عمليًا في السيارات الكهربائية، وأن الحل كان بطارية خفيفة الوزن تخزن كميات كبيرة من الطاقة بالنسبة إلى حجمها، فركّز المهندسون على الليثيوم.';
update public.question_answers set distractor_notes = '["القنطرة الملحية تكمل الدائرة فقط ولا تزود الخلية بالطاقة اللازمة لعكس التفاعل.","التفاعل العكسي غير تلقائي ويُحدثه مصدر طاقة كهربائي خارجي لا التسخين.","تبديل القطبين دون مصدر طاقة لا يُحدث تفاعلًا غير تلقائي؛ فالتفاعل العكسي يحتاج إلى طاقة.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O01' and q.type = 'mcq' and q.number = 1) and distractor_notes is not distinct from '["القنطرة الملحية تكمل الدائرة فقط ولا تزود الخلية بالطاقة اللازمة لعكس التفاعل.","الكتاب يذكر أن التفاعل العكسي غير تلقائي ويُحدثه مصدر طاقة كهربائي خارجي لا التسخين.","تبديل القطبين دون مصدر طاقة لا يُحدث تفاعلًا غير تلقائي؛ فالتفاعل العكسي يحتاج إلى طاقة.",""]'::jsonb;
update public.question_answers set distractor_notes = '["لو كان التفاعل العكسي تلقائيًا لحدث دون مصدر طاقة؛ فهو غير تلقائي.","","الإلكترونات تنتقل في الدائرة الخارجية في الخلايا كلها؛ وليس هذا سبب الحاجة إلى الطاقة.","القنطرة الملحية تسمح بحركة الأيونات ولا تمنعها، ولا علاقة لها بالحاجة إلى مصدر طاقة."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O01' and q.type = 'mcq' and q.number = 2) and distractor_notes is not distinct from '["لو كان التفاعل العكسي تلقائيًا لحدث دون مصدر طاقة؛ والكتاب ينص على أنه غير تلقائي.","","الإلكترونات تنتقل في الدائرة الخارجية في الخلايا كلها؛ وليس هذا سبب الحاجة إلى الطاقة.","القنطرة الملحية تسمح بحركة الأيونات ولا تمنعها، ولا علاقة لها بالحاجة إلى مصدر طاقة."]'::jsonb;
update public.question_answers set explanation = 'عند تزويد الخلية بطاقة خارجية ينعكس تدفق الإلكترونات ويحدث التفاعل غير التلقائي الذي يستعيد الوضع الأصلي للخلية.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O01' and q.type = 'mcq' and q.number = 5) and explanation = 'عند تزويد الخلية بطاقة خارجية ينعكس تدفق الإلكترونات ويحدث التفاعل غير التلقائي الذي يستعيد الوضع الأصلي للخلية (الشكل 4-19).';
update public.question_answers set distractor_notes = '["هذا تفاعل محتمل عند الأنود، لكنه لا يحدث لأن تأكسد أيونات الكلوريد أسهل حدوثًا.","هذا اختزال، والاختزال يحدث عند الكاثود، ثم إنه لا يحدث في ماء البحر أصلًا.","","هذا اختزال الماء الذي يحدث عند الكاثود لا عند الأنود."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O02' and q.type = 'mcq' and q.number = 2) and distractor_notes is not distinct from '["هذا تفاعل محتمل عند الأنود، لكنه لا يحدث لأن تأكسد أيونات الكلوريد أسهل حدوثًا كما يذكر الكتاب.","هذا اختزال، والاختزال يحدث عند الكاثود، ثم إنه لا يحدث في ماء البحر أصلًا.","","هذا اختزال الماء الذي يحدث عند الكاثود لا عند الأنود."]'::jsonb;
update public.question_answers set model_answer = 'الكاثود: Na⁺ + e⁻ → Na أو 2H₂O + 2e⁻ → H₂ + 2OH⁻، ويحدث اختزال الماء لأن اختزال الهيدروجين في الماء أسهل حدوثًا (اختزال تفضيلي). الأنود: 2Cl⁻ → Cl₂ + 2e⁻ أو 2H₂O → O₂ + 4H⁺ + 4e⁻، ويحدث تأكسد أيونات الكلوريد لأنه أسهل حدوثًا. أما مصهور NaCl فلا يحتوي على ماء، فلا يوجد إلا Na⁺ ليُختزل عند الكاثود وCl⁻ ليتأكسد عند الأنود، فينتج Na وCl₂.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O02' and q.type = 'essay' and q.number = 2) and model_answer = 'الكاثود: Na⁺ + e⁻ → Na أو 2H₂O + 2e⁻ → H₂ + 2OH⁻، ويحدث اختزال الماء لأن اختزال الهيدروجين في الماء أسهل حدوثًا (اختزال تفضيلي). الأنود: 2Cl⁻ → Cl₂ + 2e⁻ أو 2H₂O → O₂ + 4H⁺ + 4e⁻، ويحدث تأكسد أيونات الكلوريد لأنه أسهل حدوثًا كما يذكر الكتاب. أما مصهور NaCl فلا يحتوي على ماء، فلا يوجد إلا Na⁺ ليُختزل عند الكاثود وCl⁻ ليتأكسد عند الأنود، فينتج Na وCl₂.';
update public.question_answers set explanation = 'في الخلية الجلفانية يوفر التفاعل التلقائي نفسه الطاقة الكهربائية، أما خلية التحليل فتحتاج إلى مصدر جهد خارجي يدفع التفاعل غير التلقائي.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O03' and q.type = 'mcq' and q.number = 3) and explanation = 'في الخلية الجلفانية يوفر التفاعل التلقائي نفسه الطاقة الكهربائية (كإضاءة المصباح في الشكل 4-19)، أما خلية التحليل فتحتاج إلى مصدر جهد خارجي يدفع التفاعل غير التلقائي.';
update public.question_answers set explanation = 'لا يحدث اختزال Na⁺ في ماء البحر لأن اختزال الهيدروجين في جزيئات الماء أسهل حدوثًا، فجزيئات الماء لديها ميل للاختزال أكثر من الصوديوم.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O04' and q.type = 'mcq' and q.number = 1) and explanation = 'لا يحدث اختزال Na⁺ في ماء البحر لأن اختزال الهيدروجين في جزيئات الماء أسهل حدوثًا، فجزيئات الماء لديها ميل للاختزال أكثر من الصوديوم (الشكل 4-21).';
update public.question_answers set explanation = 'اختزال الهيدروجين في الماء أسهل حدوثًا، ومن ثمّ يتم الاختزال التفضيلي للماء بدل أيونات الصوديوم.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O04' and q.type = 'mcq' and q.number = 3) and explanation = 'يذكر الكتاب أن اختزال الهيدروجين في الماء أسهل حدوثًا، ومن ثمّ يتم الاختزال التفضيلي للماء بدل أيونات الصوديوم.';
update public.question_answers set explanation = 'المركبات الأيونية لا يمكنها توصيل التيار إلا عندما تكون أيوناتها حرة الحركة، وذلك عند ذوبانها في الماء أو انصهارها.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O05' and q.type = 'mcq' and q.number = 2) and explanation = 'يذكر الكتاب أن المركبات الأيونية لا يمكنها توصيل التيار إلا عندما تكون أيوناتها حرة الحركة، وذلك عند ذوبانها في الماء أو انصهارها.';
update public.question_answers set explanation = 'التحليل الكهربائي هو استعمال الطاقة الكهربائية لإحداث تفاعل كيميائي.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O06' and q.type = 'mcq' and q.number = 1) and explanation = 'يعرّف الكتاب التحليل الكهربائي بأنه استعمال الطاقة الكهربائية لإحداث تفاعل كيميائي.';
update public.question_answers set explanation = 'في خلية التحليل الكهربائي يسبب مصدر خارجي للطاقة حدوث تفاعل أكسدة واختزال غير تلقائي.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O06' and q.type = 'mcq' and q.number = 5) and explanation = 'في خلية التحليل الكهربائي يسبب مصدر خارجي للطاقة حدوث تفاعل أكسدة واختزال غير تلقائي (الخلاصة ص 158).';
update public.question_answers set explanation = 'الصوديوم في حالته النقية يُستعمل مبرّدًا في المفاعلات النووية.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O08' and q.type = 'mcq' and q.number = 2) and explanation = 'يذكر الكتاب أن الصوديوم في حالته النقية يُستعمل مبرّدًا في المفاعلات النووية.';
update public.question_answers set distractor_notes = '["تنقية مياه السباحة من استعمالات الكلور.","بوليمر كلوريد الفينيل يُصنع باستعمال الكلور.","","المبيدات تعالَج بمركبات الكلور."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O08' and q.type = 'mcq' and q.number = 3) and distractor_notes is not distinct from '["تنقية مياه السباحة من استعمالات الكلور.","بوليمر كلوريد الفينيل يُصنع باستعمال الكلور.","","المبيدات تعالَج بمركبات الكلور وفق الكتاب."]'::jsonb;
update public.question_answers set explanation = 'الكلور يُستعمل في صناعة بوليمر كلوريد الفينيل الذي يُستعمل في صناعة الأنابيب.', distractor_notes = '["الهيدروجين لا يدخل في اسم البوليمر؛ فالذي يُستعمل في صناعته هو الكلور.","","البوليمر يُصنع من الكلور، ويُستعمل في الأنابيب.","تبريد المفاعلات من استعمالات الصوديوم، وبوليمر كلوريد الفينيل يُستعمل في الأنابيب."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O08' and q.type = 'mcq' and q.number = 4) and explanation = 'يذكر الكتاب (الشكل 4-21) أن الكلور يُستعمل في صناعة بوليمر كلوريد الفينيل الذي يُستعمل في صناعة الأنابيب.';
update public.question_answers set distractor_notes = '["الألومنيوم يتكون عند الكاثود ويستقر في قاع الخلية، لا على الأنود.","تُستهلك القضبان بتفاعل كربونها مع الأكسجين لا بذوبانها.","أيونات Al³⁺ تُختزل عند الكاثود ولا تتأكسد عند الأنود.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O09' and q.type = 'mcq' and q.number = 5) and distractor_notes is not distinct from '["الألومنيوم يتكون عند الكاثود ويستقر في قاع الخلية، لا على الأنود.","الكتاب يعلل استهلاكها بتفاعل كربونها مع الأكسجين لا بذوبانها.","أيونات Al³⁺ تُختزل عند الكاثود ولا تتأكسد عند الأنود.",""]'::jsonb;
update public.question_answers set distractor_notes = '["الألومنيوم يتكون مصهورًا عند الكاثود ويستقر في القاع.","","أصابع الجرافيت أنود؛ والألومنيوم يتكون بالاختزال عند الكاثود لا عندها.","الغاز المتصاعد هو CO₂، أما الألومنيوم فيتكون فلزًا مصهورًا."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O09' and q.type = 'mcq' and q.number = 6) and distractor_notes is not distinct from '["الألومنيوم يتكون مصهورًا عند الكاثود ويستقر في القاع وفق الكتاب.","","أصابع الجرافيت أنود؛ والألومنيوم يتكون بالاختزال عند الكاثود لا عندها.","الغاز المتصاعد هو CO₂، أما الألومنيوم فيتكون فلزًا مصهورًا."]'::jsonb;
update public.question_answers set distractor_notes = '["إعادة التدوير سببها كمية الكهرباء الهائلة لا ندرة الخام.","الكريوليت ليس المستهلك الرئيس للتكلفة؛ فالعامل الحاسم استهلاك الكهرباء.","صهر الألومنيوم المعاد تدويره هو الطاقة الوحيدة التي يحتاج إليها، وهي أقل بكثير.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O10' and q.type = 'mcq' and q.number = 1) and distractor_notes is not distinct from '["الكتاب يربط إعادة التدوير بكمية الكهرباء الهائلة لا بندرة الخام.","الكريوليت ليس المستهلك الرئيس للتكلفة؛ فالعامل الحاسم استهلاك الكهرباء.","صهر الألومنيوم المعاد تدويره هو الطاقة الوحيدة التي يحتاج إليها، وهي أقل بكثير.",""]'::jsonb;
update public.question_answers set explanation = 'إنتاج الألومنيوم من خامه يتطلب كمية هائلة من الكهرباء، أما المعاد تدويره فلا يحتاج إلا إلى حرارة صهره؛ لذا يوفر كل طن معاد تدويره كمية كبيرة من الطاقة الكهربائية.', distractor_notes = '["إعادة التدوير لا ترتبط بالنقاوة؛ فالحجة العلمية هي توفير الطاقة.","الكريوليت مذيب في الخلية، والمستهلك الرئيس للطاقة هو التحليل الكهربائي.","","يحتاج إلى حرارة الصهر في الفرن، فالقول إنه لا يحتاج إلى أي طاقة خطأ."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O10' and q.type = 'mcq' and q.number = 7) and explanation = 'إنتاج الألومنيوم من خامه يتطلب كمية هائلة من الكهرباء، أما المعاد تدويره فلا يحتاج إلا إلى حرارة صهره؛ لذا يوفر كل طن معاد تدويره كمية كبيرة من الطاقة الكهربائية (الشكل 4-22).';
update public.question_answers set distractor_notes = '["هذا اختزال يحدث عند الكاثود لا الأنود.","النحاس يتأكسد إلى أيونات النحاس II (Cu²⁺) لا Cu⁺.","","هذا تفاعل استخلاص النحاس من خامه بالتسخين، وليس تفاعل الأنود في التنقية."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O11' and q.type = 'mcq' and q.number = 4) and distractor_notes is not distinct from '["هذا اختزال يحدث عند الكاثود لا الأنود.","الكتاب يذكر أن النحاس يتأكسد إلى أيونات النحاس II (Cu²⁺) لا Cu⁺.","","هذا تفاعل استخلاص النحاس من خامه بالتسخين، وليس تفاعل الأنود في التنقية."]'::jsonb;
update public.question_answers set distractor_notes = '["لو ترسبت على الكاثود لما كان النحاس الناتج نقيًا.","","الشوائب تترسب في قاع الخلية لا أنها تتصاعد.","الشوائب مواد غير النحاس فلا تتحول إليه."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O11' and q.type = 'mcq' and q.number = 5) and distractor_notes is not distinct from '["لو ترسبت على الكاثود لما كان النحاس الناتج نقيًا.","","الكتاب يذكر أن الشوائب تترسب في قاع الخلية لا أنها تتصاعد.","الشوائب مواد غير النحاس فلا تتحول إليه."]'::jsonb;
update public.question_answers set distractor_notes = '["هذا تأكسد الفضة، ويحدث عند الأنود لا الكاثود.","أيون الفضة في هذه الخلية أحادي الشحنة Ag⁺.","","هذا اختزال الماء، أما في الطلاء فتُختزل أيونات الفضة وتترسب على الجسم."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O12' and q.type = 'mcq' and q.number = 3) and distractor_notes is not distinct from '["هذا تأكسد الفضة، ويحدث عند الأنود لا الكاثود.","أيون الفضة في هذه الخلية أحادي الشحنة Ag⁺ وفق الكتاب.","","هذا اختزال الماء، أما في الطلاء فتُختزل أيونات الفضة وتترسب على الجسم."]'::jsonb;
update public.question_answers set explanation = 'يجب مراقبة شدة التيار المار في الخلية والتحكم فيها للحصول على طبقة تغليف فلزية ناعمة ومتساوية.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L3-O12' and q.type = 'mcq' and q.number = 5) and explanation = 'ينص الكتاب على أنه يجب مراقبة شدة التيار المار في الخلية والتحكم فيها للحصول على طبقة تغليف فلزية ناعمة ومتساوية.';
update public.question_answers set explanation = 'الطول الموجي والتردد لا يؤثران في السعة، فهي خاصية مستقلة.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'C1-L1-O05' and q.type = 'mcq' and q.number = 5) and explanation = 'ذكرت المذكرة أن الطول الموجي والتردد لا يؤثران في السعة، فهي خاصية مستقلة.';
update public.question_answers set distractor_notes = '["خطأ شائع؛ التردد رمزه ν، أما v في المعادلة فهي السرعة.","","الحجم لا يظهر في المعادلة."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'C1-L2-O05' and q.type = 'mcq' and q.number = 3) and distractor_notes is not distinct from '["خطأ شائع (ورد في المذكرة)؛ التردد رمزه ν، أما v في المعادلة فهي السرعة.","","الحجم لا يظهر في المعادلة."]'::jsonb;
