update public.question_answers set common_errors = '["القول إن تكوين الروابط يمتص طاقة","وصف الحالتين كلتيهما بأنهما ماصتان"]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'C4-L1-O08' and q.type = 'essay' and q.number = 3) and common_errors is not distinct from '["القول إن تكوين الروابط يمتص طاقة","وصف الحالتين كلتيهما بأنهما ماصتان (كما ورد خطأً في المذكرة)"]'::jsonb;
update public.question_answers set explanation = 'إذا كان فرق الكهروسالبية أكبر من 1.7 تكون الرابطة أيونية (مثل NaCl).' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'C4-L5-O02' and q.type = 'mcq' and q.number = 1) and explanation = 'حسب المذكرة: إذا كان فرق الكهروسالبية أكبر من 1.7 تكون الرابطة أيونية (مثل NaCl).';
update public.question_answers set model_answer = 'Al–F: الفرق = 3.9 − 1.6 = 2.3 > 1.7 ← أيونية (مثل AlF₃). Al–Cl: الفرق = 3.1 − 1.6 = 1.5 < 1.7 ← تساهمية قطبية. إذن العبارة غير صحيحة على إطلاقها؛ فنوع الرابطة يحدده فرق الكهروسالبية لا مجرد كون إحدى الذرتين فلزًا، فقد تكون الرابطة بين فلز ولافلز تساهمية قطبية إذا كان الفرق أقل من 1.7.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'C4-L5-O02' and q.type = 'essay' and q.number = 3) and model_answer = 'Al–F: الفرق = 3.9 − 1.6 = 2.3 > 1.7 ← أيونية (AlF₃ مثال المذكرة). Al–Cl: الفرق = 3.1 − 1.6 = 1.5 < 1.7 ← تساهمية قطبية. إذن العبارة غير صحيحة على إطلاقها؛ فنوع الرابطة يحدده فرق الكهروسالبية لا مجرد كون إحدى الذرتين فلزًا، فقد تكون الرابطة بين فلز ولافلز تساهمية قطبية إذا كان الفرق أقل من 1.7.';
update public.question_answers set explanation = 'الكحول مركب قطبي، والماء مذيب قطبي، فتذوب جزيئات الكحول في الماء وفق قاعدة «الأشباه تذوب في الأشباه».' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'C4-L5-O04' and q.type = 'mcq' and q.number = 2) and explanation = 'الكحول مركب قطبي، والماء مذيب قطبي، فتذوب جزيئات الكحول في الماء وفق قاعدة «الأشباه تذوب في الأشباه» (مثال المذكرة).';
update public.question_answers set explanation = 'الزيت مادة غير قطبية والبنزين مذيب غير قطبي، فيذوب الزيت فيه.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'C4-L5-O05' and q.type = 'mcq' and q.number = 1) and explanation = 'الزيت مادة غير قطبية والبنزين مذيب غير قطبي، فيذوب الزيت فيه (مثال المذكرة: الزيت في البنزين).';
update public.question_answers set explanation = 'القوى بين الجزيئية (قوى فان دير فالس) أضعف من القوى الجزيئية (الروابط داخل الجزيء).' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'C4-L5-O06' and q.type = 'mcq' and q.number = 3) and explanation = 'حسب المذكرة: القوى بين الجزيئية (قوى فان دير فالس) أضعف من القوى الجزيئية (الروابط داخل الجزيء).';
update public.question_answers set explanation = 'Br₂ جزيء غير قطبي (ذرتان متماثلتان)، وقوى التشتت هي القوى بين الجزيئات غير القطبية (H₂، Cl₂، F₂، Br₂).' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'C4-L5-O07' and q.type = 'mcq' and q.number = 1) and explanation = 'Br₂ جزيء غير قطبي (ذرتان متماثلتان)، وقوى التشتت هي القوى بين الجزيئات غير القطبية كما في المذكرة (H₂، Cl₂، F₂، Br₂).';
update public.question_answers set explanation = 'تزداد قوة التشتت بزيادة عدد الإلكترونات، لأن السحابة الإلكترونية الأكبر يسهل إزاحتها مؤقتًا.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'C4-L5-O07' and q.type = 'mcq' and q.number = 5) and explanation = 'حسب المذكرة: تزداد قوة التشتت بزيادة عدد الإلكترونات، لأن السحابة الإلكترونية الأكبر يسهل إزاحتها مؤقتًا.';
update public.question_answers set explanation = 'ترتيب القوى: الرابطة الهيدروجينية > ثنائية القطب > التشتت، فقوى التشتت هي الأضعف بين القوى بين الجزيئية.', distractor_notes = '["الرابطة الهيدروجينية هي الأقوى في هذا الترتيب.","لا يحدث انتقال للإلكترونات، وإنما إزاحة مؤقتة لكثافتها.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'C4-L5-O07' and q.type = 'mcq' and q.number = 6) and explanation = 'حسب ترتيب المذكرة: الرابطة الهيدروجينية > ثنائية القطب > التشتت، فقوى التشتت هي الأضعف بين القوى بين الجزيئية.';
update public.question_answers set explanation = 'HCl جزيء قطبي له طرف δ+ (H) وطرف δ− (Cl)، فتنشأ بين جزيئاته قوى ثنائية القطب (مثل HCl وH₂O وNH₃).' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'C4-L5-O08' and q.type = 'mcq' and q.number = 2) and explanation = 'HCl جزيء قطبي له طرف δ+ (H) وطرف δ− (Cl)، فتنشأ بين جزيئاته قوى ثنائية القطب كما في أمثلة المذكرة (HCl، H₂O، NH₃).';
update public.question_answers set explanation = 'الرابطة الهيدروجينية تجاذب بين ذرة H متصلة بذرة عالية الكهروسالبية (F أو O أو N) في جزيء، وذرة F أو O أو N في جزيء آخر، فهي قوة بين جزيئية.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'C4-L5-O09' and q.type = 'mcq' and q.number = 1) and explanation = 'حسب المذكرة: الرابطة الهيدروجينية تجاذب بين ذرة H متصلة بذرة عالية الكهروسالبية (F أو O أو N) في جزيء، وذرة F أو O أو N في جزيء آخر، فهي قوة بين جزيئية.';
update public.question_answers set explanation = 'الرابطة الهيدروجينية قوة تجاذب بين الجزيئات وليست رابطة كيميائية داخل الجزيء، وترتيبها: هيدروجينية > ثنائية القطب > تشتت.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'C4-L5-O09' and q.type = 'mcq' and q.number = 5) and explanation = 'الرابطة الهيدروجينية قوة تجاذب بين الجزيئات وليست رابطة كيميائية داخل الجزيء، وترتيبها في المذكرة: هيدروجينية > ثنائية القطب > تشتت.';
update public.question_answers set explanation = 'المركبات التساهمية الجزيئية درجات انصهارها وغليانها منخفضة، والصلبة منها لينة، بسبب ضعف القوى بين جزيئاتها.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'C4-L5-O12' and q.type = 'mcq' and q.number = 7) and explanation = 'حسب المذكرة: المركبات التساهمية الجزيئية درجات انصهارها وغليانها منخفضة، والصلبة منها لينة، بسبب ضعف القوى بين جزيئاتها.';
update public.question_answers set explanation = 'من أمثلة المواد الصلبة التساهمية الشبكية الألماس والكوارتز.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'C4-L5-O13' and q.type = 'mcq' and q.number = 1) and explanation = 'حسب المذكرة: من أمثلة المواد الصلبة التساهمية الشبكية الألماس والكوارتز.';
update public.question_answers set distractor_notes = '["عبارة صحيحة: فانصهارها يتطلب كسر روابط تساهمية كثيرة.","عبارة صحيحة.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'C4-L5-O14' and q.type = 'mcq' and q.number = 7) and distractor_notes is not distinct from '["عبارة صحيحة: فانصهارها يتطلب كسر روابط تساهمية كثيرة.","عبارة صحيحة وردت في المذكرة.",""]'::jsonb;
update public.question_answers set explanation = 'ترتبط كل ذرة C في الألماس بأربع ذرات C بترتيب رباعي الأوجه.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'C4-L5-O15' and q.type = 'mcq' and q.number = 2) and explanation = 'حسب المذكرة: ترتبط كل ذرة C في الألماس بأربع ذرات C بترتيب رباعي الأوجه.';
update public.question_answers set explanation = 'O2 وCl2 وBr2 جزيئات ثنائية الذرة متماثلة غير قطبية، فالقوى بين جزيئاتها قوى تشتت فقط.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'C6-L2-O04' and q.type = 'mcq' and q.number = 2) and explanation = 'O2 وCl2 وBr2 جزيئات ثنائية الذرة متماثلة غير قطبية، فالقوى بين جزيئاتها قوى تشتت فقط، وهي من أمثلة المذكرة.';
update public.question_answers set explanation = 'في الماء ترتبط كل ذرة H مباشرة بذرة O، فتنشأ روابط هيدروجينية بين جزيئاته.' where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'C6-L2-O08' and q.type = 'mcq' and q.number = 1) and explanation = 'في الماء ترتبط كل ذرة H مباشرة بذرة O، فتنشأ روابط هيدروجينية بين جزيئاته، وهو من أمثلة المذكرة.';
update public.question_answers set distractor_notes = '["وقود السيارات خليط من مواد عدة، وليس المقصود هنا.","","لا علاقة للماء بالعبارة؛ فالمادة نفسها في الحالتين."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'C6-L3-O25' and q.type = 'mcq' and q.number = 2) and distractor_notes is not distinct from '["وقود السيارات خليط من مواد عدة، وليس المقصود في الكتاب.","","لا علاقة للماء بالعبارة؛ فالمادة نفسها في الحالتين."]'::jsonb;
