update public.question_answers set distractor_notes = '["المادة المتأينة لا تُذيب الجسيمات المنتشرة؛ بل تتدخل في الطبقات الكهروستاتيكية فتتجمع الجسيمات.","المادة المتأينة تُتلف المخلوط الغروي لا أنها تزيد ثباته.","","المادة المتأينة تؤثر في الطبقات الكهروستاتيكية، فيتغير المخلوط وتترسب جسيماته."]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C1-L1-O13' and q.type = 'mcq' and q.number = 1) and distractor_notes is not distinct from '["المادة المتأينة لا تُذيب الجسيمات المنتشرة؛ بل تتدخل في الطبقات الكهروستاتيكية فتتجمع الجسيمات.","ذكر الكتاب أن المادة المتأينة تُتلف المخلوط الغروي لا أنها تزيد ثباته.","","المادة المتأينة تؤثر في الطبقات الكهروستاتيكية، فيتغير المخلوط وتترسب جسيماته."]'::jsonb;
update public.question_answers set distractor_notes = '["هذا تعريف الاختزال لا الأكسدة.","الأكسدة تتعلق بالإلكترونات وعدد التأكسد، لا بالبروتونات أو العدد الكتلي.","الأكسدة تتضمن دائمًا زيادة في عدد التأكسد، وتعريفها فقد الإلكترونات لا اكتساب الأكسجين.",""]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id = q.objective_id where o.code = 'K3-C4-L1-O01' and q.type = 'mcq' and q.number = 6) and distractor_notes is not distinct from '["هذا تعريف الاختزال لا الأكسدة.","الأكسدة تتعلق بالإلكترونات وعدد التأكسد، لا بالبروتونات أو العدد الكتلي.","الأكسدة تتضمن دائمًا زيادة في عدد التأكسد، وتعريفها في الكتاب بفقد الإلكترونات لا باكتساب الأكسجين.",""]'::jsonb;
commit;
